insert into public.quotes (id, text, author, category, context, source, year, meaning, application) values
  ('q-0005', 'Quand vous êtes dans le sens contraire du courant et que vous nagez vite, vous reculez moins que les autres.', 'Bernard Tapie', 'mindset', null, null, null, 'Tapie décrit une situation défavorable où l''effort ne produit pas de gain visible, mais limite la perte. C''est une définition réaliste de la résistance : on ne gagne pas, on perd moins vite que les autres.', 'En période difficile, mesure-toi à ton secteur plutôt qu''à ton passé. Reculer moins que les autres est une performance, même si ça n''en a pas l''air.'),
  ('q-0006', 'La réussite, c''est un peu de talent, beaucoup de travail et surtout une passion dévorante.', 'Bernard Tapie', 'mindset', null, null, null, 'Tapie pondère trois facteurs et donne le poids principal au dernier : le talent aide, le travail est indispensable, mais c''est l''intensité de l''engagement qui fait tenir la durée nécessaire.', 'Si un projet ne t''anime pas, sois lucide sur ta capacité à fournir l''effort qu''il exigera. Le talent seul ne compense jamais un investissement tiède.'),
  ('q-0007', 'Seul un poisson mort navigue dans le sens du courant.', 'Bernard Arnault', 'mindset', null, null, null, 'Arnault oppose le mouvement propre à la dérive. Suivre le courant demande zéro effort et donne l''impression d''avancer, mais c''est le courant qui décide de la destination.', 'Repère ce que tu fais uniquement parce que ton secteur le fait. Chacun de ces points est une décision que tu as déléguée sans le savoir.'),
  ('q-0008', 'Un bon produit peut durer éternellement.', 'Bernard Arnault', 'mindset', null, null, null, 'Arnault, qui bâtit sur des maisons centenaires, oppose la qualité intrinsèque à la mode. Un produit réellement bon échappe aux cycles ; un produit tendance vit le temps de la tendance.', 'Sur ta prochaine décision produit, demande-toi si elle tiendra dans dix ans. Ce filtre écarte l''essentiel de ce qui paraît urgent aujourd''hui.'),
  ('q-0009', 'Si vous contrôlez votre distribution, vous contrôlez votre image.', 'Bernard Arnault', 'leadership', null, null, null, 'Arnault désigne la distribution comme le point de contrôle de l''image : c''est là que le client rencontre le produit, et cette rencontre détermine la perception plus que n''importe quelle campagne.', 'Regarde les points de contact que tu ne contrôles pas — revendeurs, plateformes, intermédiaires. Ce sont eux qui façonnent ton image, pas ta communication.'),
  ('q-0011', 'La seule façon de faire du bon travail est d''aimer ce que vous faites.', 'Steve Jobs', 'mindset', 'Extrait du passage où Jobs raconte avoir fondé Apple, en être parti, puis y être revenu — et conclut que seule la passion permet de continuer face à l''échec.', 'Discours de remise des diplômes, Université Stanford', 2005, 'Jobs ne dit pas que la passion suffit, mais qu''elle est la seule réserve d''énergie qui tienne quand le travail devient difficile. Sans elle, on abandonne exactement au moment où l''effort commencerait à payer.', 'Repère dans ta semaine la tâche que tu repousses systématiquement. Soit tu trouves l''angle qui la rend intéressante, soit tu la délègues : la traîner encore six mois coûtera plus cher que les deux options.'),
  ('q-0012', 'L''innovation distingue un leader d''un suiveur.', 'Steve Jobs', 'leadership', null, null, null, 'Jobs propose un critère de distinction concret : suivre, c''est reproduire ce qui existe et se battre sur le prix ; innover, c''est créer la référence que les autres devront suivre. La position de leader est une conséquence, pas un titre.', 'Repère dans ton offre ce qui n''existe nulle part ailleurs. Si tu ne trouves rien, tu es en train de te battre sur le prix — que ce soit un choix assumé ou non.'),
  ('q-0013', 'Votre temps est limité, ne le gaspillez pas en vivant la vie de quelqu''un d''autre.', 'Steve Jobs', 'mindset', 'Dans la troisième partie du discours, consacrée à sa maladie et à la mort : Jobs y explique que la conscience du temps limité doit pousser à suivre son propre chemin plutôt que les attentes des autres.', 'Discours de remise des diplômes, Université Stanford', 2005, 'Jobs relie deux idées : le temps est fini, et la plupart des gens le consacrent à satisfaire des attentes qui ne sont pas les leurs. La contrainte n''est pas là pour angoisser, elle sert de critère de tri.', 'Liste ce que tu fais cette semaine parce que tu l''as décidé, et ce que tu fais parce qu''on l''attend de toi. Le rapport entre les deux colonnes t''indique s''il y a quelque chose à corriger.'),
  ('q-0014', 'Qu''est-ce qu''une entreprise ? C''est simplement une idée qui améliore la vie de quelqu''un d''autre.', 'Richard Branson', 'leadership', null, null, null, 'Branson ramène l''entreprise à sa fonction première : elle n''existe pas pour être une structure, mais parce qu''elle résout un problème pour quelqu''un. Tout le reste — statut, organigramme, levée — n''en est que la mécanique.', 'Formule ton activité en une phrase qui commence par « j''aide X à ». Si tu n''y arrives pas sans parler de toi ni de ton produit, le problème que tu résous n''est pas encore net.'),
  ('q-0015', 'Écoutez plus que vous parlez. Personne n''a rien appris en s''entendant parler.', 'Richard Branson', 'leadership', null, null, null, 'Branson pointe une asymétrie d''information : parler ne fait que redistribuer ce que tu sais déjà, écouter est le seul moment où quelque chose entre. Dans une négociation comme dans une réunion, celui qui parle le moins repart avec le plus.', 'En rendez-vous, fixe-toi de poser trois questions avant de présenter quoi que ce soit. Ce que tu apprendras changera souvent la présentation que tu avais préparée.'),
  ('q-0016', 'Seul un imbécile ne change jamais d''avis.', 'Richard Branson', 'mindset', null, null, null, 'Changer d''avis face à un fait nouveau n''est pas de l''inconstance, c''est le fonctionnement normal d''un raisonnement. Ce qui est absurde, c''est de maintenir une position pour ne pas avoir l''air d''avoir eu tort.', 'Quand tu défends une position, demande-toi quel fait te ferait changer d''avis. Si aucun ne te vient, tu n''as pas un raisonnement mais un attachement.'),
  ('q-0017', 'L''opportunité se situe à l''endroit où se trouvent les réclamations et les plaintes.', 'Jack Ma', 'mindset', null, null, null, 'Jack Ma désigne les plaintes comme un gisement : chaque réclamation signale un besoin non satisfait, donc un espace pour celui qui saura y répondre. Ce qui agace les clients d''un secteur est sa liste d''opportunités.', 'Va lire les avis négatifs de tes concurrents. Les motifs qui reviennent décrivent le produit que personne n''a encore fait.'),
  ('q-0019', 'L''échec est simplement l''opportunité de recommencer, cette fois de manière plus pertinente.', 'Henry Ford', 'mindset', null, null, null, 'Ford ajoute une condition à l''idée de recommencer : ce n''est pas la répétition qui paie, c''est la correction. Refaire la même tentative avec plus d''énergie n''est pas une deuxième chance, c''est la même chance gaspillée deux fois.', 'Avant de relancer un projet qui a échoué, écris ce que tu changes précisément. Si tu ne changes rien d''autre que ta détermination, attends-toi au même résultat.'),
  ('q-0020', 'Prenez mes idées, j''en aurai d''autres.', 'Coco Chanel', 'mindset', null, null, null, 'Chanel affirme que la valeur ne réside pas dans une idée isolée mais dans la capacité d''en produire. Protéger jalousement une trouvaille signale qu''on doute d''en avoir une autre ; la générosité est ici une preuve de confiance.', 'Partage une idée que tu gardais pour toi. Observe ce que le retour t''apporte : c''est presque toujours plus que ce que le secret te garantissait.'),
  ('q-0021', 'Prudence n''est que l''euphémisme de peur.', 'Jules Renard', 'mindset', null, null, null, 'Renard soupçonne la prudence d''être une peur qui a trouvé un nom respectable. Toute retenue n''est pas de la lâcheté, mais le mot permet de justifier l''inaction sans l''assumer.', 'Quand tu invoques la prudence, vérifie si tu peux nommer le risque précis que tu évites. Si tu n''y arrives pas, c''est probablement autre chose.'),
  ('q-0022', 'La peur bloque la compréhension intelligente de la vie.', 'Jiddu Krishnamurti', 'mindset', null, null, null, 'Krishnamurti décrit un effet cognitif : la peur réduit le champ d''attention et pousse à des réponses réflexes. On perd la capacité de voir une situation telle qu''elle est.', 'Avant une décision prise sous tension, note ce que tu crains. Nommer la peur restitue une partie de la lucidité qu''elle avait confisquée.'),
  ('q-0023', 'J''ai appris que le courage n''est pas l''absence de peur, mais la capacité de la vaincre.', 'Nelson Mandela', 'mindset', null, 'Un long chemin vers la liberté', 1994, 'Mandela, qui écrit après vingt-sept ans de prison, décrit le courage comme une victoire répétée sur la peur, pas comme une absence de peur. C''est un travail, pas un tempérament.', 'Identifie la conversation que tu évites depuis des semaines. La mener ne supprimera pas l''appréhension, mais c''est l''unique façon de constater qu''elle était surévaluée.'),
  ('q-0025', 'Le seul endroit où le succès vient avant le travail, c''est dans le dictionnaire.', 'Vidal Sassoon', 'mindset', null, null, null, 'Sassoon utilise l''ordre alphabétique pour rappeler une évidence chronologique : dans la réalité, le travail précède toujours le résultat. Le raccourci n''existe que dans le dictionnaire.', 'Quand une méthode promet le résultat sans l''effort, cherche où l''effort a été déplacé. Il est toujours quelque part, souvent chez quelqu''un d''autre.'),
  ('q-0026', 'Les gagnants trouvent des moyens, les perdants des excuses.', 'Franklin D. Roosevelt', 'mindset', null, null, null, 'Roosevelt oppose deux réactions au même obstacle : chercher un chemin, ou chercher une justification. Les deux demandent de l''énergie, une seule produit un résultat.', 'Quand tu t''entends expliquer pourquoi ce n''était pas possible, arrête-toi et cherche une option que tu n''as pas testée. L''explication peut attendre.'),
  ('q-0029', 'Un pessimiste voit la difficulté dans chaque opportunité. Un optimiste voit une opportunité dans chaque difficulté.', 'Winston Churchill', 'mindset', null, null, null, 'Churchill décrit deux lectures de la même réalité. Ce n''est pas une opposition entre lucidité et naïveté : les deux voient la même situation, mais l''un s''arrête à l''obstacle et l''autre cherche ce qu''il ouvre.', 'Face à une contrainte, oblige-toi à écrire une possibilité qu''elle crée. Un budget réduit force à prioriser, un refus libère du temps — encore faut-il le formuler.'),
  ('q-0030', 'Ne cherchez pas d''ascenseur, il n''y en a pas : les entrepreneurs prennent toujours l''escalier !', 'Frédéric Mazzella', 'mindset', null, null, null, 'Mazzella décrit la progression entrepreneuriale comme une succession de marches, sans raccourci disponible. L''ascenseur — le coup de chance, la relation décisive — n''existe pas comme stratégie.', 'Découpe ton objectif en marches franchissables et concentre-toi sur la suivante. Chercher l''ascenseur fait surtout perdre le temps de monter.'),
  ('q-0032', 'Le capitalisme est un pari sur le mouvement : c''est de là que vient le progrès.', 'Alain Minc', 'finance', null, null, null, 'Minc décrit le capitalisme comme un système qui récompense le changement plutôt que la conservation. Cela explique son instabilité autant que sa capacité à produire du progrès.', 'Dans un environnement qui valorise le mouvement, considère l''immobilité comme un choix coûteux. Ne rien changer n''est jamais neutre.'),
  ('q-0033', 'La victoire appartient à celui qui a la persévérance la plus longue.', 'Napoléon Bonaparte', 'mindset', null, null, null, 'Napoléon désigne la durée comme facteur décisif : à forces comparables, c''est celui qui tient le plus longtemps qui l''emporte. La victoire va moins au plus fort qu''au dernier debout.', 'Sur un objectif long, dimensionne ton effort pour pouvoir le tenir des années. Un rythme insoutenable est une défaite programmée, quelle que soit l''intensité de départ.'),
  ('q-0034', 'Toutes les choses semblent réalisables par la volonté et le courage.', 'Napoléon Bonaparte', 'mindset', null, null, null, 'Napoléon associe la volonté au courage : la première fixe la direction, le second permet d''y aller malgré le risque. L''une sans l''autre produit soit des intentions, soit de l''agitation.', 'Devant un projet ambitieux, sépare ce qui te manque en clarté de ce qui te manque en audace. Le remède n''est pas le même.'),
  ('q-0035', 'Se concentrer sur le client rend une entreprise plus résiliente.', 'Jeff Bezos', 'sales', null, null, null, 'Bezos explique pourquoi l''obsession client est une stratégie défensive et pas une posture morale : les concurrents changent, les technologies passent, mais le besoin du client reste un point d''ancrage stable quand tout le reste bouge.', 'Quand tu hésites entre deux directions, demande laquelle un client remarquerait. Si aucune des deux ne se voit de son côté, aucune des deux n''est urgente.'),
  ('q-0037', 'Votre marque est ce que les gens disent de vous lorsque vous n''êtes pas dans la pièce.', 'Jeff Bezos', 'sales', null, null, null, 'Bezos déplace la marque hors du contrôle de l''entreprise : elle n''est pas ce que tu affirmes dans ta communication, mais ce qu''il en reste dans la bouche des autres quand tu n''es plus là pour corriger. Seuls les actes alimentent cette version-là.', 'Demande à trois clients de décrire ton activité à quelqu''un qui ne la connaît pas, et note leurs mots exacts. L''écart avec ta plaquette est ta marque réelle.'),
  ('q-0038', 'Si vous ne voulez jamais être critiqué, ne faites rien de nouveau.', 'Jeff Bezos', 'mindset', null, null, null, 'Bezos présente la critique comme le prix d''entrée de la nouveauté, pas comme un signal d''erreur. Toute chose nouvelle est illisible au début ; la seule façon de n''être jamais critiqué est de ne rien proposer qui sorte de l''attendu.', 'Avant de renoncer à une idée à cause des réactions, sépare deux choses : ce qui est critiqué parce que c''est mauvais, et ce qui est critiqué parce que c''est inhabituel. Seul le premier motif doit te faire changer d''avis.'),
  ('q-0039', 'Observez les clients, pas les concurrents.', 'Jeff Bezos', 'sales', null, null, null, 'Le concurrent te dit où en est le marché aujourd''hui, le client te dit où il ira. Bezos écarte une stratégie réactive : à force de surveiller les autres, on finit par construire ce qu''ils ont déjà décidé à ta place.', 'Pour chaque réunion consacrée à la concurrence, tiens-en une consacrée à un client réel. Si le rapport penche du mauvais côté, ta feuille de route est écrite par quelqu''un d''autre.'),
  ('q-0040', 'Si vous voulez être inventif, vous devez être prêt à échouer.', 'Jeff Bezos', 'mindset', null, null, null, 'L''invention est par nature un processus à taux d''échec élevé : si tout ce que tu lances fonctionne, c''est que tu ne tentes que ce qui est déjà connu. Bezos assume le coût des tentatives ratées comme condition des réussites.', 'Réserve une part explicite de ton temps ou de ton budget aux paris incertains, et juge-la sur l''ensemble, pas cas par cas. Sans cette séparation, chaque échec isolé sera utilisé comme argument pour tout arrêter.'),
  ('q-0041', 'L''échec fait partie intégrante de l''invention.', 'Jeff Bezos', 'mindset', null, null, null, 'Nuance importante par rapport à l''éloge habituel de l''échec : Bezos ne dit pas que l''échec est bon, mais qu''il est indissociable de l''invention. On ne peut pas vouloir l''un en refusant l''autre.', 'Quand une tentative échoue, écris en trois lignes ce que tu sais maintenant et que tu ignorais avant. Si tu ne trouves rien à écrire, c''est là qu''il y a un vrai problème.'),
  ('q-0042', 'Nous sommes têtus sur la vision. Nous sommes flexibles sur les détails.', 'Jeff Bezos', 'leadership', null, null, null, 'Bezos sépare deux niveaux qu''on confond souvent : la direction, qui doit rester stable pour que les efforts s''accumulent, et les moyens, qui doivent bouger dès que les faits l''exigent. Changer de vision à chaque obstacle annule tout le travail accompli.', 'Écris ta vision et tes méthodes sur deux colonnes distinctes. Quand un obstacle apparaît, oblige-toi à chercher la réponse dans la colonne des méthodes avant de toucher à l''autre.'),
  ('q-0043', 'L''échec est une option. Si les choses n''échouent pas, vous n''innovez pas assez.', 'Elon Musk', 'mindset', null, null, null, 'Musk utilise l''échec comme indicateur de niveau d''ambition. Un taux de réussite de 100 % ne signale pas l''excellence mais la prudence : cela veut dire qu''on ne tente que ce dont on connaît déjà l''issue.', 'Regarde tes projets de l''année. Si aucun n''a échoué, ajoute délibérément un pari dont tu ignores le résultat — en calibrant sa taille pour qu''un échec reste absorbable.'),
  ('q-0044', 'La persévérance est très importante. N''abandonnez jamais à moins d''y être obligé.', 'Elon Musk', 'mindset', null, null, null, 'Musk pose une limite à la persévérance, ce qui la distingue de l''obstination : on continue jusqu''à ce qu''un fait rende la poursuite impossible, pas jusqu''à ce que ce soit désagréable. La difficulté n''est pas un motif d''arrêt, l''impossibilité en est un.', 'Définis à l''avance le fait précis qui te ferait arrêter — plus d''argent, hypothèse réfutée, marché inexistant. Sans ce critère, tu confondras découragement passager et vraie impasse.'),
  ('q-0045', 'Beaucoup de choses sont improbables, seules quelques-unes sont impossibles.', 'Elon Musk', 'mindset', null, null, null, 'Musk sépare deux catégories qu''on mélange : l''improbable, qui est une question de probabilité et d''effort, et l''impossible, qui relève des lois physiques. Presque tout ce qu''on renonce à tenter appartient à la première.', 'Quand un objectif te paraît hors d''atteinte, demande-toi s''il viole une loi physique ou seulement une habitude. Dans le second cas, la question devient le prix à payer, pas la faisabilité.'),
  ('q-0046', 'Si les règles vous empêchent de progresser, battez-vous pour les changer.', 'Elon Musk', 'mindset', null, null, null, 'Musk vise les règles héritées, pas la légalité. Beaucoup de contraintes sont des conventions que personne n''a réexaminées ; les traiter comme immuables revient à laisser d''anciens arbitrages gouverner des situations nouvelles.', 'Face à un blocage, distingue la règle légale de la règle d''usage. La première s''accepte, la seconde se discute — encore faut-il avoir fait le tri.'),
  ('q-0047', 'Vous devez être assez motivé pour y arriver. Sinon, vous vous rendrez simplement malheureux.', 'Elon Musk', 'mindset', null, null, null, 'Musk avertit sur le coût personnel de l''ambition. Un projet exigeant sans motivation profonde ne conduit pas à l''échec mais à l''épuisement : on tient, et on en sort abîmé.', 'Avant un engagement lourd, demande-toi si tu le voudrais encore s''il durait trois ans de plus que prévu. Si la réponse est non, réduis l''ambition plutôt que ta santé.'),
  ('q-0048', 'Lorsque quelque chose est suffisamment important, vous le faites même si les chances ne sont pas en votre faveur.', 'Elon Musk', 'mindset', null, null, null, 'Musk inverse le calcul habituel : d''ordinaire on décide selon les chances de succès, ici c''est l''importance qui tranche. Certaines choses méritent d''être tentées même quand la probabilité est mauvaise, précisément parce que l''enjeu est ailleurs.', 'Sépare tes décisions en deux : celles qu''on prend au rendement attendu, et les rares qui comptent quel que soit le résultat. Confondre les deux fait renoncer aux secondes pour de mauvaises raisons.'),
  ('q-0050', 'Se réunir est un début ; rester ensemble est un progrès ; travailler ensemble est la réussite.', 'Henry Ford', 'leadership', null, null, null, 'Ford décompose le collectif en trois étapes distinctes que l''on confond souvent : rassembler des gens, les faire durer ensemble, et obtenir qu''ils produisent quelque chose en commun. Chacune demande un travail différent, et la troisième n''arrive jamais toute seule.', 'Regarde ton équipe et situe-la sur les trois marches. Si vous en êtes à « rester ensemble », le sujet n''est pas le recrutement mais la façon dont le travail est réparti.'),
  ('q-0051', 'Quand tout semble être contre vous, souvenez-vous que l''avion décolle face au vent.', 'Henry Ford', 'mindset', null, null, null, 'L''image est technique et exacte : un avion décolle parce que le vent contraire augmente la portance. Ford ne dit pas que l''adversité est agréable, mais qu''elle fournit précisément la résistance sans laquelle rien ne s''élève.', 'Face à une opposition, cherche ce qu''elle t''oblige à améliorer. Un concurrent sérieux ou un client exigeant révèle des faiblesses qu''un marché facile t''aurait laissé ignorer.'),
  ('q-0052', 'Ce n''est pas l''employeur qui paie les salaires, mais le client.', 'Henry Ford', 'sales', null, null, null, 'Ford remonte à la source réelle de l''argent : l''employeur ne fait que redistribuer ce que le client a accepté de payer. Cela replace chaque poste, même éloigné du commercial, dans une chaîne qui aboutit à quelqu''un qui achète.', 'Demande-toi comment ton travail de la semaine finit par atteindre un client. Si le lien te paraît impossible à tracer, c''est une question à poser, pas une évidence à accepter.'),
  ('q-0053', 'Les deux choses les plus importantes n''apparaissent pas au bilan : sa réputation et ses hommes.', 'Henry Ford', 'leadership', null, null, null, 'Ford désigne deux actifs invisibles comptablement mais décisifs économiquement. Ils se construisent lentement, ne se rachètent pas, et leur perte se voit dans les résultats bien après qu''elle a eu lieu.', 'Avant une décision qui améliore un chiffre à court terme, vérifie ce qu''elle prélève sur ces deux réserves. Ce sont les seules dont l''épuisement n''apparaît nulle part avant qu''il soit tard.'),
  ('q-0054', 'La qualité signifie faire les choses correctement quand personne ne regarde.', 'Henry Ford', 'mindset', null, null, null, 'Ford ramène la qualité à un comportement plutôt qu''à un contrôle. Ce qui est fait sous surveillance ne prouve rien ; le niveau réel d''une organisation est celui qu''elle tient quand personne ne vérifie.', 'Repère un endroit où tu sais que le travail est bâclé faute de contrôle. Corriger l''exigence à cet endroit vaut mieux qu''ajouter une vérification de plus.'),
  ('q-0055', 'Les obstacles sont ces choses effrayantes que vous voyez quand vous détournez les yeux de votre objectif.', 'Henry Ford', 'mindset', null, null, null, 'Ford décrit un effet d''attention : l''obstacle grandit à mesure qu''on le regarde, et il occupe toute la place dès qu''on perd l''objectif de vue. Ce n''est pas un appel à l''ignorer, mais à ne pas en faire le sujet principal.', 'Quand un problème occupe toutes tes réunions, reformule l''ordre du jour autour du résultat visé. L''obstacle redevient alors une des choses à traiter, et non le seul horizon.'),
  ('q-0057', 'Il faut 20 ans pour bâtir une réputation et cinq minutes pour l''anéantir.', 'Warren Buffett', 'finance', null, null, null, 'Buffett oppose deux vitesses : la réputation se construit par accumulation lente et se détruit par événement unique. L''asymétrie est le message — il n''existe aucun capital de confiance assez gros pour absorber une faute grave.', 'Avant une décision limite, pose-toi la question du titre de presse. Si tu n''assumerais pas de la voir écrite noir sur blanc, aucun gain de court terme ne la rend rentable.'),
  ('q-0058', 'Le risque provient de ne pas savoir ce que l''on fait.', 'Warren Buffett', 'finance', null, null, null, 'Buffett redéfinit le risque : ce n''est pas la volatilité d''un actif, c''est l''écart entre ce que tu crois comprendre et ce que tu comprends réellement. Le danger est dans l''ignorance, pas dans le marché.', 'Avant d''engager de l''argent, essaie d''expliquer l''affaire en cinq phrases à quelqu''un d''extérieur. Si tu bloques ou si tu t''abrites derrière du vocabulaire, tu n''es pas prêt à investir.'),
  ('q-0059', 'Achetez seulement des choses que vous seriez parfaitement heureux de posséder si le marché s''effondrait pendant dix ans.', 'Warren Buffett', 'finance', 'Buffett y explique qu''il ne faut acheter que des entreprises dont on accepterait de ne plus jamais voir le cours, preuve qu''on les détient pour ce qu''elles produisent et non pour les revendre.', 'Lettre aux actionnaires de Berkshire Hathaway', 1996, 'Test de conviction déguisé en règle d''achat : si l''idée de ne plus pouvoir revendre pendant dix ans te met mal à l''aise, c''est que tu comptais sur la revente et non sur ce que l''actif produit. Buffett sépare l''investissement de la spéculation.', 'Avant un engagement important, demande-toi si tu le maintiendrais sans possibilité d''en sortir pendant plusieurs années. Un « non » ne t''interdit pas d''y aller, mais il t''oblige à savoir que tu paries sur la sortie.'),
  ('q-0060', 'Notre horizon d''investissement préféré est : pour toujours.', 'Warren Buffett', 'finance', 'Formulé en commentant l''achat de Coca-Cola : Buffett y distingue les investisseurs qui gardent leurs meilleures entreprises de ceux qui s''en séparent dès qu''elles réussissent.', 'Lettre aux actionnaires de Berkshire Hathaway', 1988, 'La phrase ne dit pas qu''il ne faut jamais vendre, mais qu''on n''achète pas en ayant déjà la sortie en tête. L''intention de garder change les critères de sélection : on regarde la solidité durable plutôt que le prochain mouvement de prix.', 'Quand tu choisis un partenaire, un outil ou un employeur, juge-le sur dix ans plutôt que sur l''année en cours. Les critères qui ressortent ne sont pas du tout les mêmes.'),
  ('q-0061', 'La bourse est un moyen de transférer l''argent des impatients vers les patients.', 'Warren Buffett', 'finance', null, null, null, 'L''impatience a un coût mesurable : vendre dans la panique et acheter dans l''euphorie revient à céder bas et à payer haut, de façon répétée. Buffett décrit un transfert de richesse entre deux comportements, pas entre deux niveaux d''intelligence.', 'Décide de ton horizon avant d''engager quoi que ce soit, et écris-le. C''est cette décision prise à froid qui te tiendra le jour où les cours bougeront et où tu auras envie d''agir dans l''urgence.'),
  ('q-0062', 'Le meilleur investissement que vous puissiez faire, c''est de miser sur vos propres capacités.', 'Warren Buffett', 'finance', null, null, null, 'Buffett rappelle qu''une compétence ne s''imprime pas, ne se dévalue pas et échappe à l''impôt. Ce qui se passe dans ta tête est le seul actif que personne ne peut te reprendre, et il produit des rendements pendant toute une carrière.', 'Bloque dans ton agenda un créneau hebdomadaire pour une compétence qui te servira dans dix ans — écrire, négocier, lire un bilan. Traite-le comme un rendez-vous client, pas comme du temps disponible.'),
  ('q-0063', 'Tous nos rêves peuvent devenir réalité si nous avons le courage de les poursuivre.', 'Walt Disney', 'mindset', null, null, null, 'Disney conditionne la réalisation au courage plutôt qu''aux moyens. Le rêve ne suffit pas et ne se réalise pas seul : il exige d''accepter le risque de l''exposer et de le poursuivre.', 'Prends le projet dont tu parles depuis des années et fixe-lui une première échéance publique. L''engagement devant témoin est ce qui transforme l''envie en obligation.'),
  ('q-0065', 'La manière de commencer est d''arrêter de parler et de commencer à faire.', 'Walt Disney', 'mindset', null, null, null, 'Disney tranche l''illusion de la préparation infinie : à un moment, réfléchir devient un moyen de ne pas commencer. Le passage à l''acte n''est pas la dernière étape de la réflexion, c''en est la sortie.', 'Si tu prépares un projet depuis plus d''un mois sans rien produire, livre une version imparfaite cette semaine. Elle t''apprendra plus que le mois suivant de préparation.'),
  ('q-0069', 'La patience est un élément clé de la réussite.', 'Bill Gates', 'mindset', null, 'La Route du futur', 1995, 'Gates place la patience parmi les compétences plutôt que parmi les vertus. Les résultats significatifs arrivent après un délai pendant lequel rien ne semble bouger — et c''est ce délai qui élimine la majorité.', 'Fixe à ton projet une durée minimale avant évaluation, et tiens-la. Juger trop tôt revient à conclure sur un échantillon qui ne dit rien.'),
  ('q-0070', 'Le succès est un mauvais professeur. Il pousse les gens intelligents à croire qu''ils sont infaillibles.', 'Bill Gates', 'mindset', null, 'La Route du futur', 1995, 'Gates identifie le danger propre à la réussite : elle valide rétrospectivement des décisions qui pouvaient être mauvaises mais chanceuses. On en tire alors des règles fausses, appliquées avec d''autant plus de confiance.', 'Après un succès, examine ce qui relevait de ta décision et ce qui relevait des circonstances. C''est le seul moyen de savoir ce qui est reproductible.'),
  ('q-0072', 'Pour gagner gros, il faut parfois prendre de gros risques.', 'Bill Gates', 'finance', null, null, null, 'Gates rappelle une relation mécanique entre exposition et rendement : sans prise de risque, le résultat reste dans la moyenne. Ce n''est pas un encouragement à l''imprudence mais un rappel du prix des gains importants.', 'Avant un pari conséquent, définis le montant que tu peux perdre sans mettre en danger le reste. Le risque se dimensionne, il ne se subit pas.'),
  ('q-0073', 'Célébrer le succès, c''est bien, mais il est plus important de tirer les leçons de l''échec.', 'Bill Gates', 'mindset', null, null, null, 'Gates hiérarchise les sources d''apprentissage. Le succès ne dit pas quel facteur a compté, puisque tout a marché ; l''échec, lui, désigne précisément ce qui n''a pas fonctionné.', 'Instaure une revue systématique après chaque échec, avec la même rigueur que tes bilans de réussite. La plupart des organisations font l''inverse, et apprennent peu.'),
  ('q-0074', 'Le plus grand risque est de ne prendre aucun risque.', 'Mark Zuckerberg', 'mindset', null, null, null, 'Zuckerberg décrit un risque invisible : dans un environnement qui change vite, l''immobilité garantit d''être dépassé. Ne rien tenter paraît prudent mais expose à la seule issue certaine, l''obsolescence.', 'Compare ce que tu risques en tentant quelque chose et ce que tu risques en ne changeant rien pendant trois ans. Le second calcul est rarement fait.'),
  ('q-0075', 'Si vous ne cassez rien, c''est que vous n''avancez pas assez vite.', 'Mark Zuckerberg', 'mindset', null, null, null, 'Zuckerberg utilise la casse comme indicateur de vitesse. Si rien ne se casse jamais, c''est qu''on n''expérimente pas — mais la formule suppose un contexte où l''erreur est réparable, ce qui n''est pas vrai partout.', 'Distingue les zones où l''erreur se corrige des zones où elle est irréversible. Accélère franchement sur les premières, ralentis délibérément sur les secondes.'),
  ('q-0076', 'La chose la plus importante est de garder votre équipe aussi petite que possible.', 'Mark Zuckerberg', 'leadership', null, null, null, 'Zuckerberg lie la taille à la vitesse de décision. Chaque personne ajoutée multiplie les liens de coordination, ce qui ralentit l''ensemble bien avant que la capacité de production augmente.', 'Avant de recruter, vérifie que le problème est un manque de bras et non un manque de clarté. Ajouter quelqu''un à une organisation confuse aggrave la confusion.'),
  ('q-0077', 'Mon objectif n''a jamais été de créer une entreprise, mais de bâtir quelque chose susceptible de changer le monde.', 'Mark Zuckerberg', 'leadership', null, null, null, 'Zuckerberg place la finalité avant la structure : l''entreprise est le moyen choisi pour réaliser quelque chose, pas l''objectif. Inverser les deux conduit à optimiser l''outil en oubliant ce qu''il devait servir.', 'Écris ce que tu veux voir exister dans le monde, indépendamment de ta structure actuelle. Si ta stratégie ne sert pas cette phrase, elle sert autre chose.'),
  ('q-0079', 'L''échec est un excellent enseignant et chaque erreur a une leçon à offrir.', 'Oprah Winfrey', 'mindset', null, null, null, 'Winfrey pose l''échec comme un enseignement systématique, à condition de l''examiner. L''erreur ne devient une leçon que si elle est analysée ; sinon elle n''est qu''un coût sans contrepartie.', 'Tiens une trace écrite de tes erreurs et de ce que tu en as tiré. Relire cette liste une fois par trimestre évite de repayer deux fois la même leçon.'),
  ('q-0080', 'Entourez-vous seulement de personnes qui vont vous élever plus haut.', 'Oprah Winfrey', 'mindset', null, null, null, 'Winfrey décrit un effet d''entourage : les personnes qui nous côtoient calibrent ce que nous jugeons normal, ambitieux ou irréaliste. Cette influence agit sans qu''on la remarque, ce qui la rend difficile à corriger.', 'Regarde qui tu vois le plus souvent et ce que ces personnes attendent de la vie. Si aucune ne te tire vers le haut, la question n''est pas de les écarter mais d''en ajouter d''autres.'),
  ('q-0081', 'Vous ne devenez pas ce que vous voulez, vous devenez ce que vous croyez.', 'Oprah Winfrey', 'mindset', null, null, null, 'Winfrey distingue le désir de la croyance. Vouloir quelque chose sans se croire capable de l''obtenir produit des tentatives molles, qui échouent et confirment la croyance de départ.', 'Quand un objectif ne bouge pas, demande-toi si tu le crois réellement atteignable. Si non, cherche un premier palier que tu crois possible : c''est lui qui déplacera la croyance.'),
  ('q-0085', 'Celui qui n''a pas d''objectifs ne risque pas de les atteindre.', 'Sun Tzu', 'mindset', null, null, null, 'Sans objectif défini, il n''y a rien à atteindre ni à évaluer : l''activité se poursuit sans qu''on puisse dire si elle réussit. L''absence de cible n''est pas de la souplesse, c''est l''impossibilité de mesurer.', 'Formule ton objectif avec un chiffre et une échéance. Sans ces deux éléments, tu ne pourras jamais savoir si tu progresses ou si tu occupes le terrain.'),
  ('q-0086', 'Le bon général a gagné la bataille avant de l''engager.', 'Sun Tzu', 'leadership', null, 'L''Art de la guerre, chapitre IV', null, 'Sun Tzu situe la victoire avant l''affrontement : elle se joue dans la préparation, le choix du terrain et le rapport de forces. L''engagement ne fait que constater ce qui a été décidé en amont.', 'Avant une négociation, prépare tes options de repli et renseigne-toi sur celles de l''autre. Ce travail préalable pèse plus lourd que ton aisance dans la pièce.'),
  ('q-0087', 'Un grand dirigeant commande par l''exemple et non par la force.', 'Sun Tzu', 'leadership', null, null, null, 'Sun Tzu distingue deux moyens d''obtenir l''obéissance : la contrainte, qui produit une exécution minimale et cesse dès que la surveillance s''arrête, et l''exemple, qui crée de l''adhésion durable.', 'Regarde ce que tu exiges de ton équipe et que tu ne t''appliques pas. Chacun de ces écarts coûte de la crédibilité, même quand personne ne le dit.'),
  ('q-0088', 'Connais l''adversaire et surtout connais-toi toi-même et tu seras invincible.', 'Sun Tzu', 'mindset', null, 'L''Art de la guerre, chapitre III', null, 'Sun Tzu associe deux connaissances complémentaires, et insiste sur la seconde : connaître l''adversaire ne sert à rien si l''on surestime ses propres moyens. L''aveuglement sur soi est la faille la plus fréquente.', 'Avant un engagement important, liste honnêtement tes faiblesses aux côtés de celles de ton concurrent. La seconde liste est facile à faire, la première est celle qui compte.'),
  ('q-0089', 'Le commencement est beaucoup plus que la moitié de l''objectif.', 'Aristote', 'mindset', null, null, null, 'Aristote accorde au commencement un poids disproportionné : c''est l''étape où l''on franchit l''inertie, où les orientations se fixent et où la plupart des projets meurent. Une fois lancé, le reste devient de l''exécution.', 'Consacre plus de soin au démarrage qu''à la planification de la fin. Les décisions prises au début se paient ou se rentabilisent pendant toute la suite.'),
  ('q-0090', 'C''est par l''expérience que la science et l''art font leur progrès.', 'Aristote', 'mindset', null, null, null, 'Aristote place l''expérience à la source du savoir : les principes se dégagent de l''observation répétée, pas de la spéculation. La pratique n''illustre pas la théorie, elle la produit.', 'Avant de construire une méthode, accumule des cas concrets. Une règle tirée de trois situations réelles vaut mieux qu''un cadre théorique élégant.'),
  ('q-0094', 'Faites le premier pas sur le chemin de la foi. Vous n''avez pas à le parcourir entièrement, juste à faire le premier pas.', 'Martin Luther King', 'mindset', null, null, null, 'King décrit une progression qui ne demande pas de voir l''ensemble : le premier pas suffit, et il révèle le suivant. C''est une méthode pour agir malgré l''incertitude.', 'Quand tu ne vois pas tout le chemin, fais quand même le premier pas. La visibilité augmente à mesure qu''on avance, jamais avant.'),
  ('q-0097', 'Tout ce que tu feras sera dérisoire, mais il est essentiel que tu le fasses.', 'Mahatma Gandhi', 'mindset', null, null, null, 'Gandhi tient ensemble deux idées contradictoires : l''action individuelle pèse peu à l''échelle du monde, et elle reste indispensable. L''insignifiance apparente n''est pas une raison de s''abstenir.', 'Quand l''ampleur d''un problème te décourage, choisis la part qui te concerne directement. L''inaction par découragement est le seul choix qui ne change rien.'),
  ('q-0098', 'Je ne crains pas l''homme qui a pratiqué 10 000 coups une fois, mais celui qui a pratiqué un coup 10 000 fois.', 'Bruce Lee', 'mindset', null, null, null, 'Lee oppose l''étendue à la profondeur. Connaître dix mille techniques superficiellement ne produit aucune maîtrise ; répéter la même dix mille fois crée un automatisme fiable sous pression. C''est la répétition, pas la variété, qui rend redoutable.', 'Choisis le geste central de ton métier — une présentation, un appel, un diagnostic — et travaille-le spécifiquement. La diversité viendra après la solidité, pas avant.'),
  ('q-0099', 'Connaître ne suffit pas, il faut savoir appliquer. La volonté ne suffit pas, il faut savoir agir.', 'Bruce Lee', 'mindset', null, null, null, 'Lee ferme deux échappatoires courantes : savoir sans appliquer reste théorique, et vouloir sans agir reste une intention. La connaissance et la motivation ne sont que des préalables — ni l''une ni l''autre ne produit de résultat.', 'Repère une chose que tu sais devoir faire depuis des mois. Le problème n''est ni l''information ni l''envie : traite-le comme une question d''exécution, pas de compréhension.'),
  ('q-0100', 'Ne crains pas l''échec. Ce n''est pas l''échec, mais le manque d''ambition qui est un crime.', 'Bruce Lee', 'mindset', null, null, null, 'Lee déplace le blâme : l''échec est une conséquence normale de la tentative, tandis que l''absence d''ambition prive de tout résultat possible. Ce n''est pas le résultat qui est condamnable, c''est de n''avoir rien visé.', 'Quand tu fixes un objectif, vérifie qu''il t''oblige à progresser. Un objectif atteint sans effort n''était pas un objectif, c''était une prévision.'),
  ('q-0101', 'Il n''y a pas de limites. Il n''y a que des paliers, et tu ne dois pas t''y arrêter.', 'Bruce Lee', 'mindset', null, null, null, 'Lee décrit le plateau : un palier où la progression s''arrête alors que le travail continue. Ce n''est pas une limite mais une étape — s''y installer par confort est ce qui la transforme en plafond.', 'Si tes résultats stagnent malgré un travail constant, change de méthode plutôt que d''intensité. Un plateau ne se franchit pas en poussant plus fort sur le même levier.'),
  ('q-0102', 'C''est dur d''échouer, mais c''est pire de n''avoir jamais essayé de réussir.', 'Theodore Roosevelt', 'mindset', null, null, null, 'Roosevelt compare deux regrets de nature différente. L''échec est un coût ponctuel, qu''on solde et dont on tire quelque chose ; le renoncement, lui, ne se solde jamais puisqu''on ne saura jamais ce qu''il aurait donné.', 'Face à une hésitation, demande-toi ce que tu penseras de ce choix dans cinq ans. L''échec se raconte, l''abandon se rumine.'),
  ('q-0103', 'Le seul homme à ne jamais faire d''erreurs est celui qui ne fait rien.', 'Theodore Roosevelt', 'mindset', null, null, null, 'L''absence d''erreur n''est pas un indicateur de compétence mais d''exposition. Un dossier parfaitement propre signale le plus souvent qu''on n''a rien tenté qui pouvait mal tourner.', 'Si personne dans ton équipe ne se trompe jamais, cherche pourquoi : soit les sujets sont trop faciles, soit les erreurs sont cachées. Les deux méritent d''être traités.'),
  ('q-0105', 'Parlez doucement, et tenez un gros bâton, vous irez loin.', 'Theodore Roosevelt', 'leadership', null, null, null, 'Roosevelt décrit un rapport de force silencieux : la fermeté ne s''annonce pas, elle se démontre. Celui qui doit hausser le ton révèle qu''il n''a rien derrière ; celui qui a les moyens d''agir peut se permettre de rester calme.', 'En négociation, prépare ta solution de repli avant d''entrer dans la pièce. C''est elle qui te permettra de rester posé, pas ta capacité à te contenir.'),
  ('q-0106', 'N''ayez pas peur d''échouer. Ayez peur de ne pas essayer.', 'Michael Jordan', 'mindset', null, null, null, 'Jordan hiérarchise deux peurs. L''échec est un coût connu et limité ; l''absence de tentative est un coût invisible et illimité, puisqu''il porte sur tout ce qui n''aura pas eu lieu.', 'Quand tu hésites, chiffre les deux scénarios : ce que coûte un échec, et ce que coûte de ne pas savoir. Le second est presque toujours sous-estimé parce qu''il ne se voit pas.'),
  ('q-0107', 'Je peux accepter l''échec, tout le monde échoue dans quelque chose. Mais je ne peux pas accepter de ne pas essayer.', 'Michael Jordan', 'mindset', null, null, null, 'Jordan sépare le résultat de l''engagement. Il accepte de perdre parce que cela fait partie du jeu, mais pas de ne pas jouer — la première chose est un aléa, la seconde une décision.', 'Après un échec, pose-toi une seule question : ai-je vraiment essayé ? Si oui, il n''y a rien à se reprocher. Si non, c''est là qu''est le sujet.'),
  ('q-0108', 'Plus je me prépare, plus j''ai de chance.', 'Michael Jordan', 'mindset', null, null, null, 'Jordan démonte l''idée de chance : ce qu''on appelle ainsi est souvent une préparation qui permet de saisir une occasion que d''autres n''auraient pas su exploiter. La fréquence de la « chance » suit celle de la préparation.', 'Avant une opportunité prévisible — un rendez-vous, un appel d''offres — prépare le scénario favorable autant que le défavorable. Être prêt à réussir demande autant de travail qu''être prêt à encaisser.'),
  ('q-0110', 'Le talent fait gagner les matches, mais le travail d''équipe et l''intelligence font gagner des tournois.', 'Michael Jordan', 'leadership', null, null, null, 'Jordan distingue la performance ponctuelle de la performance durable. Le talent individuel suffit sur un match ; tenir une saison entière exige une organisation collective que le talent seul ne remplace pas.', 'Si ton activité repose sur une personne exceptionnelle, tu gagnes des matchs. Construis les processus qui permettront de gagner sans elle : c''est ce qui distingue une performance d''une entreprise.'),
  ('q-0113', 'Il n''y a qu''une réponse à la défaite, et c''est la victoire.', 'Winston Churchill', 'mindset', null, null, null, 'Churchill, s''exprimant en temps de guerre, refuse toute réponse intermédiaire à la défaite : ni justification, ni renoncement négocié. La seule sortie est de reprendre l''objectif jusqu''à l''atteindre.', 'Après un échec net, refuse de réviser l''objectif à la baisse dans l''immédiat. Attends d''avoir retrouvé du terrain pour décider s''il mérite d''être ajusté.'),
  ('q-0115', 'Pour s''améliorer, il faut changer. Donc, pour être parfait, il faut avoir changé souvent.', 'Winston Churchill', 'mindset', null, null, null, 'Churchill fait du changement la condition même de l''amélioration, avec une conclusion volontairement provocante : viser un état parfait suppose d''accepter une remise en cause permanente, donc de renoncer à la stabilité.', 'Programme une remise en question régulière de tes méthodes, même celles qui fonctionnent. C''est précisément celles-là qu''on ne réexamine jamais.'),
  ('q-0116', 'Celui qui déplace la montagne, c''est celui qui commence à enlever les petites pierres.', 'Confucius', 'mindset', null, null, null, 'L''image ramène une tâche écrasante à sa seule porte d''entrée praticable. Personne ne déplace une montagne ; on déplace une pierre, puis une autre. Ce qui distingue celui qui y arrive n''est pas la force, c''est d''avoir commencé petit.', 'Face à un chantier qui te paralyse, identifie la plus petite action possible et fais-la aujourd''hui. L''objectif n''est pas l''avancement, c''est de sortir de l''immobilité.'),
  ('q-0117', 'Celui qui ne progresse pas chaque jour, recule chaque jour.', 'Confucius', 'mindset', null, null, null, 'Il n''y a pas de position neutre : les compétences se démodent, les concurrents avancent, les marchés changent. Rester identique produit donc un recul relatif, même sans rien faire de mal.', 'Choisis une compétence de ton métier et consacre-lui un temps fixe chaque semaine. Le rythme compte davantage que la durée — c''est la régularité qui compense la dérive.'),
  ('q-0118', 'Un homme est grand non pas parce qu''il n''a pas échoué ; un homme est grand parce que l''échec ne l''a pas arrêté.', 'Confucius', 'mindset', null, null, null, 'La grandeur ne se mesure pas à un parcours sans faute, qui signalerait surtout peu de prises de risque, mais à la capacité de continuer après. L''échec est traité comme un événement, pas comme un verdict.', 'Quand un revers te fait douter de ta légitimité, regarde le parcours de ceux que tu admires. Tu y trouveras les mêmes accidents, simplement moins racontés.'),
  ('q-0120', 'Ne vous souciez pas de n''être pas remarqué ; cherchez plutôt à faire quelque chose de remarquable.', 'Confucius', 'mindset', null, null, null, 'Inversion de priorité : chercher la reconnaissance conduit à soigner l''apparence, chercher à faire quelque chose de remarquable conduit à soigner le fond. La reconnaissance suit le second chemin, jamais le premier.', 'Avant de communiquer sur un travail, demande-toi s''il mérite l''attention que tu veux attirer. Si la réponse est non, l''énergie va dans le travail, pas dans l''annonce.'),
  ('q-0121', 'Exige beaucoup de toi-même et attends peu des autres.', 'Confucius', 'mindset', null, null, null, 'Confucius répartit l''exigence de façon asymétrique : maximale envers soi, modérée envers les autres. C''est la seule combinaison qui produise à la fois de la progression personnelle et des relations tenables.', 'Quand quelque chose échoue à cause d''autrui, cherche d''abord ta part. Ce n''est pas une question de morale : c''est la seule part sur laquelle tu peux agir.'),
  ('q-0122', 'Dans les affaires, les grandes choses ne sont jamais faites par une seule personne.', 'Steve Jobs', 'leadership', null, null, null, 'Correctif au mythe du fondateur solitaire. Jobs, à qui on attribue volontiers les produits d''Apple, insiste sur le fait qu''aucun d''eux n''aurait existé sans des équipes entières — et que reconnaître cela n''enlève rien à celui qui dirige.', 'Sur ton prochain succès, nomme publiquement les personnes qui l''ont rendu possible. Ce n''est pas de la politesse : c''est ce qui décide si elles s''investiront autant la fois suivante.'),
  ('q-0123', 'Les gens qui sont assez fous pour penser qu''ils peuvent changer le monde sont ceux qui le font.', 'Steve Jobs', 'mindset', 'Signature de la campagne « Think Different » qui a marqué le retour de Jobs à la tête d''Apple — sa rédaction exacte est disputée entre lui et l''agence TBWA\Chiat\Day, mais la phrase reste associée à son retour.', 'Campagne publicitaire « Think Different », Apple', 1997, 'L''idée n''est pas que la folie soit une qualité, mais que juger un projet impossible est une prédiction, pas un constat. Ceux qui ignorent cette prédiction sont statistiquement les seuls à pouvoir la démentir.', 'Quand on te dit qu''une chose est impossible, demande sur quoi repose ce jugement — une contrainte physique, ou l''habitude. La réponse change complètement ce que tu dois en faire.'),
  ('q-0124', 'La simplicité est la sophistication ultime.', 'Steve Jobs', 'mindset', 'Apparue sur une brochure du premier Apple II avant de devenir une formule répétée par Jobs pendant des décennies. Elle est aussi, à tort, très souvent attribuée à Léonard de Vinci — aucune trace de cette phrase n''existe dans ses écrits.', 'Brochure publicitaire de l''Apple II, Apple', 1977, 'La simplicité dont parle Jobs n''est pas l''absence d''effort mais son aboutissement : il faut avoir compris un problème en profondeur pour pouvoir en retirer tout l''accessoire. Le compliqué est souvent le signe d''une réflexion inachevée.', 'Prends ta présentation ou ta page produit et supprime la moitié. Ce qui résiste à la coupe est ton vrai message ; ce que tu remets ensuite par réflexe mérite d''être rediscuté.'),
  ('q-0125', 'Je suis convaincu qu''environ la moitié de ce qui sépare les entrepreneurs qui réussissent de ceux qui échouent, c''est la pure persévérance.', 'Steve Jobs', 'mindset', null, null, null, 'Jobs chiffre volontairement bas : il ne dit pas que la persévérance suffit, mais qu''elle pèse autant que le talent, la vision et le financement réunis. C''est la seule variable qui ne dépend d''aucune circonstance extérieure.', 'Quand un projet devient pénible, distingue « ça ne marche pas » de « c''est difficile ». Le premier justifie d''arrêter, le second est simplement l''étape où la plupart abandonnent.'),
  ('q-0126', 'Innover, c''est savoir abandonner des milliers de bonnes idées.', 'Steve Jobs', 'mindset', null, null, null, 'Jobs décrit l''innovation comme un travail de refus. Le problème n''est pas de manquer d''idées, c''est d''en avoir trop de bonnes : chacune consomme de l''attention, et les garder toutes revient à n''en réussir aucune.', 'Écris tes cinq prochaines idées, garde-en une, et note pourquoi tu écartes les quatre autres. Le fait de justifier les refus t''évite de les reprendre dans trois mois par simple nostalgie.'),
  ('q-0127', 'Cela n''a aucun sens d''embaucher des gens intelligents et de leur dire quoi faire.', 'Steve Jobs', 'leadership', 'Sa dernière interview publique, où il détaille sa philosophie du management : diriger par les idées plutôt que par la hiérarchie.', 'Conférence D8, entretien avec Walt Mossberg et Kara Swisher', 2010, 'Jobs relève une incohérence coûteuse : recruter des gens compétents puis leur dicter la méthode revient à payer une expertise qu''on s''interdit d''utiliser.', 'Sur ta prochaine délégation, donne l''objectif et les contraintes, pas la marche à suivre. Si tu ne peux pas, le problème est le recrutement, pas la délégation.'),
  ('q-0129', 'Ne quittez jamais les flux de trésorerie des yeux, car c''est le sang de l''entreprise.', 'Richard Branson', 'finance', null, null, null, 'Branson distingue rentabilité et solvabilité. On peut être rentable sur le papier et mourir quand même : ce qui tue une entreprise, ce n''est pas de perdre de l''argent, c''est de ne plus en avoir en caisse au bon moment.', 'Tiens à jour ton nombre de mois de trésorerie devant toi, et regarde-le chaque semaine au même titre que ton chiffre d''affaires. En dessous de trois mois, ça devient ta priorité numéro un.'),
  ('q-0130', 'La complexité est votre ennemie. N''importe quel imbécile peut compliquer quelque chose.', 'Richard Branson', 'mindset', null, null, null, 'La complexité est le réglage par défaut : elle s''installe seule, par ajouts successifs, sans que personne l''ait décidée. La simplicité, elle, demande une décision explicite et le courage de retirer.', 'Prends un processus interne et compte les étapes. Chacune doit pouvoir être justifiée par ce qu''elle empêche ; celles qui existent « parce que c''est comme ça » sont des candidates à la suppression.'),
  ('q-0131', 'Les opportunités, c''est comme les autobus, il y en a toujours un autre qui arrive.', 'Richard Branson', 'mindset', null, null, null, 'Branson relativise le coût d''une occasion manquée. Traiter chaque opportunité comme unique conduit à accepter dans l''urgence des choses qu''on aurait refusées à froid ; la rareté est plus souvent ressentie que réelle.', 'Quand une proposition s''accompagne d''une pression temporelle forte, demande-toi si l''urgence sert ton intérêt ou celui de l''autre. C''est rarement les deux.'),
  ('q-0132', 'Si vous vous occupez de votre personnel, ils s''occuperont de vos clients.', 'Richard Branson', 'sales', null, null, null, 'Chaîne de causalité, pas déclaration de bonnes intentions : la qualité du service client est produite par des gens, et personne ne traite bien un client s''il est lui-même mal traité. Le soin apporté à l''équipe ressort à l''autre bout.', 'Avant de lancer un plan d''amélioration du service client, demande à ton équipe ce qui l''empêche de bien faire son travail. La réponse coûte souvent moins cher que le plan.'),
  ('q-0133', 'Vous devez prendre des risques si vous voulez réussir.', 'Richard Branson', 'mindset', null, null, null, 'Rappel du fonctionnement de base : un résultat inhabituel suppose une prise d''exposition. Éviter tout risque garantit surtout la moyenne, ce qui reste un choix — mais un choix qu''il vaut mieux faire consciemment.', 'Distingue les risques réversibles des irréversibles. Les premiers se prennent vite et s''annulent ; les seconds méritent le temps d''analyse que la plupart des gens dépensent sur les premiers.'),
  ('q-0134', 'Parfois, la décision la plus risquée que vous puissiez prendre est de ne rien faire.', 'Richard Branson', 'mindset', null, null, null, 'L''inaction paraît neutre alors qu''elle ne l''est pas : ne rien décider, c''est laisser la situation décider à ta place, sans en assumer le choix. Branson rappelle que l''immobilité a un coût, simplement moins visible.', 'Sur une décision que tu repousses, chiffre ce que coûtent trois mois de plus d''attente. Comparé au risque de te tromper, le résultat est souvent surprenant.'),
  ('q-0135', 'Lancer une entreprise, c''est résoudre des problèmes avec succès.', 'Richard Branson', 'leadership', null, null, null, 'Définition dépouillée de l''entrepreneuriat : pas une posture, pas un statut, mais une activité de résolution de problèmes qui recommence en permanence. Ce qui change avec le temps, c''est la taille des problèmes, pas leur présence.', 'Si l''accumulation de problèmes te donne le sentiment d''échouer, souviens-toi que c''est la description du poste. La bonne question n''est pas « pourquoi encore un problème » mais « est-ce un problème plus intéressant que ceux d''il y a un an ».'),
  ('q-0136', 'Réussir en affaires, c''est avant tout créer des liens.', 'Richard Branson', 'sales', null, null, null, 'Branson replace la relation avant la transaction. Les contrats se signent entre sociétés mais se décident entre personnes, et la qualité de ces liens détermine ce qui se passe quand un imprévu survient.', 'Consacre chaque semaine un moment à une relation professionnelle sans objectif immédiat. Les liens créés en période calme sont ceux sur lesquels on peut compter en période tendue.'),
  ('q-0137', 'Le bonheur est l''ingrédient secret des entreprises prospères.', 'Richard Branson', 'leadership', null, null, null, 'Argument économique déguisé en évidence : des gens satisfaits restent, apprennent et prennent des initiatives, ce qui coûte beaucoup moins cher que de recruter et former en continu. Le bien-être n''est pas un supplément, c''est un facteur de performance.', 'Regarde ton taux de départs sur douze mois et multiplie-le par le coût d''un remplacement. Le chiffre obtenu est le budget que tu as déjà, sans le savoir, pour améliorer les conditions de travail.'),
  ('q-0138', 'Ce qu''on obtient en atteignant nos objectifs n''est pas aussi important que ce que l''on devient en les atteignant.', 'Zig Ziglar', 'mindset', null, null, null, 'Ziglar déplace la valeur de l''objectif vers le chemin. Le résultat s''obtient une fois et se périme ; les compétences et la discipline acquises en route restent disponibles pour tout ce qui suivra.', 'Écris à côté de ton objectif la personne qu''il t''oblige à devenir — plus rigoureux, plus à l''aise à l''oral, plus endurant. C''est ce qui te restera même si l''objectif n''est pas atteint.'),
  ('q-0139', 'La pire décision de toutes est celle que l''on n''a pas prise.', 'Zig Ziglar', 'mindset', null, null, null, 'Ziglar range l''indécision parmi les décisions, et la classe en dernier. Ne pas trancher revient à choisir le statu quo tout en gardant l''illusion d''avoir encore le choix — avec le coût du retard en plus.', 'Fixe une date limite aux décisions que tu repousses. Passé ce délai, tranche avec l''information disponible : dans la plupart des cas, attendre n''apporte pas de certitude supplémentaire.'),
  ('q-0140', 'La meilleure arme de persuasion que tu possèdes dans ton arsenal est l''intégrité.', 'Zig Ziglar', 'sales', null, null, null, 'Ziglar traite l''intégrité comme un outil commercial, pas comme une contrainte morale. Une technique convainc une fois ; la réputation d''être honnête fait travailler quelqu''un pour toi dans toutes les conversations où tu n''es pas.', 'Sur ta prochaine vente, dis explicitement à quoi ton offre ne convient pas. Le gain de crédibilité dépasse presque toujours l''affaire que tu perds ainsi.'),
  ('q-0141', 'Si l''échec vous apprend quelque chose, vous n''êtes pas vraiment perdant.', 'Zig Ziglar', 'mindset', null, null, null, 'Redéfinition du perdant : ce n''est pas celui qui échoue, c''est celui qui échoue sans rien en retirer. L''échec devient un coût de formation dès lors qu''on en extrait quelque chose de réutilisable.', 'Après un revers, écris la leçon sous forme de règle applicable la prochaine fois. « J''aurais dû mieux préparer » n''est pas une leçon ; « je vérifie le budget avant le deuxième rendez-vous » en est une.'),
  ('q-0142', 'Gagner n''est pas tout, mais l''effort qu''il faut fournir l''est.', 'Zig Ziglar', 'mindset', null, null, null, 'Ziglar déplace le mérite du résultat vers ce qu''il exige. Le score dépend de circonstances qu''on ne contrôle pas ; l''effort consenti, lui, est entièrement de ton ressort et reste acquis quel que soit l''issue.', 'Juge ta semaine sur ce que tu as réellement fourni, pas seulement sur ce qui a abouti. C''est la seule mesure qui reste stable quand les résultats dépendent d''autrui.'),
  ('q-0143', 'Plus vous aidez les gens à obtenir ce qu''ils désirent, plus vous avez de succès.', 'Zig Ziglar', 'sales', null, null, null, 'Principe de réciprocité appliqué au commerce : ton succès passe par celui de tes clients, donc servir leur intérêt n''est pas un sacrifice mais le mécanisme même de la réussite. Ziglar inverse l''ordre habituel entre donner et recevoir.', 'Dans ton prochain échange commercial, cherche d''abord ce que la personne essaie d''obtenir, indépendamment de ce que tu vends. Tu sauras ensuite si tu peux vraiment l''aider, ou pas.'),
  ('q-0145', 'Le succès ne s''explique pas. L''échec ne s''excuse pas.', 'Napoleon Hill', 'mindset', null, null, null, 'Hill souligne une asymétrie de discours : le succès parle de lui-même et n''a pas besoin d''être commenté, tandis que l''échec appelle des justifications qui ne changent rien au résultat. Le temps passé à expliquer est du temps qui ne corrige pas.', 'Après un échec, remplace l''explication par une décision. Une phrase sur ce que tu changes vaut mieux qu''un paragraphe sur ce qui s''est passé.'),
  ('q-0146', 'Chaque difficulté porte en elle le germe d''un avantage équivalent ou supérieur.', 'Napoleon Hill', 'mindset', null, null, null, 'Hill affirme que la difficulté contient une contrepartie utilisable — une compétence acquise, un défaut révélé, une relation testée. Encore faut-il la chercher : elle n''apparaît pas d''elle-même.', 'Face à un problème sérieux, écris ce qu''il t''oblige à améliorer. Cette question transforme une contrainte subie en information exploitable.'),
  ('q-0147', 'Les opportunités apparaissent le plus souvent sous la forme de malchance ou d''échec temporaire.', 'Napoleon Hill', 'mindset', null, null, null, 'Hill explique pourquoi les opportunités passent inaperçues : elles arrivent déguisées en ennuis. La perte d''un client, un projet annulé ou un refus libèrent des ressources qu''on n''aurait jamais réallouées volontairement.', 'Après un contretemps, note ce qu''il libère — du temps, un budget, une place. C''est souvent la seule occasion que tu auras de réaffecter ces ressources.'),
  ('q-0148', 'Le monde a l''habitude de faire de la place à l''homme dont les paroles et les actions montrent qu''il sait où il va.', 'Napoleon Hill', 'mindset', null, null, null, 'Hill décrit un effet de clarté : les gens et les occasions s''organisent autour de quelqu''un dont la direction est lisible. Le flou, lui, ne mobilise personne — non par mauvaise volonté, mais parce qu''on ne sait pas où aider.', 'Formule ton objectif en une phrase que tu peux dire à quelqu''un en trente secondes. Tant qu''elle n''existe pas, personne ne peut t''orienter une occasion pertinente.'),
  ('q-0151', 'S''il y a un secret à l''efficacité, c''est la concentration.', 'Peter Drucker', 'mindset', null, null, null, 'Drucker vise l''illusion de productivité : la dispersion donne l''impression d''avancer sur tout alors qu''elle empêche d''aboutir sur quoi que ce soit. L''efficacité tient moins à ce qu''on fait qu''à ce qu''on accepte de ne pas faire.', 'Choisis une seule priorité pour la journée et traite-la avant d''ouvrir ta messagerie. Ce qui reste après elle est du bonus, pas un échec.'),
  ('q-0152', 'Le temps est le capital le plus rare, et si on ne sait pas le gérer, alors on ne peut rien gérer d''autre.', 'Peter Drucker', 'leadership', null, null, null, 'Drucker distingue le temps des autres ressources : l''argent, les gens, le matériel se remplacent, se stockent ou s''empruntent. Le temps ne fait rien de tout cela, ce qui en fait la seule contrainte réellement absolue.', 'Note pendant une semaine où passent tes heures, sans chercher à corriger. L''écart entre ce que tu crois faire et ce que tu fais est presque toujours le vrai sujet.'),
  ('q-0153', 'L''entreprise n''a que deux fonctions de base : commercialiser et innover.', 'Peter Drucker', 'leadership', null, null, null, 'Drucker réduit l''entreprise à ce qui crée un client : commercialiser, c''est répondre à un besoin existant ; innover, c''est en créer un nouveau. Le reste — administration, finance, production — est un coût nécessaire, pas une fonction créatrice.', 'Classe tes activités de la semaine en trois colonnes : commercialiser, innover, administrer. Si la troisième domine largement, tu gères une structure plus que tu ne développes une entreprise.'),
  ('q-0154', 'On obtient des résultats en exploitant des opportunités, non en résolvant des problèmes.', 'Peter Drucker', 'mindset', null, null, null, 'Drucker corrige une habitude de gestion : résoudre un problème ramène au point de départ, saisir une opportunité fait avancer. Les deux consomment la même énergie, mais un seul produit de la croissance.', 'Regarde tes cinq dernières décisions. Si toutes visaient à réparer quelque chose, réserve un créneau explicite aux sujets qui n''ont rien de cassé mais beaucoup à gagner.'),
  ('q-0155', 'Il n''y a pas « un » caractère d''entrepreneur. Mais il faut « du » caractère pour l''être.', 'Peter Drucker', 'mindset', null, null, null, 'Drucker écarte le profil type. Il n''existe pas de personnalité entrepreneuriale — ni âge, ni tempérament, ni parcours obligatoires — mais il faut du caractère au sens de constance : tenir une décision dans l''incertitude, sur la durée.', 'Cesse de chercher si tu as « le profil ». Regarde plutôt si tu tiens tes engagements quand plus personne ne les surveille : c''est ce que Drucker appelle du caractère.'),
  ('q-0156', 'Pour être irremplaçable, il faut être différente.', 'Coco Chanel', 'mindset', null, null, null, 'Chanel relie l''irremplaçabilité à la différence, pas à l''excellence. Être meilleur reste comparable, donc substituable ; être différent supprime la comparaison et rend le remplacement impossible.', 'Identifie ce que tu fais autrement que les autres, pas mieux. C''est là qu''est ta position, et c''est ce que tu dois renforcer plutôt que corriger.'),
  ('q-0157', 'La mode se démode, le style jamais.', 'Coco Chanel', 'mindset', null, null, null, 'Chanel oppose deux temporalités : la mode est un accord collectif temporaire, le style est une cohérence personnelle. Suivre la première oblige à recommencer sans cesse ; construire le second capitalise.', 'Regarde ce que tu changes dans ton activité par conviction et ce que tu changes par conformité. Seul le premier type d''évolution s''accumule.'),
  ('q-0158', 'Ma vie ne me plaisait pas, alors j''ai créé ma vie.', 'Coco Chanel', 'mindset', null, null, null, 'Chanel décrit un refus assumé du déterminisme. Elle ne dit pas que les circonstances n''existent pas, mais qu''elles ne dispensent pas de choisir — et que ce choix est un acte de construction, pas un souhait.', 'Identifie un aspect de ta situation que tu subis depuis longtemps. Sépare ce qui dépend réellement de toi de ce qui n''en dépend pas, puis agis uniquement sur la première liste.'),
  ('q-0161', 'Un investissement dans le savoir paie toujours les meilleurs intérêts.', 'Benjamin Franklin', 'finance', null, null, null, 'Franklin compare le savoir aux placements : il ne se déprécie pas, ne se vole pas, et produit un rendement qui se compose sur toute une vie. C''est un argument économique, pas un encouragement moral.', 'Consacre un budget annuel explicite à ta formation, comme tu le ferais pour un outil. Ce qui n''a pas de ligne budgétaire finit toujours par ne pas se faire.'),
  ('q-0162', 'Le temps, c''est de l''argent.', 'Benjamin Franklin', 'finance', null, 'Advice to a Young Tradesman', 1748, 'Franklin, écrivant à un jeune commerçant, rappelle que le temps inoccupé a un coût réel : ce n''est pas de l''argent non gagné, c''est de l''argent perdu. La formule transforme une ressource abstraite en poste de dépense.', 'Calcule ce que vaut une heure de ton activité, puis regarde tes réunions récurrentes à cette aune. Certaines ne survivent pas au calcul.'),
  ('q-0164', 'Si vous ne parvenez pas à planifier, vous prévoyez d''échouer !', 'Benjamin Franklin', 'mindset', null, null, null, 'Franklin ne dit pas que le plan garantit le succès, mais que son absence organise l''échec. Sans plan, on ne peut ni anticiper, ni répartir l''effort, ni savoir si l''on dérive.', 'Avant un projet, écris les trois étapes et leurs échéances. Même approximatif, ce cadre rend visible tout retard — ce qu''aucune intention ne permet.'),
  ('q-0165', 'Ne remettez pas au lendemain ce que vous pouvez faire le jour même.', 'Benjamin Franklin', 'mindset', null, 'L''Almanach du pauvre Richard', null, 'Maxime contre le report : ce qui est différé ne disparaît pas, il s''accumule et devient plus coûteux, parce qu''il faut à chaque fois reprendre le contexte perdu.', 'Traite immédiatement ce qui prend moins de deux minutes. Le coût de le noter, de le retrouver et de s''y remettre dépasse souvent celui de le faire tout de suite.'),
  ('q-0166', 'La paresse chemine si lentement que la pauvreté la rattrape.', 'Benjamin Franklin', 'finance', null, 'L''Almanach du pauvre Richard', null, 'L''image de la poursuite décrit un rattrapage inévitable : l''inaction ne fige pas la situation, elle laisse les conséquences avancer pendant qu''on n''avance pas. La lenteur du processus est ce qui le rend indolore jusqu''au bout.', 'Regarde une chose que tu laisses se dégrader faute de temps — un impayé, un outil vieillissant, une compétence. Chiffre ce qu''elle coûtera dans un an si rien ne change.'),
  ('q-0168', 'Dans 20 ans, vous serez plus déçu par les choses que vous n''avez pas faites que par celles que vous avez faites.', 'H. Jackson Brown Jr.', 'mindset', null, null, null, 'Brown compare deux regrets sur le long terme : celui de l''action ratée s''estompe, celui de l''occasion manquée grandit. L''asymétrie devrait peser dans les décisions présentes.', 'Devant une hésitation, projette-toi à vingt ans. Le regret d''avoir essayé est presque toujours plus léger que celui de ne pas avoir su.'),
  ('q-0170', 'Chaque fois que vous vous trouvez du côté de la majorité, il est temps de faire une pause et de réfléchir.', 'Mark Twain', 'mindset', null, 'Carnets', null, 'Twain propose un signal d''alerte : se retrouver dans la majorité peut indiquer qu''on a suivi plutôt que réfléchi. Ce n''est pas que la majorité ait tort, c''est que l''accord facile mérite vérification.', 'Quand tu es d''accord avec tout le monde, prends cinq minutes pour reconstruire ton raisonnement. Vérifie qu''il t''appartient.'),
  ('q-0172', 'Trop de publicité tue la publicité.', 'Jacques Séguéla', 'sales', null, null, null, 'Séguéla nomme un effet de seuil : au-delà d''une certaine dose, chaque message supplémentaire ne s''ajoute pas aux précédents, il les annule. L''attention n''est pas extensible, et une audience saturée cesse de trier — elle rejette en bloc.', 'Compte tes points de contact sur une semaine : e-mails, notifications, relances, publications. Si le nombre te surprend, coupe le tiers le moins utile plutôt que d''améliorer le message le plus faible.'),
  ('q-0173', 'Tout homme qui meurt riche meurt déshonoré.', 'Andrew Carnegie', 'finance', 'Carnegie a donné la quasi-totalité de sa fortune de son vivant, finançant plus de 2 500 bibliothèques publiques.', 'L''Évangile de la richesse', 1889, 'Carnegie, qui a donné l''essentiel de sa fortune de son vivant, considère la richesse accumulée sans usage comme un échec. L''argent est un moyen ; mourir en le laissant inutilisé revient à n''avoir jamais su à quoi il servait.', 'Demande-toi à quoi sert concrètement ce que tu accumules. Une réserve sans finalité n''est pas de la prudence, c''est une décision reportée indéfiniment.'),
  ('q-0174', 'Aucun homme ne devient riche à moins qu''il enrichisse autrui.', 'Andrew Carnegie', 'finance', null, null, null, 'Carnegie décrit le mécanisme de la richesse durable : elle vient de la valeur créée pour d''autres, pas d''un transfert. Une fortune bâtie sans contrepartie reste une captation, et se comporte comme telle dans le temps.', 'Vérifie que ton modèle enrichit réellement tes clients — en temps, en argent ou en capacité. Si le gain n''est que de ton côté, la relation ne durera pas.'),
  ('q-0176', 'Faites votre devoir et un peu plus encore, et l''avenir prendra soin de lui-même.', 'Andrew Carnegie', 'mindset', null, null, null, 'Carnegie décrit un léger surplus systématique : faire strictement ce qu''on attend rend interchangeable, faire un peu plus crée une différence qui finit par se remarquer. L''écart est petit à chaque fois, considérable cumulé.', 'Sur ta prochaine livraison, ajoute une chose non demandée mais utile. Ce n''est pas du zèle : c''est ce qui fait qu''on te rappelle plutôt qu''un autre.'),
  ('q-0177', 'Concentrez vos énergies, vos pensées et votre capital.', 'Andrew Carnegie', 'finance', null, null, null, 'Carnegie prône la concentration contre la dispersion. Répartir ses moyens réduit le risque apparent mais empêche d''atteindre le seuil où quelque chose devient significatif — en attention comme en capital.', 'Liste tes chantiers en cours. Si tu en as plus de trois qui comptent vraiment, tu n''en as en réalité aucun : choisis ceux que tu mets en pause.'),
  ('q-0178', 'Ceux qui réussissent sont des hommes qui ont choisi une ligne de conduite et qui s''y tiennent.', 'Andrew Carnegie', 'mindset', null, null, null, 'Carnegie place la constance au-dessus du choix initial. Beaucoup de directions peuvent fonctionner ; presque aucune ne fonctionne si on en change tous les six mois, car rien n''a le temps de produire.', 'Fixe une durée minimale avant de réévaluer une orientation. Changer avant l''échéance doit devenir une décision consciente, pas une réaction à la difficulté du moment.'),
  ('q-0179', 'Ce n''est pas parce que les choses sont difficiles que nous n''osons pas, c''est parce que nous n''osons pas qu''elles sont difficiles.', 'Sénèque', 'mindset', null, 'Lettres à Lucilius, lettre 104', null, 'Sénèque inverse la relation entre difficulté et audace. Ce n''est pas la difficulté objective qui nous arrête, c''est le renoncement préalable qui rend la chose difficile : faute d''essayer, on ne développe jamais les moyens qui l''auraient rendue abordable.', 'Prends une tâche que tu qualifies de trop difficile et décompose-la en trois étapes. Le plus souvent, c''est le flou qui intimidait, pas la difficulté.'),
  ('q-0180', 'Il n''est pas de vent favorable pour celui qui ne sait pas où il va.', 'Sénèque', 'mindset', null, 'Lettres à Lucilius, lettre 71', null, 'Sans destination, aucune circonstance ne peut être qualifiée de favorable — il n''y a plus de critère pour juger. Sénèque ne parle pas de motivation mais d''orientation : sans cap, même la chance devient inutilisable.', 'Écris en une phrase où tu veux être dans un an. Tant que cette phrase n''existe pas, tu ne peux pas trier les opportunités qui se présentent — tu ne peux que réagir.'),
  ('q-0181', 'C''est par l''épreuve du feu qu''on reconnaît l''or pur. C''est par les épreuves qu''on reconnaît l''homme de cœur.', 'Sénèque', 'mindset', null, null, null, 'L''épreuve ne fabrique pas la qualité, elle la révèle. Sénèque décrit un test, pas une méthode de progression : la difficulté montre ce qui était déjà là, en bien comme en mal.', 'Après une période tendue, note qui a tenu ses engagements et qui s''est dérobé. Cette information vaut plus que tous les entretiens d''évaluation en période calme.'),
  ('q-0182', 'Le plus grand obstacle à la vie est l''attente, qui espère demain et néglige aujourd''hui.', 'Sénèque', 'mindset', 'Sénèque y répond à ceux qui se plaignent de la brièveté de la vie : elle est assez longue, c''est l''usage qu''on en fait qui la gaspille.', 'De la brièveté de la vie', null, 'Sénèque désigne l''attente comme une forme de perte : à force de vivre dans le prochain moment, on ne vit dans aucun. Le temps ainsi passé n''est pas économisé, il est simplement dépensé sans qu''on s''en aperçoive.', 'Repère ce que tu diffères en attendant « le bon moment ». Fixe-lui une date, ou renonce-y explicitement — l''attente indéfinie est la seule option qui coûte sans rien produire.'),
  ('q-0183', 'À force de remettre à plus tard, la vie nous dépasse.', 'Sénèque', 'mindset', null, 'Lettres à Lucilius, lettre 1', null, 'Formule sur le report chronique. Chaque ajournement paraît sans conséquence pris isolément ; leur accumulation consomme la seule ressource qu''on ne peut pas reconstituer.', 'Applique la règle des deux minutes : ce qui prend moins de deux minutes se fait immédiatement. Le reste va dans une liste avec une date, jamais dans un vague « bientôt ».'),
  ('q-0184', 'C''est pendant l''orage qu''on connaît le pilote.', 'Sénèque', 'mindset', null, null, null, 'La compétence d''un dirigeant ne se mesure pas quand tout va bien, puisque rien ne la sollicite. C''est la crise qui distingue celui qui savait de celui que les circonstances portaient.', 'Prépare tes procédures de crise pendant la période calme — qui décide, qui informe, avec quel budget. Improviser cela le jour venu est ce qui transforme un problème en désastre.'),
  ('q-0185', 'Un voyage de mille lieues commence toujours par un premier pas.', 'Lao Tseu', 'mindset', null, 'Tao Tö King, chapitre 64', null, 'La formule ramène l''immensité d''un projet à sa seule condition de démarrage. Le premier pas ne réduit pas la distance de façon significative, mais il change l''état : on passe de l''intention au mouvement.', 'Pour un projet qui t''intimide, définis un premier pas si petit qu''il ne puisse pas être repoussé. La taille n''a aucune importance, le franchissement si.'),
  ('q-0187', 'Qui triomphe de lui-même possède la force.', 'Lao Tseu', 'mindset', null, 'Tao Tö King, chapitre 33', null, 'Lao Tseu place la maîtrise de soi au-dessus de la domination des autres. Vaincre autrui dépend des circonstances et de l''adversaire ; se vaincre soi-même ne dépend que de soi, ce qui en fait la seule victoire vraiment disponible.', 'Identifie l''habitude qui te coûte le plus. La corriger produira plus d''effet que toute victoire obtenue sur un concurrent.'),
  ('q-0188', 'Tout ce que je sais, c''est que je ne sais rien.', 'Socrate', 'mindset', null, null, null, 'Socrate fait de la conscience de son ignorance le point de départ du savoir. Celui qui croit savoir cesse de chercher ; celui qui mesure son ignorance continue d''apprendre.', 'Sur un sujet que tu maîtrises, cherche activement ce que tu ignores encore. C''est cette question qui empêche l''expertise de se figer.'),
  ('q-0191', 'Une vie sans examen ne vaut pas la peine d''être vécue.', 'Socrate', 'mindset', 'Ce que Socrate répond à ses juges qui lui proposent l''exil plutôt que la mort : une vie sauvée au prix de renoncer à examiner ses idées ne l''intéresse pas.', 'Platon, Apologie de Socrate', null, 'Socrate défend une vie soumise à l''examen : accepter ses choix sans jamais les interroger revient à vivre selon des décisions qu''on n''a pas prises soi-même.', 'Consacre une heure par trimestre à réexaminer tes choix structurants — métier, priorités, engagements. Sans ce rendez-vous, l''inertie décide à ta place.'),
  ('q-0193', 'Sois comme un promontoire contre lequel les flots viennent sans cesse se briser.', 'Marc Aurèle', 'mindset', null, 'Pensées pour moi-même, livre IV', null, 'Marc Aurèle propose une image de stabilité : le promontoire ne repousse pas les vagues, il les laisse se briser. La solidité ne vient pas de la lutte mais du fait de ne pas être déplacé.', 'Face à des critiques répétées, décide à l''avance de ce que tu changes et de ce que tu maintiens. Sans cette ligne, chaque vague te déplace un peu.'),
  ('q-0195', 'Avoir du courage ne veut pas dire que nous n''avons pas peur, mais que nous affrontons nos peurs.', 'Maya Angelou', 'mindset', null, null, null, 'Angelou définit le courage comme un rapport à la peur, pas comme son absence. L''intrépidité totale n''existe pas ; ce qui se travaille, c''est la capacité d''agir malgré la peur présente.', 'Avant une échéance qui t''angoisse, nomme précisément ce que tu crains. La peur identifiée devient un risque à traiter ; la peur diffuse reste paralysante.'),
  ('q-0196', 'Vous ferez face à de nombreuses défaites dans votre vie, mais ne vous laissez jamais vaincre.', 'Maya Angelou', 'mindset', null, null, null, 'Angelou distingue la défaite, qui est un événement, de l''état de vaincu, qui est une acceptation. On peut perdre souvent sans jamais franchir la seconde étape — et c''est elle seule qui est définitive.', 'Après un revers, fixe-toi une action concrète dans les 48 heures, même minime. C''est le délai d''inaction qui transforme un échec en renoncement.'),
  ('q-0197', 'Faites de votre mieux jusqu''à ce que vous sachiez faire mieux. Et quand vous saurez, faites mieux.', 'Maya Angelou', 'mindset', null, null, null, 'Angelou désamorce la culpabilité rétrospective : on ne peut être jugé que sur ce qu''on savait au moment d''agir. En revanche, une fois qu''on sait, continuer comme avant n''est plus de l''ignorance.', 'Quand tu découvres une meilleure façon de faire, applique-la tout de suite plutôt que de te reprocher l''ancienne. Le seul reproche légitime concerne ce que tu maintiens après avoir su.'),
  ('q-0199', 'Aussi dur que tu crois pouvoir travailler, tu peux travailler encore plus dur que ça.', 'Kobe Bryant', 'mindset', null, null, null, 'Bryant décrit un plafond d''effort systématiquement sous-estimé : ce qu''on croit être sa limite est presque toujours en deçà de ce qu''on peut réellement soutenir. Il parle d''exigence, pas d''épuisement.', 'Sur ta compétence clé, ajoute une séance de travail délibéré par semaine. L''objectif est de déplacer ce que tu crois être ton maximum, pas de saturer ton agenda.'),
  ('q-0200', 'On n''abandonne pas, on ne bat en retraite, on ne fuit pas.', 'Kobe Bryant', 'mindset', null, null, null, 'Bryant énonce trois refus qui décrivent une discipline plus qu''un état d''esprit : ne pas céder, ne pas reculer, ne pas éviter. C''est une règle de conduite pour les moments où tout pousse à faire l''inverse.', 'Identifie la situation où tu as tendance à te dérober. Décide à l''avance de ta réaction : c''est la décision prise à froid qui tient le jour venu.'),
  ('q-0201', 'Tout changement de vie commence par une décision.', 'Tony Robbins', 'mindset', null, null, null, 'Robbins situe le point de bascule à la décision, pas à l''effort qui suit. Tant que le choix n''est pas tranché, l''énergie se disperse à évaluer les options plutôt qu''à avancer.', 'Sur un sujet que tu tournes en boucle, fixe une date de décision et tiens-la. La qualité du choix compte souvent moins que le fait d''en avoir fait un.'),
  ('q-0202', 'L''échec est une partie du succès. Quiconque évite l''échec évite aussi le succès.', 'Tony Robbins', 'mindset', null, null, null, 'Robbins présente l''échec comme un composant du succès, pas comme son contraire. Éviter systématiquement l''échec revient donc à éviter les conditions dans lesquelles le succès pourrait apparaître.', 'Vérifie que ta prudence ne t''écarte pas des situations où quelque chose de significatif peut arriver. Un parcours sans échec signale souvent une ambition calibrée trop bas.'),
  ('q-0203', 'Les décisions que nous prenons déterminent notre destin.', 'Tony Robbins', 'mindset', null, null, null, 'Robbins attribue la trajectoire aux décisions plutôt qu''aux circonstances. Les conditions varient pour tout le monde ; ce qui distingue les parcours, c''est ce qu''on en fait au moment de choisir.', 'Repère les trois décisions qui ont le plus orienté ta situation actuelle. Cet exercice montre concrètement le poids réel de tes choix — et donc des prochains.'),
  ('q-0205', 'La qualité de la vie d''une personne est en rapport direct avec sa volonté d''exceller, quel que soit le domaine où elle s''exerce.', 'Vince Lombardi', 'mindset', null, null, null, 'Lombardi relie la qualité de vie à l''exigence, sans la limiter à un domaine : c''est la disposition à bien faire, quel que soit le sujet, qui détermine ce qu''on tire de son existence.', 'Choisis un domaine où tu te contentes du minimum et relève le niveau pendant un mois. L''effet déborde généralement sur le reste.'),
  ('q-0206', 'Si l''important n''est pas de gagner, pourquoi compte-t-on les points ?', 'Vince Lombardi', 'mindset', null, null, null, 'Lombardi démonte le discours sur la participation : si le résultat n''avait aucune importance, on ne le mesurerait pas. Reconnaître qu''on veut gagner est une condition pour s''en donner les moyens.', 'Assume l''objectif que tu poursuis réellement au lieu de le minimiser par prudence. Un objectif qu''on n''ose pas nommer ne mobilise personne.'),
  ('q-0207', 'Les conditions essentielles pour réussir sont la patience et la certitude du succès.', 'John D. Rockefeller', 'mindset', null, null, null, 'Rockefeller associe deux qualités qui se soutiennent : la patience permet de tenir la durée, la conviction empêche d''abandonner pendant qu''on attend. Séparées, la première devient de l''attentisme et la seconde de l''impatience.', 'Fixe à ton projet une durée avant jugement, et note pourquoi tu crois qu''il fonctionnera. Ce texte te servira quand la patience seule ne suffira plus.'),
  ('q-0208', 'Si vous voulez réussir, lancez-vous sur de nouveaux chemins plutôt que de parcourir les sentiers usés du succès accepté.', 'John D. Rockefeller', 'mindset', null, null, null, 'Rockefeller met en garde contre les chemins déjà empruntés : là où le succès est reconnu, la concurrence est maximale et les marges déjà prises. L''inconnu est risqué mais reste disponible.', 'Regarde où tout le monde va dans ton secteur, puis regarde ce que personne n''occupe. Le second espace demande plus d''explications mais laisse plus de place.'),
  ('q-0209', 'La ténacité est une des qualités indispensables pour réussir dans la vie, quel que soit le but à atteindre.', 'John D. Rockefeller', 'mindset', null, null, null, 'Rockefeller érige la ténacité en qualité transversale : indépendamment du domaine et du talent, c''est elle qui détermine qui reste quand les autres partent. Elle est le facteur commun à des réussites très différentes.', 'Quand tu compares deux options, tiens compte de celle que tu tiendras le plus longtemps. Un plan légèrement moins bon mais tenable bat un plan optimal abandonné.'),
  ('q-0210', 'Le secret du succès est de faire les choses communes de manière peu commune.', 'John D. Rockefeller', 'mindset', null, null, null, 'Rockefeller ne recommande pas de chercher l''extraordinaire, mais d''exécuter l''ordinaire à un niveau que les autres n''atteignent pas. L''avantage vient de la qualité d''exécution sur des choses banales.', 'Prends la tâche la plus routinière de ton activité et fais-la remarquablement bien pendant un mois. C''est souvent là que se trouve la différence perceptible par le client.'),
  ('q-0211', 'Il n''y a qu''un seul patron : le client. Il peut licencier tout le monde, simplement en allant dépenser son argent ailleurs.', 'Sam Walton', 'sales', null, null, null, 'Walton rappelle qui détient réellement le pouvoir de décision : le client, dont le simple changement d''habitude suffit à vider une entreprise. Aucune hiérarchie interne ne pèse contre cela.', 'Regarde tes départs de clients comme des décisions de licenciement. Chacun t''a signifié quelque chose, même sans le dire.'),
  ('q-0213', 'La meilleure raison de lancer une entreprise, c''est de créer du sens.', 'Guy Kawasaki', 'leadership', null, null, null, 'Kawasaki place le sens avant le profit comme motif de création. Une entreprise fondée pour l''argent seul manque de résistance dans les périodes où l''argent tarde — c''est-à-dire au début.', 'Écris ce que ton activité change pour ceux qui l''utilisent. Cette phrase te servira les jours où les chiffres ne suffiront pas à te faire tenir.'),
  ('q-0214', 'Les vrais entrepreneurs sont motivés par leur passion, non par le profit.', 'Guy Kawasaki', 'mindset', null, null, null, 'Kawasaki distingue le moteur du résultat : le profit sanctionne la réussite mais ne fait pas travailler quelqu''un pendant des années sans garantie. La passion, elle, tient sans contrepartie immédiate.', 'Vérifie que tu ferais encore ce projet s''il rapportait moitié moins. Si la réponse est non, sois lucide sur ta capacité à traverser les périodes creuses.'),
  ('q-0221', 'Être réaliste est la voie la plus commune vers la médiocrité.', 'Will Smith', 'mindset', null, null, null, 'Smith vise le réalisme utilisé comme prétexte : ajuster ses ambitions à ce qui semble raisonnable conduit à viser exactement la moyenne. Le mot sert souvent à habiller le renoncement.', 'Quand on qualifie ton objectif d''irréaliste, demande sur quoi repose ce jugement. Souvent, il repose sur ce qui a été fait, pas sur ce qui est possible.'),
  ('q-0224', 'Un gagnant est un rêveur qui n''abandonne jamais.', 'Nelson Mandela', 'mindset', null, null, null, 'Mandela associe deux qualités qu''on oppose souvent : rêver, c''est viser au-delà du raisonnable ; ne pas abandonner, c''est accepter la durée. L''une sans l''autre ne produit rien.', 'Vérifie que ton objectif a les deux composantes : une ambition qui justifie l''effort, et une échéance assez lointaine pour être tenable. Un objectif ambitieux à court terme se solde presque toujours par l''abandon.'),
  ('q-0225', 'La plus grande gloire n''est pas de ne jamais tomber, mais de se relever à chaque chute.', 'Nelson Mandela', 'mindset', null, null, null, 'Mandela déplace le critère d''évaluation : la performance ne se mesure pas à l''absence de chute mais à la capacité de reprendre. Cela suppose de juger sur une trajectoire plutôt que sur un instantané.', 'Quand tu évalues quelqu''un — ou toi-même — regarde le temps de récupération après un échec plutôt que le nombre d''échecs. C''est l''indicateur qui prédit la suite.'),
  ('q-0226', 'Ne me jugez pas par mon succès, jugez-moi par combien de fois je suis tombé et je me suis relevé.', 'Nelson Mandela', 'mindset', null, null, null, 'Mandela propose un critère de jugement contre-intuitif : le nombre de relèvements dit plus sur une personne que son palmarès, parce qu''il révèle ce qui se passe quand rien ne va.', 'Dans un recrutement, demande un échec et ce qui a suivi. La réponse est bien plus prédictive que la liste des réussites, que tout le monde prépare.'),
  ('q-0227', 'C''est toujours impossible jusqu''à ce que ça soit fait.', 'Nelson Mandela', 'mindset', null, null, null, 'Mandela constate que l''impossibilité est un jugement provisoire, valable jusqu''à la première réalisation. Venant de quelqu''un qui a vu tomber un régime qu''on disait immuable, ce n''est pas une formule d''encouragement mais un constat.', 'Quand on te dit qu''une chose n''a jamais été faite, distingue « impossible » de « inédit ». Le second n''est pas un obstacle, c''est une absence de précédent.'),
  ('q-0228', 'La confiance en soi est le premier secret du succès.', 'Ralph Waldo Emerson', 'mindset', null, null, null, 'Emerson place la confiance en amont plutôt qu''en récompense. Sans elle, on ne tente pas, donc on n''obtient rien qui pourrait la justifier — la boucle se referme avant d''avoir commencé.', 'Fonde ta confiance sur des preuves plutôt que sur une humeur : garde une trace écrite de ce que tu as déjà réussi. C''est le seul argument qui tienne les jours de doute.'),
  ('q-0229', 'N''allez pas là où le chemin peut mener. Allez là où il n''y a pas de chemin et laissez une trace.', 'Ralph Waldo Emerson', 'mindset', null, null, null, 'Emerson oppose deux stratégies : suivre un chemin existant, qui mène là où d''autres sont déjà arrivés, ou en ouvrir un, qui expose au risque mais laisse une position qu''on ne partage avec personne.', 'Regarde ce que fait ton secteur en majorité et demande-toi ce que personne n''y tente. L''absence de concurrence à cet endroit est une information, pas forcément un piège.'),
  ('q-0230', 'Les hommes parlent de la victoire comme d''une chance. C''est le travail qui fait la victoire.', 'Ralph Waldo Emerson', 'mindset', null, null, null, 'Emerson conteste l''attribution à la chance. Ce qui est visible de l''extérieur, c''est le succès ; ce qui ne l''est pas, c''est le travail accumulé — d''où l''impression de hasard chez ceux qui n''ont vu que la fin.', 'Quand une réussite te paraît chanceuse, cherche ce qui l''a précédée pendant des années. Tu y trouveras plus d''enseignements utiles que dans l''explication par la chance.'),
  ('q-0231', 'Rien de grand ne se fit jamais sans enthousiasme.', 'Ralph Waldo Emerson', 'mindset', null, null, null, 'Emerson pointe l''énergie nécessaire pour franchir les obstacles d''un projet ambitieux. La compétence permet d''exécuter, mais c''est l''enthousiasme qui fait tenir la distance entre le début et le résultat.', 'Si un projet t''ennuie déjà au démarrage, sois lucide : les obstacles à venir ne le rendront pas plus attrayant. Mieux vaut le confier à quelqu''un qu''il intéresse.'),
  ('q-0232', 'L''ancêtre de toute action est une pensée.', 'Ralph Waldo Emerson', 'mindset', null, null, null, 'Emerson rappelle que toute réalisation commence par une représentation mentale. Ce n''est pas un appel à la pensée magique, mais un constat de séquence : on ne fait jamais ce qu''on n''a pas d''abord conçu.', 'Avant de lancer un projet, décris précisément à quoi ressemble le résultat réussi. L''imprécision de cette image se retrouvera intégralement dans l''exécution.'),
  ('q-0233', 'La vie est une aventure audacieuse ou elle n''est rien.', 'Helen Keller', 'mindset', null, null, null, 'Keller, sourde et aveugle depuis la petite enfance, écarte l''entre-deux : une existence organisée pour éviter tout risque se vide de ce qui la rend vivable. L''audace n''est pas un supplément, c''est ce qui donne son contenu à la vie.', 'Identifie une chose que tu évites uniquement par crainte de l''inconfort. Fais-la à petite échelle pour vérifier ce que ta prudence te coûtait réellement.'),
  ('q-0234', 'Tournez votre visage vers le soleil et vous ne verrez pas les ombres.', 'Helen Keller', 'mindset', null, null, null, 'L''image décrit une question d''orientation, pas de déni : les ombres existent, mais elles se trouvent derrière quand on fait face à la lumière. Ce qu''on regarde détermine ce qu''on voit.', 'Quand un projet s''enlise, commence tes réunions par ce qui avance avant de traiter ce qui bloque. L''ordre change l''énergie disponible pour résoudre le reste.'),
  ('q-0235', 'Aucun pessimiste n''a jamais découvert le secret des étoiles ni ouvert un nouveau chemin pour l''esprit humain.', 'Helen Keller', 'mindset', null, null, null, 'Keller relie découverte et disposition d''esprit. Le pessimisme est cohérent et souvent juste à court terme, mais il n''engage jamais l''exploration — donc il ne trouve rien.', 'Avant d''écarter une idée comme irréaliste, accorde-lui trente minutes d''examen sérieux. Le coût est faible, et c''est le seul moyen de ne pas rejeter par réflexe.'),
  ('q-0236', 'Il y a toujours deux raisons pour faire quelque chose : une bonne raison et la vraie raison !', 'Dale Carnegie', 'mindset', null, null, null, 'Carnegie distingue le motif avoué du motif réel. Comprendre cette différence change la façon de négocier : on répond souvent à la bonne raison alors que la décision se joue sur l''autre.', 'Face à un refus argumenté, cherche ce qui n''est pas dit — un budget, une crainte, un rapport de force interne. C''est là que se trouve le vrai obstacle.'),
  ('q-0237', 'Ni les situations ni les gens ne peuvent être améliorés par un facteur externe. Si amélioration il doit y avoir, elle doit venir de l''intérieur.', 'Dale Carnegie', 'mindset', null, null, null, 'Carnegie situe le levier du changement à l''intérieur. On peut créer les conditions, mais personne ne transforme quelqu''un contre son gré : la contrainte produit de la conformité, pas de l''amélioration.', 'Plutôt que d''imposer un changement, rends-le désirable et possible. Si la personne n''y trouve pas son intérêt, la mesure ne survivra pas à ta surveillance.'),
  ('q-0239', 'Un enfant, un professeur, un livre, un crayon peuvent changer le monde.', 'Malala Yousafzai', 'mindset', null, null, null, 'Malala désigne la puissance de l''éducation à partir d''éléments minuscules. La formule oppose la modestie des moyens à l''ampleur de l''effet, pour montrer que le levier est accessible.', 'Ne sous-estime pas les moyens dont tu disposes déjà. Beaucoup de projets attendent des ressources qui n''ajouteraient rien d''essentiel.'),
  ('q-0244', 'Les chefs d''entreprise ne peuvent pas être des spectateurs.', 'Howard Schultz', 'leadership', null, null, null, 'Schultz refuse la position d''observateur pour un dirigeant. Regarder son entreprise de loin, à travers des rapports, revient à découvrir les problèmes une fois qu''ils sont irréversibles.', 'Passe régulièrement du temps là où le travail se fait réellement. Ce que tu y verras ne remonte jamais tel quel dans un tableau de bord.'),
  ('q-0245', 'Parfois, vous devez créer la chose dont vous voulez faire partie.', 'Howard Schultz', 'mindset', null, null, null, 'Schultz décrit l''entrepreneuriat comme une réponse à un manque personnel : construire ce dont on aurait voulu disposer. C''est le point de départ le plus fiable, parce qu''on connaît le besoin de l''intérieur.', 'Note ce qui te manque et que personne ne propose. Ta frustration de client est une information que tes concurrents n''ont pas.'),
  ('q-0247', 'Nous devrions construire de grandes choses qui n''existent pas.', 'Larry Page', 'mindset', null, null, null, 'Page oriente l''ambition vers l''inexistant plutôt que vers l''amélioration. Améliorer ce qui existe donne des gains marginaux ; créer ce qui n''existe pas ouvre un espace entier, avec une incertitude proportionnelle.', 'Consacre une part de ton temps à un projet sans équivalent, même petit. Le reste de ton activité optimisera toujours l''existant, personne n''a besoin qu''on l''y aide.'),
  ('q-0248', 'Presque tous ceux qui ont eu une idée quelque peu révolutionnaire ont d''abord été traités de fous.', 'Larry Page', 'mindset', null, null, null, 'Page observe une régularité : une idée réellement nouvelle est incompréhensible avec les repères existants, donc jugée absurde. Le rejet initial est un effet mécanique, pas une évaluation de la qualité.', 'Quand une idée provoque un rejet immédiat, distingue les objections argumentées des réactions d''incompréhension. Seules les premières méritent qu''on révise le projet.'),
  ('q-0249', 'L''optimisme est important. Vous devez être un peu ridicule sur les objectifs que vous allez définir.', 'Larry Page', 'mindset', null, null, null, 'Page assume une ambition qui paraît disproportionnée, parce qu''un objectif raisonnable oriente vers des solutions connues. Un objectif absurde oblige à changer d''approche, ce qui est précisément l''intérêt.', 'Prends un objectif et multiplie-le par dix. Observe quelles solutions deviennent impossibles : c''est ce filtre qui fait apparaître les approches vraiment différentes.'),
  ('q-0250', 'Il est très difficile d''échouer complètement, si vous visez assez haut.', 'Larry Page', 'mindset', null, null, null, 'Page décrit un effet d''ambition : viser très haut et n''atteindre qu''une fraction laisse tout de même un résultat supérieur à un objectif modeste pleinement atteint. L''échec relatif d''une grande ambition reste souvent un succès.', 'Quand tu fixes un objectif, demande-toi ce que vaudrait 30 % du résultat. Si c''est déjà satisfaisant, l''ambition est bien calibrée.'),
  ('q-0251', 'Il vaut mieux agir trop rapidement qu''attendre trop longtemps.', 'Jack Welch', 'mindset', null, null, null, 'Welch tranche en faveur de la vitesse parce que les coûts ne sont pas symétriques : une décision trop rapide se corrige, une décision trop tardive laisse le problème grandir pendant l''hésitation.', 'Distingue les décisions réversibles des autres. Les premières se prennent vite, quitte à revenir dessus ; réserve ton temps d''analyse aux secondes.'),
  ('q-0252', 'Restructurer, c''est un chemin, pas une destination.', 'Jack Welch', 'leadership', null, null, null, 'Welch décrit l''adaptation comme un état permanent, pas comme une opération exceptionnelle. Traiter la réorganisation comme un événement ponctuel conduit à accumuler du retard entre deux, puis à devoir tout casser.', 'Programme une revue régulière de ton organisation, même quand tout va bien. Les ajustements fréquents et petits coûtent moins cher qu''une refonte tous les cinq ans.'),
  ('q-0253', 'Contrôlez votre destinée ou quelqu''un d''autre le fera à votre place.', 'Jack Welch', 'mindset', null, null, null, 'Welch pose une alternative sans troisième terme : si tu ne définis pas ta trajectoire, d''autres la définiront selon leurs intérêts. L''absence de choix est donc elle-même un choix, simplement délégué.', 'Regarde une décision importante en attente. Si tu ne la prends pas ce trimestre, identifie qui la prendra à ta place et ce qu''il choisira.'),
  ('q-0254', 'Soit vous êtes le meilleur dans ce que vous faites, soit vous ne le faites pas très longtemps.', 'Jack Welch', 'mindset', null, null, null, 'Welch énonce une pression concurrentielle brutale : sur un marché ouvert, les positions moyennes se font éroder par le haut et par le bas. Il ne dit pas qu''il faut être premier partout, mais qu''il faut l''être là où l''on reste.', 'Identifie le domaine précis où tu peux être le meilleur, quitte à le définir étroitement. Être excellent sur un segment vaut mieux qu''être correct sur cinq.'),
  ('q-0256', 'J''attribue mon succès à ceci : je n''ai jamais présenté ou accepté aucune excuse.', 'Earl Nightingale', 'mindset', null, null, null, 'Nightingale relie sa réussite à un refus systématique : ne pas produire d''excuse, ne pas en accepter. L''excuse est une explication qui dispense de corriger.', 'Quand tu t''apprêtes à justifier un retard, propose une solution à la place. L''explication n''intéresse presque jamais celui qui attend.'),
  ('q-0257', 'Pour augmenter votre taux de succès, vous devez augmenter votre taux d''échecs.', 'Thomas J. Watson', 'mindset', null, null, null, 'Watson relie mécaniquement les deux taux : plus de tentatives produit plus d''échecs et plus de réussites. Vouloir augmenter l''un en réduisant l''autre est arithmétiquement impossible.', 'Si tu veux plus de résultats, augmente le nombre de tentatives avant d''améliorer leur qualité. Le volume produit des occasions que la perfection retarde.'),
  ('q-0258', 'Nos clients les plus mécontents sont notre plus grande source de progrès.', 'Bill Gates', 'sales', null, null, null, 'Gates transforme la réclamation en ressource. Le client satisfait ne signale rien, celui qui part en silence non plus : seul le mécontent explique gratuitement ce qui ne va pas.', 'Mets en place un canal simple pour les réclamations et lis-les toi-même une fois par mois. Les filtrer par un tableau de bord fait disparaître exactement l''information utile.'),
  ('q-0259', 'On ne devient homme qu''en se surpassant.', 'Aristote', 'mindset', null, null, null, 'L''idée est que la nature humaine ne se réalise pas passivement : c''est en dépassant l''état où l''on se trouve qu''on devient pleinement ce qu''on peut être. L''effort n''est pas un supplément, il est constitutif.', 'Choisis chaque année une chose que tu ne sais pas encore faire et qui te met mal à l''aise. C''est le seul type d''objectif qui te change réellement.'),
  ('q-0260', 'La stratégie, c''est l''art de faire face à son destin.', 'Peter Drucker', 'leadership', null, null, null, 'Drucker relie stratégie et responsabilité. Ne pas choisir de direction ne protège de rien : cela laisse simplement les circonstances décider. La stratégie est l''acte d''assumer une trajectoire plutôt que de la subir.', 'Écris en une phrase ce que ton organisation refuse de faire. Une stratégie qui n''exclut rien n''est pas une stratégie, c''est une liste de souhaits.'),
  ('q-0261', 'Il faut toujours être prêt à négocier, mais ne jamais négocier sans être prêt.', 'Richard Nixon', 'sales', null, null, null, 'Nixon distingue la disponibilité et la préparation. Être ouvert au dialogue est une posture ; entrer en négociation sans avoir travaillé son dossier est une faute qui se paie immédiatement.', 'Avant toute négociation, écris ton objectif, ta limite et ta solution de repli. Ces trois lignes valent mieux que n''importe quelle technique.'),
  ('q-0262', 'On peut tromper tout le monde une partie du temps, et une partie des gens tout le temps, mais on ne peut pas tromper tout le monde tout le temps.', 'Abraham Lincoln', 'mindset', null, null, null, 'La formule décrit les limites de la manipulation dans la durée : elle fonctionne ponctuellement ou sur une partie des gens, jamais sur tous et durablement. Le temps finit par révéler.', 'Construis ta communication en supposant que tout finira par se savoir. C''est la seule hypothèse qui ne se retourne jamais contre toi.'),
  ('q-0263', 'Gagner de l''argent est un art, travailler est un art et faire de bonnes affaires est le plus bel art.', 'Andy Warhol', 'finance', null, null, null, 'Warhol place le commerce au même rang que la création. La formule provoque, mais elle désigne un vrai travail : concevoir un modèle viable demande autant d''invention qu''une œuvre.', 'Traite la conception de ton modèle économique comme un travail créatif à part entière, pas comme une contrainte administrative à expédier.'),
  ('q-0264', 'Le secret des affaires est de savoir quelque chose que personne ne sait.', 'Aristote Onassis', 'finance', null, null, null, 'Onassis désigne l''asymétrie d''information comme source d''avantage. Savoir ce que les autres ignorent — un besoin, un fournisseur, un signal — vaut plus que la compétence partagée.', 'Identifie ce que tu sais et que tes concurrents ignorent. Si tu ne trouves rien, ton premier chantier est d''aller chercher cette information.'),
  ('q-0265', 'Vous n''êtes jamais trop vieux pour fixer un nouvel objectif ou rêver un nouveau rêve.', 'C.S. Lewis', 'mindset', null, null, null, 'Lewis conteste l''idée d''échéance sur les projets personnels. La limite est presque toujours une croyance sur l''âge convenable, pas une contrainte réelle.', 'Si tu renonces à quelque chose à cause de ton âge, vérifie ce qui l''empêche concrètement. La réponse est rarement autre chose qu''une convention.'),
  ('q-0266', 'Seul, nous pouvons faire si peu ; ensemble, nous pouvons faire tant.', 'Helen Keller', 'leadership', null, null, null, 'Keller décrit un effet de composition : les capacités individuelles s''additionnent mais surtout se complètent, ce qui rend le collectif capable de choses qu''aucun membre ne pourrait entreprendre seul.', 'Sur ton objectif le plus ambitieux, liste ce qui te manque et cherche qui le possède. Réunir des compétences complémentaires va plus vite que de toutes les acquérir.'),
  ('q-0267', 'Le succès n''est pas la clé du bonheur. Le bonheur est la clé du succès.', 'Albert Schweitzer', 'mindset', null, null, null, 'Schweitzer inverse la séquence habituelle : on attend le bonheur du succès, alors que c''est l''état intérieur qui permet le travail durable qui produit le succès.', 'Avant d''attendre qu''un résultat te rende satisfait, regarde si ton travail actuel est tenable. Un métier qui t''épuise ne deviendra pas agréable en réussissant.'),
  ('q-0268', 'La seule limite à notre réalisation de demain sera nos doutes d''aujourd''hui.', 'Franklin D. Roosevelt', 'mindset', null, null, null, 'Roosevelt, s''adressant à un pays en crise, désigne le doute comme la contrainte principale — avant les moyens. Ce qu''on renonce à tenter aujourd''hui fixe la limite de ce qui sera possible demain.', 'Liste ce que tu n''as pas tenté cette année par manque de confiance plutôt que de moyens. C''est cette liste qui dessine ton plafond réel.'),
  ('q-0269', 'Ce n''est pas que je sois si intelligent, c''est juste que je reste avec les problèmes plus longtemps.', 'Albert Einstein', 'mindset', null, null, null, 'Einstein attribue ses résultats à l''endurance sur un problème plutôt qu''à une capacité supérieure. C''est le temps passé sans abandonner qui fait la différence, pas la vitesse de compréhension.', 'Face à un problème difficile, prolonge ton effort au-delà du point où tu abandonnes d''habitude. C''est souvent juste après que la solution apparaît.'),
  ('q-0270', 'Le succès est la somme de petits efforts, répétés jour après jour.', 'Robert Collier', 'mindset', null, null, null, 'Collier décrit un effet d''accumulation : ce sont des gestes modestes, répétés, qui produisent des résultats importants. L''effort ponctuel intense n''a pas le même rendement.', 'Préfère trente minutes tous les jours à une journée entière par mois. La régularité produit un cumul que l''intensité ponctuelle n''atteint pas.'),
  ('q-0271', 'La force de l''équipe, c''est chaque membre. La force de chaque membre, c''est l''équipe.', 'Phil Jackson', 'leadership', null, null, null, 'Jackson décrit une dépendance réciproque : le collectif tire sa force des individus, et chaque individu tire la sienne du collectif. Renforcer l''un renforce l''autre.', 'Quand tu développes quelqu''un, explique en quoi cela sert l''équipe. Et quand tu renforces l''équipe, montre ce que chacun y gagne individuellement.'),
  ('q-0272', 'Fixer des objectifs est le premier pas pour transformer l''invisible en visible.', 'Tony Robbins', 'mindset', null, null, null, 'Robbins décrit la fixation d''objectif comme un acte de matérialisation : tant qu''une intention reste dans la tête, elle n''a ni forme, ni échéance, ni moyen de vérification.', 'Écris ton objectif noir sur blanc, avec une date. Le simple fait de le sortir de ta tête le rend évaluable, donc actionnable.'),
  ('q-0273', 'L''avenir appartient à ceux qui croient à la beauté de leurs rêves.', 'Eleanor Roosevelt', 'mindset', null, null, null, 'Roosevelt lie l''avenir à la conviction : ceux qui ne croient pas à leur projet ne le poursuivent pas assez longtemps pour qu''il aboutisse. La croyance n''est pas magique, elle est ce qui fait durer l''effort.', 'Si tu doutes de ton projet, cherche la preuve qui te convaincrait et va la chercher. Un projet qu''on ne croit pas ne survit pas aux difficultés.'),
  ('q-0274', 'Croyez que vous pouvez et vous êtes déjà à mi-chemin.', 'Theodore Roosevelt', 'mindset', null, null, null, 'Roosevelt ne prétend pas que la confiance produise le résultat, mais qu''elle conditionne l''engagement. Celui qui doute engage la moitié de ses moyens, et échoue alors pour une raison qui n''a rien à voir avec la difficulté réelle.', 'Avant de te lancer, sépare ce qui est objectivement difficile de ce que tu crois hors de ta portée. Le premier appelle une préparation, le second appelle une preuve — souvent un premier essai limité.'),
  ('q-0275', 'Ce qui est derrière nous et ce qui est devant nous sont de petites choses comparées à ce qui est en nous.', 'Ralph Waldo Emerson', 'mindset', null, null, null, 'Emerson relativise le passé et l''avenir face aux ressources internes. Les regrets et les projections occupent l''essentiel de l''attention alors qu''ils ne sont pas actionnables ; ce qui l''est se trouve ailleurs.', 'Quand tu tournes en boucle sur une erreur passée ou une incertitude future, ramène la question à ce que tu peux faire aujourd''hui avec ce que tu es. C''est la seule des trois zones où l''action existe.'),
  ('q-0276', 'Si ce que vous faites ne vous rapproche pas de vos buts, alors c''est que ça vous en éloigne.', 'Brian Tracy', 'mindset', null, null, null, 'Tracy ferme la position neutre : le temps passe de toute façon, donc une activité qui ne rapproche pas d''un objectif consomme la ressource sans contrepartie. Il n''y a pas d''action sans effet.', 'Passe tes activités récurrentes au test : celle-ci me rapproche-t-elle de quelque chose ? Ce qui ne passe pas le test mérite d''être supprimé ou assumé comme du repos.'),
  ('q-0277', 'En matière commerciale, le succès vient davantage de l''attitude que de l''aptitude.', 'Michael Aguilar', 'sales', null, null, null, 'Aguilar place l''attitude devant la technique en matière commerciale. Les compétences s''acquièrent ; l''engagement, l''écoute et la constance déterminent si elles seront utilisées.', 'Avant de suivre une formation commerciale, vérifie ce que tu appliques déjà de ce que tu sais. C''est souvent là que se trouve la marge.'),
  ('q-0278', 'Les 5 freins à toute vente : pas de besoin, pas de budget, pas d''urgence, pas d''envie, pas de confiance.', 'Zig Ziglar', 'sales', null, null, null, 'Grille de diagnostic : un refus est rarement un « non » global, c''est l''un de ces cinq blocages en particulier. Les traiter séparément évite d''insister sur le prix quand le problème est la confiance.', 'Après un refus, identifie lequel des cinq freins était en cause. Selon la réponse, la suite est une relance, une preuve, une remise ou un abandon — quatre actions totalement différentes.'),
  ('q-0279', 'Si les gens vous apprécient, ils vous écouteront, mais s''ils ont confiance en vous, ils feront affaire avec vous.', 'Zig Ziglar', 'sales', null, null, null, 'Ziglar hiérarchise deux niveaux qu''on confond : la sympathie ouvre la conversation, la confiance conclut l''affaire. Être apprécié est nécessaire mais ne suffit jamais à faire signer.', 'Demande-toi ce qui, dans ton dossier, prouve ce que tu avances — références, chiffres, engagement écrit. La sympathie ne se démontre pas, la fiabilité si.'),
  ('q-0280', 'La vente est essentiellement un transfert de sentiments.', 'Zig Ziglar', 'sales', null, null, null, 'Ziglar décrit ce qui se joue réellement dans une vente : le client n''achète pas ta conviction par le raisonnement, il la ressent. Si tu n''es pas convaincu, aucune argumentation ne compensera.', 'Avant un rendez-vous, vérifie que tu crois toi-même à ce que tu proposes pour ce client-là. Si ce n''est pas le cas, l''honnêteté te servira mieux que la technique.'),
  ('q-0281', 'Nous considérons nos clients comme des invités, à une fête où nous sommes les hôtes.', 'Jeff Bezos', 'sales', null, null, null, 'L''image de l''hôte déplace la relation : un invité n''a pas à réclamer, c''est l''hôte qui anticipe. Bezos transforme une obligation contractuelle en devoir d''attention, ce qui relève le niveau d''exigence bien au-delà du service minimum.', 'Repère un moment où ton client doit faire une démarche pour obtenir quelque chose de normal — relancer, réclamer, chercher. Chacun de ces moments est une chose que l''hôte aurait dû prévoir.'),
  ('q-0282', 'Mettre le client en premier. Inventer. Et être patient.', 'Jeff Bezos', 'sales', null, null, null, 'Trois principes qui ne fonctionnent qu''ensemble. Servir le client sans inventer mène à la stagnation ; inventer sans patience fait abandonner avant que ça prenne ; être patient sans les deux autres n''est que de l''attente.', 'Vérifie que tes priorités actuelles cochent les trois. S''il en manque une, c''est généralement la patience — et c''est celle qui coûte le plus cher à négliger.'),
  ('q-0283', 'Ne trouvez pas des clients pour vos produits, trouvez des produits pour vos clients.', 'Seth Godin', 'sales', null, null, null, 'Godin inverse la démarche : partir du produit oblige à chercher qui pourrait le vouloir ; partir d''un groupe de personnes permet de construire ce qu''elles attendent. Le second sens est bien plus efficace.', 'Définis précisément à qui tu t''adresses avant de définir ce que tu vends. Un public net rend l''offre presque évidente.'),
  ('q-0284', 'Nous plaçons le client en numéro un, l''employé en numéro deux, l''actionnaire en numéro trois.', 'Jack Ma', 'sales', null, null, null, 'Jack Ma fixe un ordre de priorité qui inverse la doctrine actionnariale. La logique est séquentielle : des clients servis font une entreprise saine, qui finit par récompenser l''actionnaire — l''inverse ne fonctionne pas.', 'Quand deux intérêts s''opposent, vérifie lequel produit l''autre. Sacrifier le client pour le résultat trimestriel détruit précisément ce qui génère le résultat.'),
  ('q-0285', 'On se souvient de la qualité bien plus longtemps que du prix.', 'Guccio Gucci', 'sales', null, null, null, 'Gucci oppose deux durées : la douleur du prix est immédiate et s''oublie, l''expérience de la qualité dure et se raconte. C''est un argument contre l''optimisation par le bas.', 'Avant de rogner sur la qualité pour tenir un prix, demande-toi ce dont le client se souviendra dans un an. Ce n''est presque jamais le montant.'),
  ('q-0287', 'Il ne sert à rien d''être le meilleur si on est le seul à le savoir.', 'Richard Branson', 'sales', null, null, null, 'L''excellence non communiquée n''existe pas commercialement. Branson ne fait pas l''éloge du marketing tapageur : il rappelle qu''un client ne peut pas choisir ce qu''il ignore, quelle que soit la qualité réelle.', 'Fais l''inventaire de ce que tu fais mieux que les autres et vérifie que chaque point apparaît quelque part de visible. Ce qui n''est écrit nulle part n''entre pas dans la décision du client.'),
  ('q-0289', 'L''entreprise est élue tous les jours par ses clients.', 'François Michelin', 'sales', null, null, null, 'Michelin décrit le marché comme un vote quotidien : chaque achat est un mandat renouvelé, chaque abandon un retrait. Aucune position n''est acquise, quelle que soit l''ancienneté.', 'Regarde ton taux de réachat plutôt que ton nombre de clients. Le premier mesure le mandat renouvelé, le second un cumul historique.'),
  ('q-0290', 'La philosophie commerciale nous enseigne que celui qui ne demande rien n''a rien, et il est déçu.', 'Jean-Jacques Servan-Schreiber', 'sales', null, null, null, 'Servan-Schreiber rappelle une évidence commerciale négligée : la plupart des occasions manquées le sont faute d''avoir demandé. Le refus est un risque limité, l''absence de demande est un refus certain.', 'Fais cette semaine la demande que tu repousses. Le pire résultat possible est celui que tu as déjà en ne demandant pas.'),
  ('q-0292', 'Quand on ne sait pas où on va, tous les chemins mènent un peu nulle part.', 'Henry Kissinger', 'leadership', null, null, null, 'Kissinger décrit l''inutilité du mouvement sans cap : sans destination, aucun chemin n''est meilleur qu''un autre, donc aucun progrès n''est mesurable.', 'Avant d''arbitrer entre plusieurs options, écris ce que tu cherches à obtenir. Sans ce critère, tu choisiras sur des impressions.'),
  ('q-0293', 'Si vous voulez vous élever, élevez quelqu''un d''autre.', 'Booker T. Washington', 'leadership', null, null, null, 'Washington décrit une élévation par réciprocité : aider quelqu''un à progresser crée des liens, de la réputation et des compétences qui reviennent. Ce n''est pas seulement moral, c''est efficace.', 'Consacre du temps chaque mois à faire progresser quelqu''un sans contrepartie. Le retour arrive rarement de la personne aidée, mais il arrive.'),
  ('q-0294', 'L''attitude détermine les actions. Les actions déterminent les résultats.', 'Jim Rohn', 'leadership', null, null, null, 'Rohn décrit une chaîne : l''attitude oriente les actions, les actions produisent les résultats. On ne peut donc pas corriger un résultat sans remonter au moins jusqu''aux actions, souvent jusqu''à l''attitude.', 'Face à un résultat décevant, remonte la chaîne au lieu de fixer un nouvel objectif. Le même état d''esprit produira les mêmes actions et les mêmes chiffres.'),
  ('q-0295', 'Un leader est quelqu''un qui connaît le chemin, qui suit le chemin, et qui montre le chemin.', 'John C. Maxwell', 'leadership', null, null, null, 'Maxwell décompose le leadership en trois exigences cumulatives : la compétence (connaître), l''exemplarité (suivre soi-même), et la transmission (montrer). Il manque toujours l''une des trois chez ceux qui échouent à entraîner.', 'Repère laquelle des trois te fait défaut. Un dirigeant qui sait mais n''applique pas perd sa crédibilité ; un qui applique mais n''explique pas ne forme personne.'),
  ('q-0296', 'Si vous ne pouvez pas contrôler vos émotions, vous ne pouvez pas contrôler votre argent.', 'Warren Buffett', 'finance', null, null, null, 'L''obstacle n''est pas technique mais comportemental. La peur pousse à vendre au pire moment, l''avidité à acheter au pire prix : les décisions se prennent sous émotion et se justifient ensuite par des chiffres choisis exprès.', 'Note ta décision et son motif avant d''agir, jamais après. Relire ce que tu pensais au moment du choix est le seul moyen de distinguer un raisonnement d''une réaction.'),
  ('q-0297', 'Règle numéro un : ne perdez jamais d''argent. Règle numéro deux : n''oubliez jamais la règle numéro un.', 'Warren Buffett', 'finance', null, null, null, 'La règle n''interdit pas de perdre, elle hiérarchise : préserver le capital passe avant le rendement, parce qu''une perte de 50 % exige ensuite 100 % de gain pour revenir à l''équilibre. Les mathématiques ne sont pas symétriques.', 'Avant chaque engagement, chiffre ce que tu perds si tout se passe mal, pas seulement ce que tu gagnes si tout va bien. Si le scénario noir te met en danger, réduis la taille plutôt que d''espérer.'),
  ('q-0299', 'En bourse, tu as deux choix : t''enrichir lentement ou t''appauvrir rapidement.', 'Benjamin Graham', 'finance', null, null, null, 'Graham oppose deux régimes de vitesse : l''enrichissement progressif fonctionne mais demande du temps, tandis que la recherche de gains rapides expose à des pertes tout aussi rapides. Il n''existe pas de version accélérée du premier.', 'Avant d''accepter une promesse de rendement élevé et rapide, demande d''où vient exactement l''argent. Une réponse floue est en soi la réponse.'),
  ('q-0300', 'La chance ne sourit qu''aux esprits bien préparés.', 'Louis Pasteur', 'mindset', null, null, null, 'Pasteur relie la chance à la préparation : les occasions se présentent à beaucoup de gens, seuls ceux qui étaient prêts les reconnaissent et les exploitent.', 'Prépare-toi pour l''occasion que tu espères sans pouvoir la provoquer. C''est ce travail invisible qui décidera si tu peux la saisir.'),
  ('q-0301', 'L''enthousiasme est une maladie contagieuse.', 'Voltaire', 'mindset', null, null, null, 'Voltaire décrit la contagion de l''enthousiasme : il se transmet d''une personne à l''autre indépendamment des arguments. C''est un constat sur les mécanismes collectifs, valable en bien comme en mal.', 'Avant de présenter un projet, vérifie que tu y crois toi-même. Ce qui se transmet à ton auditoire, c''est ton état, pas tes diapositives.'),
  ('q-0302', 'Accepter l''idée de la défaite, c''est être déjà vaincu.', 'Général Foch', 'mindset', null, null, null, 'Foch décrit une défaite qui précède le combat : accepter mentalement l''issue négative supprime l''effort qui aurait pu l''éviter. La conviction préalable devient prédiction autoréalisatrice.', 'Quand tu abordes une échéance en la considérant perdue, mesure ce que tu cesses de faire du fait de cette conviction. C''est souvent là que se joue le résultat.'),
  ('q-0303', 'Ne pensez pas à l''échec, pensez aux opportunités que vous risquez de manquer.', 'Jack Canfield', 'mindset', null, null, null, 'Canfield déplace l''attention du risque vers le coût de l''inaction. Penser à l''échec paralyse ; penser aux occasions perdues remet en mouvement.', 'Face à une hésitation, liste ce que tu perds en ne faisant rien. Cette colonne est presque toujours moins visible et plus lourde.'),
  ('q-0304', 'Vous risquez d''être déçu si vous échouez, mais vous êtes condamné si vous n''essayez pas.', 'Beverly Sills', 'mindset', null, null, null, 'Sills compare deux issues : l''échec produit une déception dont on se remet, le renoncement produit une certitude définitive. Le second est plus sûr et plus coûteux.', 'Quand tu évalues un risque, compare-le à l''issue certaine de ne pas essayer. La comparaison est rarement à l''avantage de l''abstention.'),
  ('q-0305', 'Être conscient de son ignorance est le premier pas vers la connaissance.', 'Benjamin Disraeli', 'mindset', null, null, null, 'Disraeli fait de la conscience de son ignorance le point de départ : on ne cherche pas ce qu''on croit déjà savoir. Reconnaître le manque est ce qui déclenche l''apprentissage.', 'Sur ton domaine d''expertise, dresse la liste de ce que tu ne maîtrises pas. Cette liste est ton plan de formation le plus utile.'),
  ('q-0308', 'La façon la plus courante d''abandonner son pouvoir, c''est de penser qu''on n''en a pas.', 'Alice Walker', 'mindset', null, null, null, 'Walker décrit une abdication silencieuse : croire qu''on n''a aucune marge de manœuvre supprime l''usage qu''on aurait pu en faire. Le pouvoir non exercé équivaut au pouvoir absent.', 'Dans une situation que tu subis, identifie une seule chose que tu peux décider. L''exercer, même à petite échelle, change le rapport à la situation.'),
  ('q-0312', 'Le leadership n''a rien à voir avec les titres. C''est la capacité à influencer d''autres vies.', 'John C. Maxwell', 'leadership', null, null, null, 'Maxwell sépare l''autorité formelle de l''influence réelle. Le titre garantit qu''on t''obéira, pas qu''on te suivra — et la différence apparaît exactement quand les choses deviennent difficiles.', 'Demande-toi qui viendrait te demander conseil si tu n''avais plus de titre. La réponse mesure ton influence réelle, pas ton organigramme.'),
  ('q-0314', 'À une époque, le leadership résidait dans les muscles. Aujourd''hui, il réside dans la façon de traiter les gens.', 'Mahatma Gandhi', 'leadership', null, null, null, 'Gandhi décrit un déplacement historique de la source d''autorité : de la force physique vers la qualité de la relation. Ce qui fait suivre aujourd''hui n''est plus la capacité à contraindre.', 'Regarde ce sur quoi repose ton autorité : la position, ou la façon dont tu traites les gens. Seule la seconde survit à un changement d''organigramme.'),
  ('q-0316', 'Le leader est celui qui sait inspirer sans éteindre, diriger sans écraser.', 'Maya Angelou', 'leadership', null, null, null, 'Angelou décrit un équilibre difficile : donner une direction sans confisquer l''initiative. Un leader qui écrase obtient de l''exécution, jamais de l''engagement — et l''exécution seule ne suffit pas quand l''imprévu arrive.', 'Après ta prochaine réunion, demande-toi qui a parlé et qui s''est tu. Le silence systématique de quelqu''un de compétent est un signal sur ta façon de diriger, pas sur lui.'),
  ('q-0317', 'Les gens n''achètent pas ce que vous faites, ils achètent pourquoi vous le faites.', 'Simon Sinek', 'leadership', null, 'Commencer par pourquoi', 2009, 'Sinek explique pourquoi deux produits identiques ne se vendent pas pareil : le client n''achète pas une fiche technique, il achète une intention à laquelle il s''identifie. Le « pourquoi » ne se copie pas, contrairement au « quoi ».', 'Réécris ta page d''accueil en commençant par la conviction qui t''a fait démarrer, et ne place les caractéristiques qu''ensuite. Si l''ordre inverse te paraît plus naturel, c''est que ta conviction n''est pas encore formulée.'),
  ('q-0318', 'La fonction du leadership est de produire d''autres leaders, pas plus de suiveurs.', 'Ralph Nader', 'leadership', null, null, null, 'Nader donne un critère d''évaluation du leadership : le nombre de personnes devenues autonomes, pas le nombre de personnes qui suivent. Un dirigeant qui produit de la dépendance a échoué.', 'Compte combien de personnes de ton équipe pourraient assumer ton rôle. Ce chiffre mesure ton efficacité mieux que ta charge de travail.'),
  ('q-0319', 'Tout le monde porte un panneau invisible autour du cou qui dit : faites-moi sentir que je suis important.', 'Mary Kay Ash', 'leadership', null, null, null, 'Ash décrit un besoin universel de reconnaissance, généralement invisible parce que personne ne le formule. Le prendre en compte coûte peu et change la qualité des relations.', 'Formule un retour positif précis à quelqu''un cette semaine — précis, pas général. C''est la précision qui rend la reconnaissance crédible.'),
  ('q-0320', 'Avant d''être un leader, le succès consiste à se développer soi-même. Une fois leader, le succès consiste à faire grandir les autres.', 'Jack Welch', 'leadership', null, null, null, 'Welch décrit un basculement de métier au moment de devenir dirigeant : ce qui était mesuré par sa propre performance l''est désormais par celle des autres. Beaucoup échouent en continuant à exceller personnellement.', 'Si tu diriges, mesure ta semaine à ce que ton équipe a pu faire grâce à toi, pas à ce que tu as produit toi-même. Le second chiffre est flatteur et trompeur.'),
  ('q-0321', 'Les leaders ne naissent pas, ils sont faits. Et ils sont faits par l''effort acharné.', 'Vince Lombardi', 'leadership', null, null, null, 'Lombardi écarte le talent inné au profit de la construction. Le leadership se fabrique par un travail répété, ce qui le rend accessible — mais coûteux.', 'Traite le leadership comme une compétence à travailler : demande un retour après chaque réunion que tu animes. C''est la répétition corrigée qui construit, pas l''expérience seule.'),
  ('q-0322', 'Soyez craintifs quand les autres sont avides. Soyez avide quand les autres sont craintifs.', 'Warren Buffett', 'finance', 'Écrite après le krach d''octobre 1987, en review de l''exercice 1986 : Buffett y résume sa discipline face aux mouvements de foule du marché.', 'Lettre aux actionnaires de Berkshire Hathaway', 1986, 'Buffett décrit un contre-mouvement délibéré. Les prix sont le plus attractifs quand l''ambiance est la plus mauvaise, et les plus dangereux quand tout le monde est confiant — l''inconfort ressenti est donc souvent le signal, pas l''avertissement.', 'Quand une décision fait l''unanimité autour de toi, prends dix minutes pour écrire l''argument inverse. L''objectif n''est pas de le suivre, mais de vérifier que ton accord vient de l''analyse et non de l''ambiance.'),
  ('q-0323', 'Si vous n''êtes pas prêt à détenir une action pendant 10 ans, ne pensez même pas à la détenir pendant 10 minutes.', 'Warren Buffett', 'finance', 'Dans le même texte que le principe de détention « pour toujours » : un investissement se juge sur l''entreprise, jamais sur l''horizon qu''on lui impose.', 'Lettre aux actionnaires de Berkshire Hathaway', 1996, 'Formulation frappante d''un principe simple : la durée de détention ne dépend pas de l''humeur du marché mais de la qualité de ce qu''on détient. Si dix ans font peur, le problème est l''actif lui-même, pas l''horizon.', 'Applique le test à tes engagements en cours, professionnels compris. Ceux que tu ne renouvellerais pas pour dix ans méritent d''être réexaminés maintenant plutôt qu''à l''échéance.'),
  ('q-0324', 'Il ne s''agit pas de prédire la pluie, il s''agit de construire l''arche.', 'Warren Buffett', 'finance', 'La « règle de Noé » : Buffett l''a formulée après avoir lui-même sous-estimé un risque, pour dire qu''anticiper ne vaut rien sans s''y préparer réellement.', 'Lettre aux actionnaires de Berkshire Hathaway', 1981, 'La « règle de Noé » sépare la lucidité de la préparation. Voir venir un risque ne protège de rien : seule compte la mesure prise avant qu''il se réalise. Buffett vise ceux qui commentent justement une menace sans jamais agir en conséquence.', 'Prends le risque que tu identifies depuis des mois sans rien changer. Décide d''une mesure concrète cette semaine, même modeste : c''est l''arche, pas la prévision, qui fait la différence.'),
  ('q-0325', 'Les quatre mots les plus dangereux dans le monde de l''investissement sont : « cette fois, c''est différent ».', 'John Templeton', 'finance', null, null, null, 'Templeton désigne la formule qui précède les pires erreurs : croire que les règles habituelles ne s''appliquent plus. Chaque bulle s''est construite sur cette conviction.', 'Quand on te dit qu''une situation est sans précédent, cherche les précédents. Ils existent presque toujours, et ils finissent de la même façon.'),
  ('q-0326', 'La patience est la clé de l''investissement réussi.', 'John Templeton', 'finance', null, null, null, 'Templeton place la patience au rang de compétence principale, avant l''analyse : les résultats supposent de laisser du temps au raisonnement pour se vérifier.', 'Fixe ton horizon avant d''engager quoi que ce soit, et note-le. C''est cette décision écrite à froid qui te tiendra quand l''agitation reviendra.'),
  ('q-0327', 'Ne cherchez pas l''aiguille dans la meule de foin : achetez la meule.', 'John C. Bogle', 'finance', null, null, null, 'Bogle défend l''approche indicielle par une image : plutôt que de chercher la bonne valeur, détenir l''ensemble du marché. Cela supprime le risque de sélection au prix de renoncer à surperformer.', 'Quand tu ne peux pas identifier le meilleur choix, demande-toi si tu peux diversifier plutôt que parier. C''est souvent la décision la plus solide.'),
  ('q-0328', 'Investissez dans ce que vous connaissez.', 'Peter Lynch', 'finance', null, null, null, 'Lynch recommande de rester dans son périmètre de compréhension. Investir dans ce qu''on ne comprend pas revient à déléguer son jugement à d''autres, sans pouvoir évaluer s''ils ont raison.', 'Avant de t''engager, vérifie que tu peux expliquer le modèle économique en quelques phrases. Si tu t''appuies sur du vocabulaire que tu ne maîtrises pas, tu ne décides pas, tu suis.'),
  ('q-0329', 'Investir n''est pas battre les autres à leur jeu. Il s''agit de se contrôler soi-même.', 'Benjamin Graham', 'finance', null, null, null, 'Graham déplace la difficulté : le principal adversaire n''est pas le marché ni les autres investisseurs, mais ses propres réactions. La compétence recherchée est comportementale avant d''être analytique.', 'Écris tes règles de décision à froid et engage-toi à les relire avant d''agir. C''est leur existence écrite, pas ta discipline du moment, qui te protège de l''impulsion.'),
  ('q-0330', 'Les riches investissent leur argent et dépensent ce qui reste.', 'Robert Kiyosaki', 'finance', null, null, null, 'Kiyosaki inverse l''ordre habituel des opérations. La plupart dépensent puis épargnent ce qui reste — et il ne reste jamais rien. Placer l''épargne en premier la rend structurelle plutôt que résiduelle.', 'Programme un virement automatique le jour de ta paie, avant toute dépense. L''automatisme supprime la décision mensuelle, qui est le vrai point de fuite.'),
  ('q-0331', 'Les pauvres et la classe moyenne travaillent pour de l''argent. Les riches font travailler l''argent.', 'Robert Kiyosaki', 'finance', null, null, null, 'Kiyosaki distingue deux rapports à l''argent : l''échanger contre son temps, ce qui plafonne aux heures disponibles, ou le faire produire, ce qui déplafonne mais suppose d''en immobiliser.', 'Identifie une source de revenu qui ne dépende pas directement de tes heures. Même modeste au départ, c''est la structure qui compte, pas le montant initial.'),
  ('q-0332', 'L''éducation obligatoire amène un salaire, l''éducation personnelle amène la fortune.', 'Robert Kiyosaki', 'finance', null, null, null, 'Kiyosaki oppose deux formations : celle qui prépare à occuper un poste, et celle qu''on va chercher soi-même — négociation, gestion, vente. La seconde n''est enseignée nulle part et détermine pourtant l''essentiel.', 'Choisis un sujet financier ou commercial que l''école ne t''a pas appris et consacre-lui un livre par trimestre. Le retour sur ce temps dépasse largement celui d''une heure supplémentaire travaillée.'),
  ('q-0333', 'L''important n''est pas d''avoir raison ou tort, mais de savoir combien d''argent on gagne quand on a raison.', 'George Soros', 'finance', null, null, null, 'Soros dissocie la justesse du résultat : avoir raison souvent sur de petites positions rapporte moins qu''avoir raison rarement sur des positions bien dimensionnées. Ce qui compte est l''ampleur, pas la fréquence.', 'Quand tu répartis tes efforts, concentre-les là où tu as le plus de conviction. Traiter tous les paris de la même façon dilue ce que tu sais.'),
  ('q-0334', 'Le moment d''acheter, c''est quand le sang coule dans les rues.', 'Nathan Rothschild', 'finance', null, null, null, 'La formule décrit l''achat en période de panique, quand les prix s''effondrent avec le sentiment. Elle est brutale et suppose surtout d''avoir des réserves quand les autres n''en ont plus.', 'Constitue tes réserves en période calme. La capacité à agir quand tout le monde recule dépend entièrement de ce qui a été mis de côté avant.'),
  ('q-0335', 'On apprend beaucoup plus de ses pertes que de ses gains.', 'Paul Tudor Jones', 'finance', null, null, null, 'Jones note que les pertes enseignent mieux que les gains, parce qu''elles obligent à comprendre ce qui a échoué, tandis que le succès n''invite à aucune analyse.', 'Après une perte, écris ce que tu ferais différemment. Après un gain, écris ce qui relevait de la chance. Le second exercice est plus difficile et plus utile.'),
  ('q-0336', 'N''essayez pas d''acheter aux points bas et de vendre aux points hauts. Seuls les menteurs peuvent faire ça.', 'Bernard Baruch', 'finance', null, null, null, 'Baruch écarte l''idée de timing parfait : personne ne repère le sommet ni le creux autrement que rétrospectivement. Ceux qui prétendent le faire décrivent un passé reconstruit.', 'Renonce à viser le moment optimal et vise plutôt la régularité. Une méthode appliquée systématiquement bat une intuition appliquée parfois.'),
  ('q-0337', 'La vente commence quand le client dit : non.', 'Elmer G. Leterman', 'sales', null, null, null, 'Leterman renverse la lecture du refus : le « non » n''est pas la fin de l''échange, c''est le moment où le travail commence — comprendre l''objection, y répondre, ou reconnaître que ça ne convient pas.', 'Après un refus, pose une question de plus au lieu de conclure. Tu apprendras soit comment avancer, soit pourquoi ce n''était pas le bon client.'),
  ('q-0338', 'La raison d''être d''une entreprise est de créer et de garder un client.', 'Theodore Levitt', 'sales', null, null, null, 'Levitt réduit la finalité de l''entreprise à deux verbes : créer un client, puis le garder. Le profit en découle et n''est pas l''objectif — le poser comme tel conduit à sacrifier le second verbe.', 'Vérifie que tes objectifs couvrent les deux temps. Beaucoup d''organisations mesurent l''acquisition et ignorent la conservation, qui coûte pourtant bien moins cher.'),
  ('q-0339', 'Prenez soin du client et l''entreprise prendra soin d''elle-même.', 'Ray Kroc', 'sales', null, null, null, 'Kroc énonce une causalité : la santé de l''entreprise découle du soin apporté au client, pas l''inverse. Surveiller les chiffres sans surveiller le service revient à regarder le thermomètre plutôt que le malade.', 'Choisis un indicateur de qualité client et suis-le aussi sérieusement que ton chiffre d''affaires. Le second se corrige rarement sans le premier.'),
  ('q-0340', 'Le service client ne doit pas être uniquement un service, il doit concerner l''ensemble de l''entreprise.', 'Tony Hsieh', 'sales', null, null, null, 'Hsieh conteste l''idée d''un service client cantonné à un service : la qualité de l''expérience dépend de la production, de la facturation, de la logistique. La confier à une équipe isolée garantit son échec.', 'Fais lire les réclamations clients à des équipes qui ne sont pas au contact. Ce sont souvent elles qui détiennent la cause du problème.'),
  ('q-0341', 'Un client qui n''a qu''un seul fournisseur cesse d''être intelligent.', 'François Michelin', 'sales', null, null, null, 'Michelin observe qu''un client en situation de dépendance perd sa capacité de comparaison, donc d''exigence. C''est un avertissement pour l''acheteur, mais aussi pour le fournisseur qui s''endort sur cette rente.', 'Si un client dépend entièrement de toi, ne t''en félicite pas : c''est le moment où ta compétitivité cesse d''être testée. Vérifie régulièrement que tu resterais choisi.'),
  ('q-0342', 'Ce qui compte, c''est le chiffre un : une tasse, un client, un partenaire.', 'Howard Schultz', 'sales', null, null, null, 'Schultz ramène l''échelle à l''unité : la qualité se joue sur une transaction, pas sur une moyenne. Un client mal servi ne se console pas d''un taux de satisfaction global.', 'Cesse de juger uniquement sur des moyennes. Regarde un cas réel en détail chaque semaine — c''est là que les défauts apparaissent.'),
  ('q-0344', 'Un objectif correctement défini est à moitié atteint.', 'Zig Ziglar', 'sales', null, null, null, 'Ziglar attribue la moitié du résultat à la formulation. Un objectif flou ne se planifie pas, ne se mesure pas et ne se sait jamais atteint ; le préciser fait apparaître les étapes qui étaient invisibles.', 'Reprends ton objectif principal et ajoute-lui un chiffre et une date. S''il résiste à cet exercice, ce n''est pas encore un objectif mais une intention.'),
  ('q-0345', 'Pour une vente manquée par excès d''enthousiasme, on en compte cent manquées par faute d''enthousiasme.', 'Zig Ziglar', 'sales', null, null, null, 'Ziglar corrige une peur mal placée : les commerciaux se retiennent de crainte d''en faire trop, alors que le défaut d''engagement est cent fois plus coûteux. Le silence et la tiédeur ne rassurent pas, ils désintéressent.', 'Si tu hésites à relancer par peur d''insister, mesure d''abord combien de tes dossiers meurent faute de nouvelle. La réponse te dira de quel côté est ton vrai risque.'),
  ('q-0346', 'Le marketing ne consiste pas à vendre ce que vous produisez, mais à connaître ce dont le consommateur a besoin.', 'Philip Kotler', 'sales', null, null, null, 'Kotler inverse le point de départ du marketing : il ne s''agit pas d''écouler une production décidée en amont, mais de partir du besoin pour définir ce qu''on produit. Le sens de la démarche change tout le reste.', 'Avant de développer une offre, va parler à dix clients potentiels de leur problème sans mentionner ta solution. Ce que tu apprendras là modifiera souvent l''offre elle-même.'),
  ('q-0347', 'L''objectif de la vente est de satisfaire un besoin client, celui du marketing est de comprendre ce besoin.', 'Philip Kotler', 'sales', null, null, null, 'Kotler répartit les rôles : le marketing comprend le besoin en amont, la vente y répond au contact. Confondre les deux conduit à vendre sans avoir compris, ce qui rend chaque vente plus difficile que nécessaire.', 'Sépare explicitement le temps que tu consacres à comprendre ton marché de celui que tu passes à vendre. Si le premier est nul, le second sera épuisant.'),
  ('q-0348', 'Le marketing s''apprend en un jour ; il faut toute une vie pour le maîtriser.', 'Philip Kotler', 'sales', null, null, null, 'Kotler distingue les principes, simples et rapides à énoncer, de leur application, qui dépend d''un contexte toujours particulier. C''est un avertissement contre la confiance acquise après une lecture.', 'Applique un seul principe marketing à la fois et mesure ce qu''il donne chez toi. Les règles générales ne valent que confrontées à ton marché précis.'),
  ('q-0349', 'Il est impossible d''être chef d''entreprise sans un minimum d''audace.', 'Carlos Ghosn', 'leadership', null, null, null, 'Ghosn pose l''audace comme condition d''exercice, pas comme trait de caractère : diriger suppose de trancher avec une information incomplète, ce qu''aucune analyse supplémentaire ne supprime.', 'Face à une décision où l''information manquera toujours, fixe-toi un seuil : à partir de quel niveau de certitude tu tranches. Sans ce seuil, tu attends indéfiniment.'),
  ('q-0351', 'Si vous vous limitez aux avis des experts, il y a peu de chances que vous innoviez.', 'Carlos Ghosn', 'leadership', null, null, null, 'Ghosn observe que l''expertise raisonne à partir de l''existant : elle sait ce qui a été essayé et ce qui a échoué, ce qui la rend précieuse pour éviter les erreurs et médiocre pour créer du neuf.', 'Consulte les experts sur les risques, pas sur la faisabilité de ce qui n''existe pas. Ils sont excellents sur le premier point et structurellement conservateurs sur le second.'),
  ('q-0352', 'Une équipe n''est pas un groupe de personnes qui travaillent ensemble. C''est un groupe de personnes qui se font confiance.', 'Simon Sinek', 'leadership', null, null, null, 'Sinek distingue la coprésence de la coopération. Des gens peuvent travailler côte à côte pendant des années sans former une équipe : ce qui fait la différence, c''est la possibilité de se montrer vulnérable sans en payer le prix.', 'Demande-toi si quelqu''un de ton équipe peut dire « je ne sais pas » ou « j''ai fait une erreur » sans conséquence. Si non, tu as un groupe, pas une équipe.'),
  ('q-0353', 'Un chef possède un titre, un leader a les autres avec lui.', 'Simon Sinek', 'leadership', null, null, null, 'Sinek oppose l''autorité conférée à l''autorité consentie. Le titre s''obtient par décision d''un tiers ; le fait d''être suivi s''obtient auprès de ceux qui suivent, et peut être retiré à tout moment.', 'Observe ce qui se passe quand tu n''imposes rien. Ceux qui continuent d''avancer dans ta direction sont la mesure réelle de ton autorité.'),
  ('q-0354', 'Bâtir la confiance ne réclame rien de plus que de dire la vérité.', 'Simon Sinek', 'leadership', null, null, null, 'Sinek ramène la confiance à un mécanisme simple : elle se construit par cohérence entre ce qu''on dit et ce qui se vérifie. Aucune technique de communication ne remplace ce test, qui se répète à chaque échange.', 'Quand tu ne peux pas tout dire, dis que tu ne peux pas tout dire. C''est le mensonge par omission, découvert plus tard, qui détruit — pas la réserve annoncée.'),
  ('q-0356', 'Les managers travaillent avec les processus, les leaders travaillent avec les gens.', 'John C. Maxwell', 'leadership', null, null, null, 'Maxwell distingue deux objets de travail : les processus, qui s''optimisent, et les personnes, qui se développent. Appliquer une logique de processus aux personnes produit de la conformité, pas de l''engagement.', 'Regarde tes derniers échanges avec ton équipe : portaient-ils sur des tâches ou sur des personnes ? Le déséquilibre indique de quel côté tu penches naturellement.'),
  ('q-0357', 'Pour réaliser une grande vision, vous devez avoir une grande équipe.', 'John C. Maxwell', 'leadership', null, null, null, 'Maxwell relie l''ambition d''une vision à la qualité de l''équipe. Une vision qui dépasse les capacités du groupe ne se réalise pas — elle se transforme en frustration collective.', 'Compare ton ambition à trois ans avec ton équipe actuelle. Si l''écart est grand, la priorité est le recrutement ou la formation, pas la stratégie.'),
  ('q-0358', 'La confiance est le fondement de tout bon leadership.', 'John C. Maxwell', 'leadership', null, null, null, 'Maxwell place la confiance en position de fondation : elle ne s''ajoute pas aux autres qualités, elle les rend utilisables. Sans elle, la compétence est suspectée et la vision n''est pas suivie.', 'La confiance se construit par la prévisibilité. Tiens systématiquement les petits engagements — horaires, réponses, délais : c''est là qu''elle se gagne ou se perd.'),
  ('q-0359', 'Investissez dans une entreprise que n''importe quel imbécile peut diriger, parce qu''un jour un imbécile le fera.', 'Charlie Munger', 'finance', null, null, null, 'Munger juge la solidité structurelle plutôt que la qualité du dirigeant actuel. Sur un horizon long, la direction changera forcément, et souvent pas en mieux : mieux vaut donc une activité qui résiste à une mauvaise gestion.', 'Quand tu évalues un engagement durable, demande-toi ce qu''il devient si la personne compétente en place s''en va. Si tout repose sur elle, tu paries sur elle, pas sur l''activité.'),
  ('q-0360', 'Si investir était si simple, tout le monde serait riche.', 'Charlie Munger', 'finance', null, null, null, 'Munger prévient contre les méthodes qui paraissent évidentes : si une approche fonctionnait aussi simplement qu''annoncé, sa diffusion l''aurait déjà annulée. La difficulté n''est pas un défaut du système, c''est ce qui laisse un rendement possible.', 'Devant une méthode présentée comme simple et sûre, cherche pourquoi tout le monde ne l''applique pas. La réponse t''apprendra soit un risque caché, soit que ce n''est pas vrai.'),
  ('q-0361', 'Le gros argent n''est pas dans l''achat ou la vente, mais dans l''attente.', 'Charlie Munger', 'finance', null, null, null, 'Munger désigne l''inaction comme une compétence active. L''essentiel du résultat vient de la durée de détention, pas de la finesse du moment d''entrée — et tenir sans agir est psychologiquement plus difficile que d''intervenir.', 'Fixe à l''avance les conditions qui te feraient changer de position, puis ne touche à rien tant qu''elles ne sont pas réunies. Sans cette règle écrite, l''ennui finit par passer pour de l''analyse.'),
  ('q-0362', 'Vous n''avez pas besoin d''être brillant, juste un peu plus sage que les autres, en moyenne, pendant longtemps.', 'Charlie Munger', 'finance', null, null, null, 'Munger décrit un avantage cumulatif plutôt qu''un talent. Un petit écart de jugement, répété sur des décennies, produit un résultat que l''intelligence ponctuelle n''atteint pas. La régularité fait le travail que le génie ne fait pas.', 'Choisis une décision récurrente de ton activité et améliore-la de peu, durablement. L''effet vient de la répétition, pas de l''ampleur de la correction.'),
  ('q-0363', 'Les riches acquièrent des actifs. Les pauvres et la classe moyenne acquièrent des passifs en pensant que ce sont des actifs.', 'Robert Kiyosaki', 'finance', null, null, null, 'Kiyosaki pointe une confusion coûteuse : beaucoup de possessions qu''on croit être des actifs coûtent en réalité de l''argent chaque mois. Le critère n''est pas la valeur affichée mais le sens du flux.', 'Passe tes possessions au test : est-ce que ça met de l''argent dans ta poche, ou est-ce que ça en sort ? La réponse suffit à classer, indépendamment du prix d''achat.'),
  ('q-0364', 'Ce qui compte, ce n''est pas combien d''argent vous faites, mais combien vous parvenez à en conserver.', 'Robert Kiyosaki', 'finance', null, null, null, 'Kiyosaki déplace l''attention du revenu vers ce qu''il en reste. Un revenu élevé intégralement dépensé ne construit rien : c''est l''écart entre ce qui entre et ce qui sort qui produit un patrimoine.', 'Calcule ton taux d''épargne réel sur les douze derniers mois. C''est un indicateur bien plus utile que ton revenu, et souvent bien plus surprenant.'),
  ('q-0365', 'Vous devez voir l''échec comme le début et le milieu, mais ne jamais le considérer comme une fin.', 'Jessica Herrin', 'mindset', null, null, null, 'Herrin situe l''échec dans le déroulement plutôt qu''à la fin : c''est un point de passage, parfois au départ, souvent au milieu. Le considérer comme terminal est une décision, pas un fait.', 'Quand un échec survient, demande-toi à quelle étape du parcours tu te trouves. La réponse détermine s''il faut corriger ou arrêter.'),
  ('q-0366', 'Peu importe combien de fois vous avez échoué. Vous devez juste avoir raison une fois.', 'Mark Cuban', 'mindset', null, null, null, 'Cuban décrit une asymétrie de gains : les échecs coûtent un montant limité, une seule réussite peut rapporter sans plafond. Le calcul justifie de multiplier les tentatives raisonnables.', 'Dimensionne tes paris pour qu''aucun échec ne t''empêche de continuer. C''est cette capacité à rester en jeu qui rend la réussite possible.'),
  ('q-0367', 'La croissance et le confort ne coexistent pas.', 'Virginia Rometty', 'mindset', null, null, null, 'Rometty pose une incompatibilité : progresser suppose de faire ce qu''on ne maîtrise pas encore, donc d''accepter l''inconfort. Le confort est le signe qu''on est resté dans le connu.', 'Si ton travail ne te met plus jamais mal à l''aise, cherche délibérément une mission qui te dépasse un peu. C''est le signal que la progression s''est arrêtée.'),
  ('q-0368', 'Le succès arrive généralement à ceux qui sont trop occupés pour le chercher.', 'Henry David Thoreau', 'mindset', null, null, null, 'Thoreau observe que le succès arrive à ceux qui sont absorbés par leur travail plutôt qu''à ceux qui le poursuivent. Chercher la reconnaissance détourne de ce qui la produirait.', 'Concentre-toi sur la qualité de ce que tu fais plutôt que sur sa réception. L''attention portée au résultat dégrade souvent le travail lui-même.'),
  ('q-0369', 'Je n''ai jamais rêvé de succès. J''ai travaillé pour cela.', 'Estée Lauder', 'mindset', null, null, null, 'Lauder oppose le rêve au travail : elle n''a pas attendu que le succès arrive, elle l''a construit. La formule écarte l''idée d''une réussite obtenue par la seule aspiration.', 'Traduis ton objectif en actions hebdomadaires. Tant qu''il reste une aspiration, il ne consomme rien et ne produit rien.'),
  ('q-0371', 'Il y a cette joie qui vient de s''asseoir pour résoudre un problème, et de se lever quand c''est fait et que c''est bon.', 'Drew Houston', 'mindset', null, null, null, 'Houston décrit une satisfaction propre au travail bien fait, indépendante de la reconnaissance. C''est un moteur durable, contrairement aux récompenses extérieures qui s''épuisent.', 'Repère les tâches qui te procurent cette satisfaction et augmente leur part. C''est ce qui te fera tenir quand les résultats tarderont.'),
  ('q-0372', 'Ne soyez jamais limité par l''imagination limitée des autres.', 'Mae Jemison', 'mindset', null, null, null, 'Jemison met en garde contre une limite empruntée : renoncer parce que d''autres ne voient pas la possibilité revient à adopter leur plafond comme le sien.', 'Quand on te dit que ce n''est pas possible, demande si la personne l''a tenté. Un avis sans expérience décrit une croyance, pas une contrainte.'),
  ('q-0373', 'J''ai toujours fait quelque chose que je n''étais pas tout à fait prête à faire. Je pense que c''est comme ça qu''on grandit.', 'Marissa Mayer', 'mindset', null, null, null, 'Mayer décrit une méthode de progression : accepter des missions pour lesquelles on ne se sent pas tout à fait prêt. Attendre de l''être garantit de ne jamais changer de niveau.', 'Accepte la prochaine responsabilité qui te paraît un peu trop grande. Le sentiment d''être prêt arrive après, jamais avant.'),
  ('q-0374', 'Il n''y a pas de meilleure mesure de vos valeurs que la façon dont vous dépensez votre temps.', 'Scott Belsky', 'mindset', null, null, null, 'Belsky propose un test objectif : les valeurs déclarées coûtent peu, l''emploi du temps révèle les priorités réelles. L''agenda ne ment pas, contrairement au discours.', 'Relève où sont passées tes heures cette semaine et compare avec ce que tu dis prioritaire. L''écart désigne exactement ce qu''il faut corriger.'),
  ('q-0375', 'Une idée ne peut devenir une réalité qu''une fois qu''elle est décomposée en éléments organisés et actionnables.', 'Scott Belsky', 'leadership', null, null, null, 'Belsky décrit le passage de l''idée au réel : tant qu''elle n''est pas découpée en actions identifiables et attribuées, une idée reste une intention. La décomposition est le travail qui la rend possible.', 'Prends ton idée et écris les cinq premières actions concrètes, avec un responsable pour chacune. Ce qui ne se découpe pas ne se réalise pas.'),
  ('q-0378', 'Être sans peur, ce n''est pas l''absence de peur, c''est la maîtrise de la peur. C''est se relever une fois de plus qu''on ne tombe.', 'Arianna Huffington', 'mindset', null, null, null, 'Huffington définit l''intrépidité comme une maîtrise, pas une absence : la peur reste, elle cesse simplement de commander. La seconde partie ajoute la persistance — se relever une fois de plus qu''on ne tombe suffit.', 'Compte tes relèvements plutôt que tes chutes. Tant que le premier chiffre dépasse le second d''une unité, tu es debout.'),
  ('q-0379', 'La persévérance n''est pas une longue course ; c''est plusieurs courses courtes les unes après les autres.', 'Walter Elliot', 'mindset', null, null, null, 'Elliot corrige une image trompeuse : la persévérance n''est pas un effort continu et héroïque, mais une succession de reprises courtes. Cette lecture la rend accessible.', 'Ne vise pas la constance parfaite, vise la reprise rapide après chaque interruption. C''est la durée du décrochage qui compte, pas son existence.'),
  ('q-0380', 'Le succès n''est pas une question de grandeur. C''est une question de constance.', 'Dwayne Johnson', 'mindset', null, null, null, 'Johnson déplace le critère du spectaculaire vers le régulier. Ce n''est pas l''intensité d''un effort ponctuel qui produit un résultat, mais la répétition sur la durée.', 'Choisis un rythme que tu peux tenir six mois plutôt qu''un programme intense d''un mois. La constance bat l''intensité sur toute distance longue.'),
  ('q-0382', 'Seuls ceux qui prennent le risque d''aller trop loin peuvent découvrir jusqu''où ils peuvent aller.', 'T.S. Eliot', 'mindset', null, null, null, 'Eliot lie la découverte de ses limites au dépassement : tant qu''on reste dans la zone sûre, on ne sait pas de quoi on est capable. Le risque est le seul instrument de mesure.', 'Fixe-toi un objectif dont tu ignores s''il est atteignable. Le résultat t''apprendra quelque chose que la prudence ne t''aurait jamais dit.'),
  ('q-0383', 'La plus grande erreur que vous puissiez faire dans la vie, c''est d''avoir peur de faire des erreurs.', 'John Wooden', 'mindset', null, null, null, 'Wooden désigne la peur de l''erreur comme l''erreur principale : elle empêche d''agir, d''apprendre et de progresser. Son coût cumulé dépasse celui des erreurs évitées.', 'Autorise-toi explicitement un quota d''erreurs sur un projet. Cela change la façon dont tu décides et accélère l''apprentissage.'),
  ('q-0384', 'L''échec est la clé du succès ; chaque erreur nous enseigne quelque chose.', 'Morihei Ueshiba', 'mindset', null, null, null, 'Ueshiba fait de l''erreur un mécanisme d''apprentissage systématique : chaque échec contient une information sur ce qui ne fonctionne pas, donc une avancée vers ce qui fonctionne.', 'Après chaque erreur, note l''enseignement en une phrase. Sans cette formalisation, l''information se perd et l''erreur se répète.'),
  ('q-0385', 'Ne jugez pas chaque jour à la récolte que vous faites, mais aux graines que vous plantez.', 'Robert Louis Stevenson', 'mindset', null, null, null, 'Stevenson déplace le critère d''évaluation d''une journée : la récolte dépend de semis anciens, tandis que les graines plantées aujourd''hui déterminent l''avenir. Juger sur le résultat immédiat décourage à tort.', 'En fin de journée, note ce que tu as semé plutôt que ce que tu as récolté. C''est la seule mesure qui reflète le travail réellement fourni.'),
  ('q-0386', 'La question n''est pas « qui va me donner l''autorisation de faire ça ? » mais plutôt « qui pourra m''arrêter ? »', 'Ayn Rand', 'mindset', null, null, null, 'Rand oppose deux postures : attendre une autorisation, ou vérifier ce qui empêche réellement. La première suppose un pouvoir extérieur qui, souvent, n''existe pas.', 'Sur un projet en attente, identifie qui doit réellement approuver. La plupart des blocages sont des permissions qu''on s''impose seul.'),
  ('q-0389', 'La réussite ne se mesure pas à l''argent que vous gagnez mais à votre capacité à changer la vie des gens.', 'Michelle Obama', 'mindset', null, null, null, 'Obama redéfinit la réussite par l''effet sur les autres plutôt que par l''accumulation. C''est un déplacement du critère, qui change ce qu''on cherche à optimiser.', 'Ajoute à tes indicateurs une mesure de l''effet sur les gens — clients, équipe, proches. Ce que tu mesures oriente ce que tu produis.'),
  ('q-0390', 'Créez votre propre définition du succès, agissez selon vos propres règles, et construisez la vie dont vous êtes fière.', 'Anne Sweeney', 'mindset', null, null, null, 'Sweeney propose de définir soi-même ses critères plutôt que d''hériter de ceux d''autrui. Poursuivre un succès défini par d''autres conduit à l''obtenir sans en tirer satisfaction.', 'Écris ta propre définition de la réussite, en trois lignes. Relis-la quand tu te compares : la plupart des comparaisons portent sur des critères qui ne sont pas les tiens.'),
  ('q-0392', 'La meilleure façon de prédire l''avenir est de l''inventer.', 'Alan Kay', 'mindset', null, null, null, 'Kay écarte la prédiction au profit de la construction. Prévoir suppose de subir ; inventer suppose d''agir. C''est un renversement du rapport au futur.', 'Cesse d''attendre de savoir où va ton marché. Décide de ce que tu veux y créer et engage la première étape.'),
  ('q-0393', 'Ne te demande pas ce dont le monde a besoin. Ce dont il a besoin, ce sont des gens qui ont trouvé ce qui les fait vivre pleinement.', 'Howard Thurman', 'mindset', null, null, null, 'Thurman déplace la question : chercher ce dont le monde a besoin conduit à des choix abstraits ; chercher ce qui vous anime produit un engagement soutenable, dont l''utilité découle.', 'Repère les tâches après lesquelles tu sors avec de l''énergie plutôt qu''épuisé. Augmenter leur part sert autant les autres que toi.'),
  ('q-0394', 'Si vous ne construisez pas votre rêve, quelqu''un d''autre vous embauchera pour construire les siens.', 'Tony Gaskins', 'mindset', null, null, null, 'Gaskins pose une alternative simple : construire son projet, ou être employé à construire celui d''un autre. Ce n''est pas un jugement sur le salariat, mais un rappel qu''il y a un choix.', 'Consacre un créneau fixe chaque semaine à ton propre projet, même modeste. Sans réservation explicite, le temps ira au projet de quelqu''un d''autre.'),
  ('q-0395', 'Il n''est jamais trop tard pour être ce que vous auriez pu être.', 'George Eliot', 'mindset', null, null, null, 'Eliot conteste l''idée d''échéance sur les projets de vie. Le regret repose souvent sur une croyance de calendrier, pas sur une impossibilité réelle.', 'Si tu renonces à quelque chose parce qu''il est trop tard, vérifie ce qui l''empêche concrètement aujourd''hui. La réponse surprend souvent.'),
  ('q-0398', 'Si l''on doit se souvenir de tous ses échecs, on ne s''en sort pas.', 'Xavier Niel', 'mindset', null, null, null, 'Niel écarte la rumination : rejouer ses échecs consomme l''énergie nécessaire à la suite. Ce n''est pas un appel à ne rien apprendre, mais à ne pas s''installer dans l''analyse.', 'Accorde-toi un temps limité pour tirer les leçons d''un échec, puis passe à autre chose. Au-delà, tu ne apprends plus rien de nouveau.'),
  ('q-0399', 'Il faut avoir le courage de prendre des risques et de ne pas avoir peur de l''échec.', 'Marc Simoncini', 'mindset', null, null, null, 'Simoncini associe deux conditions : accepter le risque, et ne pas craindre l''échec qui en découle. La première sans la seconde produit des prises de risque qu''on abandonne au premier revers.', 'Avant de te lancer, écris ce que tu feras si ça échoue. Avoir un plan de repli rend paradoxalement plus audacieux.'),
  ('q-0400', 'Point n''est besoin d''espérer pour entreprendre, ni de réussir pour persévérer.', 'Guillaume Ier d''Orange-Nassau', 'mindset', null, null, null, 'La formule attribuée à Guillaume d''Orange affirme qu''on peut agir sans garantie de succès. L''engagement ne dépend pas de la probabilité, mais de la valeur de ce qu''on poursuit.', 'Quand un projet te tient à cœur sans être probable, engage-le quand même à une échelle que tu peux assumer. La probabilité n''est pas le seul critère.'),
  ('q-0401', 'Si les opportunités ne frappent pas à la porte, construisez une nouvelle porte.', 'Milton Berle', 'mindset', null, null, null, 'Berle transforme l''attente en action : si l''occasion ne se présente pas, il reste à la créer. C''est un refus de la posture passive face au hasard.', 'Plutôt que d''attendre une occasion, provoque-la : contacte, propose, publie. La plupart des opportunités sont fabriquées, pas rencontrées.'),
  ('q-0402', 'Si tout semble sous contrôle, c''est que vous n''allez pas assez vite.', 'Mario Andretti', 'mindset', null, null, null, 'Andretti, pilote, décrit une limite qu''on n''atteint que dans l''inconfort : si tout paraît maîtrisé, c''est qu''on est en deçà de sa capacité réelle.', 'Si ton activité te semble entièrement sous contrôle depuis des mois, c''est probablement le moment d''augmenter l''ambition.'),
  ('q-0403', 'Il n''y a pas meilleur catalyseur du succès que la curiosité.', 'Michael Dell', 'mindset', null, null, null, 'Dell place la curiosité en amont de la compétence : c''est elle qui pousse à comprendre un marché, un client ou une technologie avant que ce soit nécessaire. Elle produit l''avance.', 'Consacre une heure par semaine à explorer un sujet adjacent à ton métier, sans objectif immédiat. C''est ce temps sans rendement apparent qui crée les connexions.'),
  ('q-0404', 'Il est possible dans certains cas d''être occupé, très occupé, et parfaitement inefficace.', 'Stephen R. Covey', 'mindset', null, null, null, 'Covey distingue l''activité de l''efficacité. Être occupé rassure et se voit ; produire ce qui compte se voit moins et demande de renoncer à une partie du reste.', 'En fin de semaine, note ce qui a réellement fait avancer tes objectifs. L''écart avec le temps passé est presque toujours instructif.'),
  ('q-0405', 'La mort de l''entrepreneur porte un nom : isolement.', 'Ernesto Sirolli', 'mindset', null, null, null, 'Sirolli désigne l''isolement comme cause principale d''échec entrepreneurial — devant le manque de financement ou de compétences. Seul, on ne voit pas ses erreurs et on ne tient pas la durée.', 'Constitue-toi un cercle de deux ou trois personnes à qui tu parles régulièrement de ton activité. C''est une protection, pas un luxe.'),
  ('q-0406', 'Certains rêvent d''incroyables réalisations, pendant que d''autres restent éveillés et les font.', 'Nolan Bushnell', 'mindset', null, null, null, 'Bushnell oppose le rêve à l''exécution : les deux commencent pareil, mais seuls certains transforment l''idée en travail réel. La différence n''est pas dans l''imagination.', 'Prends l''idée que tu rumines depuis longtemps et fixe-lui une première action datée. Le passage du rêve au projet tient à cette seule opération.'),
  ('q-0407', 'L''inspiration est périssable. Agissez immédiatement.', 'Naval Ravikant', 'mindset', null, null, null, 'Naval décrit l''inspiration comme une ressource qui se dégrade : l''envie de faire une chose est maximale au moment où elle apparaît et décroît ensuite. Attendre le bon moment revient souvent à attendre qu''elle disparaisse.', 'Quand une idée te motive, fais la première action dans l''heure — même symbolique. L''objectif est d''accrocher l''élan avant qu''il retombe.'),
  ('q-0408', 'L''échec n''est rien d''autre que la façon dont la vie vous indique que vous n''êtes pas sur la bonne voie.', 'Sara Blakely', 'mindset', null, null, null, 'Blakely traite l''échec comme un signal d''orientation plutôt que comme un verdict sur la personne. L''information porte sur la direction prise, ce qui la rend exploitable au lieu d''être décourageante.', 'Après un échec, demande-toi ce qu''il indique sur la direction plutôt que sur toi. La première lecture ouvre une correction, la seconde ne mène nulle part.'),
  ('q-0409', 'Ne soyez pas intimidé par ce que vous ne savez pas. Cela peut être votre plus grande force.', 'Sara Blakely', 'mindset', null, null, null, 'Blakely présente l''ignorance comme un atout possible : ne pas connaître les usages d''un secteur permet de poser des questions que les initiés ne posent plus et d''essayer ce qu''ils ont écarté par habitude.', 'En arrivant sur un sujet nouveau, note tes questions naïves avant de te former. Elles disparaîtront ensuite, et certaines valaient qu''on y réponde.'),
  ('q-0410', 'L''entrepreneur est cette personne qui saute d''une falaise, et construit un avion au cours de sa chute.', 'Reid Hoffman', 'mindset', null, null, null, 'Hoffman décrit la simultanéité propre à l''entrepreneuriat : on s''engage avant que les moyens existent, et on les construit pendant la chute. C''est inconfortable et c''est la description exacte du métier.', 'Accepte de démarrer avec un dispositif incomplet, mais mesure ta hauteur de chute : combien de temps te reste-t-il avant l''impact ? C''est le seul chiffre qui compte.'),
  ('q-0411', 'La volonté, c''est le clou auquel on accroche son projet pour l''avoir toujours devant les yeux.', 'Victor Hugo', 'mindset', null, null, null, 'L''image du clou décrit la fonction de la volonté : maintenir l''objectif visible pour qu''il ne disparaisse pas sous le quotidien. Ce n''est pas la force qui manque, c''est l''attention.', 'Écris ton objectif principal et place-le là où tu le verras chaque jour. Ce qui sort du champ de vision sort de la liste des priorités.'),
  ('q-0412', 'L''histoire, c''est la rencontre d''une volonté et d''un événement.', 'Charles de Gaulle', 'mindset', null, null, null, 'De Gaulle décrit l''histoire comme un produit de deux facteurs : les circonstances seules ne font rien, la volonté seule non plus. C''est leur rencontre qui produit un basculement — ce qui suppose d''être prêt quand l''occasion se présente.', 'Prépare-toi pour l''occasion que tu ne peux pas provoquer. Ceux qui saisissent un tournant sont ceux qui avaient déjà fait le travail avant qu''il arrive.'),
  ('q-0413', 'Délibérer est le fait de plusieurs. Agir est le fait d''un seul.', 'Charles de Gaulle', 'leadership', null, null, null, 'De Gaulle sépare deux temps qu''on mélange souvent : la délibération gagne à être collective, l''exécution suppose un responsable unique. Une décision portée par tout le monde n''est portée par personne.', 'Après une réunion, désigne nommément qui décide et qui exécute. Sans ce nom, le sujet reviendra à l''ordre du jour de la réunion suivante.'),
  ('q-0414', 'Si tu veux construire un bateau, ne rassemble pas des hommes pour aller chercher du bois, mais donne-leur envie de la mer immense.', 'Antoine de Saint-Exupéry', 'mindset', null, null, null, 'Saint-Exupéry oppose deux façons de mobiliser : organiser des tâches, ou créer un désir. La première produit de l''obéissance qui s''arrête avec la consigne, la seconde produit une initiative qui continue sans surveillance.', 'Avant de distribuer les tâches d''un projet, prends dix minutes pour expliquer à quoi il servira. Ce temps se rattrape largement en autonomie ensuite.'),
  ('q-0415', 'Il faut d''abord savoir ce que l''on veut, il faut ensuite avoir le courage de le dire, il faut ensuite l''énergie de le faire.', 'Georges Clemenceau', 'mindset', null, null, null, 'Clemenceau décompose l''action en trois exigences successives : la clarté, le courage de l''exprimer, l''énergie de l''exécuter. Chacune peut faire échouer l''ensemble.', 'Situe où tu bloques parmi les trois : tu ne sais pas ce que tu veux, tu n''oses pas le dire, ou tu ne l''exécutes pas. Le remède est différent à chaque fois.'),
  ('q-0416', 'Évoluer est la plus grande réussite d''une vie, et sa plus belle récompense.', 'Ray Dalio', 'mindset', null, null, null, 'Dalio place l''évolution personnelle au-dessus du résultat obtenu. Ce qu''on devient en cours de route est à la fois le vrai gain et ce qui rend possible la suite — les résultats, eux, se périment.', 'À la fin de chaque trimestre, note ce que tu sais faire maintenant et que tu ne savais pas faire avant. Si la liste est vide, tu as produit sans progresser.'),
  ('q-0417', 'L''échec signifie un dépouillement de l''inessentiel.', 'J.K. Rowling', 'mindset', null, null, null, 'Rowling décrit l''échec comme un filtre : il retire ce qui n''était pas essentiel et laisse ce qui compte vraiment. La perte est réelle, mais elle clarifie.', 'Après un échec majeur, liste ce qui te reste et qui a de la valeur. Cette liste plus courte est souvent plus juste que celle d''avant.'),
  ('q-0419', 'Le succès recèle le germe de sa propre destruction.', 'Andrew Grove', 'mindset', null, null, null, 'Grove décrit un mécanisme d''auto-destruction : le succès installe des certitudes, réduit la vigilance et rend l''organisation attachée à ce qui a marché. C''est cette rigidité qui la rend vulnérable.', 'Après une réussite, demande explicitement ce qui pourrait la rendre obsolète. Personne ne pose cette question spontanément quand tout va bien.'),
  ('q-0420', 'Seuls ceux qui dorment ne font pas d''erreurs.', 'Ingvar Kamprad', 'mindset', null, null, null, 'Kamprad relie l''erreur à l''activité : seule l''inaction garantit un dossier vierge. Reprocher les erreurs sans distinguer leur origine revient donc à décourager l''initiative.', 'Quand tu analyses une erreur, sépare celle qui vient d''une prise d''initiative de celle qui vient d''une négligence. Traiter les deux pareil élimine la première.'),
  ('q-0425', 'Le succès est fait de 99 % d''échecs.', 'Soichiro Honda', 'mindset', null, null, null, 'Honda revendique une proportion écrasante d''échecs dans son parcours. La formule replace la réussite comme le résidu visible d''un très grand nombre de tentatives ratées.', 'Quand tu compares ton parcours à celui d''un dirigeant admiré, souviens-toi que tu ne vois que le 1 % restant. Les 99 % ne sont racontés nulle part.'),
  ('q-0426', 'Nous avons plus de force que de volonté.', 'La Rochefoucauld', 'mindset', null, null, null, 'La Rochefoucauld distingue la capacité de l''intention : nous pourrions faire beaucoup plus que nous ne voulons réellement faire. L''obstacle est rarement la force, presque toujours la détermination.', 'Quand tu attribues un renoncement à un manque de moyens, vérifie honnêtement s''il s''agit de moyens ou d''envie. Le remède diffère complètement.'),
  ('q-0427', 'Les occasions se présentent habituellement sous la forme d''un dur labeur ; c''est pourquoi la plupart des gens ne les reconnaissent pas.', 'Ann Landers', 'mindset', null, null, null, 'Landers explique pourquoi les occasions passent inaperçues : elles ressemblent à du travail difficile, pas à une bonne nouvelle. Ceux qui cherchent la facilité les écartent.', 'Quand une proposition te paraît trop exigeante, examine ce qu''elle t''apporterait si tu la menais. Beaucoup d''occasions sont refusées pour leur coût apparent.'),
  ('q-0429', 'Il ne dépend pas de toi d''être riche, mais il dépend de toi d''être heureux.', 'Épictète', 'mindset', null, null, null, 'Épictète distingue ce qui dépend de nous de ce qui n''en dépend pas. La richesse relève des circonstances, du marché, de la chance ; le rapport qu''on entretient avec sa situation reste sous contrôle.', 'Fais deux colonnes : ce que tu peux influencer, ce que tu subis. Consacre ton énergie à la première et cesse de la dépenser sur la seconde.'),
  ('q-0431', 'Les rêves ne sont pas ce que vous voyez dans votre sommeil, les rêves sont des choses qui ne vous permettent pas de dormir.', 'A.P.J. Abdul Kalam', 'mindset', null, null, null, 'Abdul Kalam distingue le rêve passif du rêve moteur : celui qui compte n''est pas celui qu''on fait en dormant, c''est celui qui empêche de dormir parce qu''on veut le réaliser.', 'Repère ce à quoi tu penses spontanément quand ton esprit est libre. C''est un meilleur indicateur de ce que tu veux vraiment que n''importe quelle liste d''objectifs.'),
  ('q-0434', 'Le présent n''est pas un passé en puissance, il est le moment du choix et de l''action.', 'Simone de Beauvoir', 'mindset', null, null, null, 'Beauvoir refuse de voir le présent comme une simple transition : c''est le seul moment où le choix et l''action existent. Le passé est fixé, l''avenir n''existe pas encore.', 'Cesse de reporter une décision en attendant un contexte plus favorable. Le seul moment où tu peux décider est celui où tu te trouves.'),
  ('q-0436', 'La vraie grandeur consiste à être maître de soi-même.', 'Daniel Defoe', 'mindset', null, null, null, 'Defoe situe la grandeur dans la maîtrise de soi plutôt que dans la domination d''autrui. C''est la seule forme de pouvoir qui ne dépende d''aucune circonstance extérieure.', 'Repère la réaction qui te dessert le plus — impatience, évitement, colère. Travailler celle-là produira plus d''effet que n''importe quelle stratégie.'),
  ('q-0437', 'Toute facilité apparente, toute réussite, sont les fruits d''une rigueur intime.', 'Gérard Bauer', 'mindset', null, null, null, 'Bauer rappelle que la facilité visible est le produit d''un travail invisible. Ce qui paraît naturel chez quelqu''un résulte presque toujours d''une discipline qu''on n''a pas vue.', 'Quand quelqu''un te paraît doué, cherche ce qu''il a répété pendant des années. Tu y trouveras une méthode reproductible plutôt qu''un don.'),
  ('q-0439', 'Si on veut vivre, il faut prendre des risques.', 'Boris Cyrulnik', 'mindset', null, null, null, 'Cyrulnik, qui travaille sur la résilience, lie le risque à la vie elle-même : se protéger totalement revient à réduire son existence à ce qui ne peut rien apporter.', 'Vérifie que tes précautions protègent quelque chose de réel. Certaines se contentent d''écarter tout ce qui pourrait arriver, y compris de bon.'),
  ('q-0440', 'Je patine là où le palet va aller, pas là où il était.', 'Wayne Gretzky', 'mindset', null, null, null, 'Gretzky décrit l''anticipation : se positionner là où l''action va se produire, pas là où elle vient de se produire. Suivre le mouvement garantit d''arriver en retard.', 'Sur ton marché, regarde où va la demande plutôt que d''où elle vient. Se positionner sur le passé récent est l''erreur la plus fréquente.'),
  ('q-0442', 'Le parcours était semé d''embûches, mais c''était mal me connaître que d''imaginer que j''abandonnerais la partie dès les premiers obstacles.', 'Simone Veil', 'mindset', null, null, null, 'Veil décrit une détermination qui ne se laisse pas entamer par les obstacles initiaux. Ceux qui la sous-estimaient jugeaient sur les difficultés, pas sur la personne.', 'Quand un projet rencontre une résistance dès le départ, distingue l''obstacle du signal. Beaucoup de résistances initiales ne disent rien de la viabilité.'),
  ('q-0443', 'Le progrès est impossible sans changement et ceux qui ne peuvent changer leur esprit ne peuvent absolument rien changer.', 'George Bernard Shaw', 'mindset', null, null, null, 'Shaw relie la capacité de changer les choses à celle de changer d''avis. Celui qui ne révise jamais son jugement ne peut rien transformer, puisqu''il reproduit ce qu''il pensait déjà.', 'Identifie une opinion professionnelle que tu n''as pas révisée depuis cinq ans. Vérifie qu''elle tient encore avec les informations d''aujourd''hui.'),
  ('q-0444', 'Trop souvent, les gens travaillent dur sur la mauvaise chose. Travailler sur la bonne chose est probablement plus important que de travailler dur.', 'Caterina Fake', 'mindset', null, null, null, 'Fake hiérarchise deux variables : la direction et l''intensité. Travailler beaucoup sur le mauvais sujet produit de la fatigue sans résultat, alors que le bon sujet rend l''effort rentable.', 'Avant d''augmenter tes heures, vérifie que tu travailles sur ce qui compte. Un mauvais choix de sujet ne se rattrape pas par l''endurance.'),
  ('q-0451', 'Les entrepreneurs ne demandent pas la permission. Ils agissent pour leur mission.', 'Ryan Lilly', 'mindset', null, null, null, 'Lilly décrit une posture entrepreneuriale : agir selon sa mission plutôt que d''attendre une validation. La permission qu''on attend n''a souvent aucun émetteur identifié.', 'Sur un projet bloqué, demande-toi qui doit réellement autoriser. Si personne n''est désigné, l''autorisation que tu attends n''existe pas.'),
  ('q-0455', 'Celui qui n''a jamais commis d''erreur n''a jamais tenté quelque chose de nouveau.', 'Albert Einstein', 'mindset', null, null, null, 'Einstein relie l''erreur à la nouveauté : un parcours sans faute signale qu''on est resté dans le connu. L''erreur devient alors un indicateur d''exploration, pas d''incompétence.', 'Si tu n''as commis aucune erreur ce trimestre, demande-toi ce que tu as tenté de nouveau. L''absence d''erreur est rarement une bonne nouvelle.'),
  ('q-0456', 'L''espérance est un risque à courir.', 'Georges Bernanos', 'mindset', null, null, null, 'Bernanos présente l''espérance comme un engagement risqué, pas comme un confort : espérer, c''est accepter d''être déçu. C''est ce qui la distingue de l''optimisme naïf.', 'Quand tu t''engages sur un projet incertain, accepte explicitement la possibilité de l''échec. L''espérance lucide tient mieux que la confiance aveugle.'),
  ('q-0457', 'Le talent, c''est d''avoir envie de faire quelque chose.', 'Jacques Brel', 'mindset', null, null, null, 'Brel ramène le talent au désir plutôt qu''au don. C''est une définition volontariste : ce qui distingue n''est pas une aptitude reçue mais une envie assez forte pour faire travailler.', 'Ne cherche pas ce pour quoi tu es doué, cherche ce que tu as envie de faire assez longtemps. L''aptitude vient de la répétition.'),
  ('q-0460', 'Agir librement, c''est prendre possession de soi.', 'Henri Bergson', 'mindset', null, null, null, 'Bergson lie liberté et appropriation de soi : agir librement, c''est agir depuis ce qu''on est réellement plutôt que par réaction ou conformité.', 'Avant une décision importante, demande-toi si elle vient de toi ou d''une attente extérieure. La distinction est plus difficile qu''elle n''en a l''air.'),
  ('q-0461', 'Oser, c''est d''abord oser l''échec.', 'Charles Pépin', 'mindset', null, null, null, 'Pépin identifie ce que l''audace suppose réellement : accepter par avance la possibilité de l''échec. Sans cette acceptation, ce n''est pas de l''audace mais un pari qu''on croit gagné.', 'Avant de te lancer, énonce explicitement ce que tu perds si ça échoue. L''accepter à l''avance est ce qui rend l''action possible.'),
  ('q-0462', 'La seule chose promise d''avance à l''échec, c''est celle que l''on ne tente pas.', 'Paul-Émile Victor', 'mindset', null, null, null, 'Victor formule une certitude unique : la tentative non faite est la seule dont l''issue est connue. Toutes les autres conservent une part d''incertitude favorable.', 'Quand tu hésites, souviens-toi que le renoncement est la seule option à résultat garanti — et ce résultat est nul.'),
  ('q-0464', 'Oser, c''est perdre pied momentanément. Ne pas oser, c''est se perdre soi-même.', 'Søren Kierkegaard', 'mindset', null, null, null, 'Kierkegaard compare deux pertes : celle, temporaire, de l''équilibre quand on ose, et celle, durable, de soi-même quand on renonce systématiquement. La seconde est plus grave.', 'Face à un choix qui t''effraie, compare la durée des deux inconforts. Celui de l''audace est court, celui du renoncement s''installe.'),
  ('q-0465', 'On ne réussit ordinairement dans les grandes entreprises qu''en courant de grands dangers.', 'Hérodote', 'mindset', null, null, null, 'Hérodote relie l''ampleur des entreprises à celle des risques consentis. Ce n''est pas un éloge de l''imprudence mais un constat : les grandes réussites supposent une exposition proportionnée.', 'Calibre ton risque sur ton ambition. Un objectif ambitieux poursuivi avec une prise de risque minimale ne se réalise pas.'),
  ('q-0466', 'Il faut un peu risquer dans la vie, quand on veut avoir quelque chose.', 'Marcel Pagnol', 'mindset', null, null, null, 'Pagnol formule une condition simple : obtenir suppose d''engager quelque chose. Refuser tout risque garantit surtout de conserver exactement ce qu''on a déjà.', 'Sur un objectif qui compte, identifie ce que tu dois accepter de mettre en jeu — du temps, de l''argent, une réputation. Sans mise, pas de gain.'),
  ('q-0467', 'On hasarde de perdre en voulant trop gagner.', 'Jean de La Fontaine', 'mindset', null, null, null, 'La Fontaine avertit contre l''excès d''ambition dans une négociation ou un pari : vouloir tout obtenir fait souvent perdre ce qui était acquis.', 'Dans une négociation, fixe à l''avance le point où tu acceptes. Sans cette limite, la recherche du mieux fait régulièrement perdre le bon.'),
  ('q-0468', 'Le leadership consiste à rendre les autres meilleurs en sa présence et à faire en sorte que cet impact dure en son absence.', 'Sheryl Sandberg', 'leadership', null, null, null, 'Sandberg propose deux critères, dont le second est plus exigeant : améliorer les gens en sa présence, et faire que cet effet persiste après le départ. Le premier peut venir du charisme, le second suppose d''avoir transmis.', 'Demande-toi ce que ton équipe saura faire sans toi dans un an. Si la réponse est « la même chose qu''aujourd''hui », tu diriges sans former.'),
  ('q-0470', 'Le leadership, c''est l''art de motiver quelqu''un à faire ce que vous voulez qu''il fasse parce qu''il veut le faire.', 'Dwight Eisenhower', 'leadership', null, null, null, 'Eisenhower définit le leadership par l''adhésion volontaire : obtenir l''action souhaitée sans contrainte, parce que la personne y trouve son intérêt ou son sens.', 'Avant de demander quelque chose, cherche ce que la personne y gagne. Si tu ne trouves rien, la demande reposera uniquement sur ton autorité.'),
  ('q-0471', 'Le leadership n''est pas une position, mais une action.', 'Donald McGannon', 'leadership', null, null, null, 'McGannon sépare le leadership de la fonction : il se manifeste dans les actes, pas dans l''organigramme. On peut diriger sans titre et détenir un titre sans diriger.', 'Repère qui, sans autorité formelle, entraîne les autres dans ton organisation. Ce sont tes leaders réels, indépendamment des étiquettes.'),
  ('q-0473', 'Il est difficile d''atteindre des objectifs que vous n''avez jamais fixés.', 'Susan Wojcicki', 'leadership', null, null, null, 'Wojcicki énonce une évidence rarement appliquée : un objectif non formulé ne peut pas être atteint, faute de savoir ce qu''on vise et de pouvoir mesurer l''écart.', 'Écris tes trois objectifs du trimestre avec un critère de réussite. Ce qui n''est pas écrit se dilue dans le quotidien.'),
  ('q-0474', 'Le secret de la réussite est de savoir s''entourer de gens meilleurs que soi.', 'François Pinault', 'leadership', null, null, null, 'Pinault fait de la qualité de l''entourage le facteur déterminant. Recruter meilleur que soi suppose de renoncer à être le plus compétent, ce qui demande une sécurité personnelle.', 'Sur ton prochain recrutement, cherche quelqu''un qui te dépasse sur une compétence clé. La gêne que tu ressentiras est le signe que c''est le bon choix.'),
  ('q-0478', 'Le bien est l''ennemi du mieux.', 'Jim Collins', 'leadership', null, 'De la performance à l''excellence', 2001, 'Collins désigne le confort du satisfaisant comme obstacle principal à l''excellence : ce qui fonctionne correctement n''appelle aucune remise en cause, donc rien ne progresse.', 'Identifie ce qui marche « assez bien » dans ton activité depuis des années. C''est là que se cache ton plus gros potentiel inexploité.'),
  ('q-0482', 'L''innovation n''est pas une fin en soi. Encore faut-il la développer pour l''imposer aux clients.', 'Akio Morita', 'leadership', null, null, null, 'Morita rappelle qu''une innovation technique ne vaut rien sans adoption. Le travail de développement et de diffusion pèse autant que l''invention elle-même.', 'Après avoir conçu quelque chose de nouveau, prévois autant d''énergie pour le faire adopter que pour l''avoir créé. C''est là que la plupart des innovations meurent.'),
  ('q-0483', 'Diriger, c''est se dévouer à une idée, à un rêve, à une vision de ce qui peut advenir.', 'John F. Kennedy', 'leadership', null, null, null, 'Kennedy définit le fait de diriger par l''engagement envers une idée plutôt que par l''exercice du pouvoir. Ce qui rassemble n''est pas la fonction mais ce qu''elle sert — et cela suppose de savoir formuler ce qu''on poursuit.', 'Écris ce que ton équipe construit au-delà des objectifs chiffrés. Sans cette phrase, il ne reste que des tâches, et les tâches ne mobilisent personne durablement.'),
  ('q-0485', 'La confiance rapporte plus que le contrôle.', 'Jean-François Zobrist', 'leadership', null, null, null, 'Zobrist, dirigeant qui a supprimé les contrôles dans son usine, avance que la confiance produit plus de valeur que la surveillance — laquelle coûte cher et signale la défiance.', 'Calcule ce que te coûtent tes procédures de contrôle. Compare avec ce que t''ont réellement coûté les abus qu''elles préviennent.'),
  ('q-0487', 'Gagner de l''argent n''est pas une chose que l''on fait, c''est une compétence que l''on apprend.', 'Naval Ravikant', 'finance', null, null, null, 'Naval traite l''aptitude financière comme une compétence acquise, pas comme un trait de caractère ou une chance. Cela suppose qu''elle s''apprend, se pratique et progresse — et que l''échec initial est normal.', 'Traite ton rapport à l''argent comme un apprentissage : lis, teste petit, analyse tes erreurs. Personne n''attend d''être bon avant de commencer dans les autres domaines.'),
  ('q-0488', 'La confiance ! C''est ça qui est important, plus que les capitaux propres ou les liquidités.', 'Phil Knight', 'finance', null, null, null, 'Knight place la confiance au-dessus des ressources financières. Un partenaire fiable permet de traverser une difficulté ; du capital sans confiance ne survit pas au premier accroc.', 'Avant de choisir un partenaire ou un fournisseur, teste-le sur un petit engagement. La façon dont il tient parole vaut plus que ses références.'),
  ('q-0489', 'Gagner de l''argent n''oblige personne à salir son honneur ou sa conscience.', 'Guy de Rothschild', 'finance', null, null, null, 'Rothschild sépare la réussite financière et le compromis moral : gagner de l''argent n''impose aucune concession, c''est un choix que certains font et présentent comme une nécessité.', 'Quand une opportunité suppose un arrangement avec tes principes, cherche l''alternative. Le fait qu''elle soit moins évidente ne veut pas dire qu''elle n''existe pas.'),
  ('q-0490', 'Après tout, l''argent disparaît, des amis meurent et vous mourez vous-même, mais votre réputation demeure.', 'Thor Bjorgolfsson', 'finance', null, null, null, 'Bjorgolfsson hiérarchise ce qui dure : l''argent se perd, les circonstances changent, mais la réputation survit à tout le reste. C''est le seul actif réellement transmissible.', 'Avant une décision qui améliore un résultat immédiat, vérifie ce qu''elle prélève sur ta réputation. C''est le capital le plus long à reconstituer.'),
  ('q-0491', 'Faire de l''argent un moyen et non une fin.', 'Pierre Rabhi', 'finance', null, null, null, 'Rabhi replace l''argent dans sa fonction d''instrument. En faire une finalité conduit à accumuler sans savoir pourquoi, et à sacrifier ce qu''il devait permettre.', 'Écris ce que tu veux que ton argent te permette. Sans cette réponse, l''accumulation devient un objectif par défaut.'),
  ('q-0493', 'Les riches se concentrent sur les solutions, les pauvres se concentrent sur les problèmes.', 'T. Harv Eker', 'finance', null, null, null, 'Eker oppose deux orientations d''attention. Se concentrer sur les problèmes produit de l''analyse sans issue ; se concentrer sur les solutions produit des options. La différence est comportementale.', 'Devant une difficulté, impose-toi de proposer trois options avant de conclure à l''impasse. L''exercice change ce que tu vois.'),
  ('q-0494', 'L''argent, c''est la liberté monnayée.', 'Fiodor Dostoïevski', 'finance', null, null, null, 'Dostoïevski définit l''argent par ce qu''il achète réellement : des choix. Cette lecture le sort de la morale pour en faire un instrument de liberté, avec ce que cela suppose de responsabilité.', 'Évalue tes décisions financières à l''aune des options qu''elles ouvrent ou ferment. Un achat qui réduit ta marge de manœuvre a un coût caché.'),
  ('q-0495', 'N''estime l''argent ni plus ni moins qu''il ne vaut : c''est un bon serviteur et un mauvais maître.', 'Alexandre Dumas', 'finance', null, null, null, 'Dumas propose une juste mesure : ni mépris ni fascination. L''argent bien employé sert ; laissé aux commandes, il dicte des choix qu''on n''aurait pas faits.', 'Vérifie quelles décisions tu prends uniquement pour des raisons financières. Si la liste est longue, c''est le serviteur qui dirige.'),
  ('q-0496', 'L''argent qu''on possède est celui de la liberté ; celui qu''on pourchasse est celui de la servitude.', 'Jean-Jacques Rousseau', 'finance', null, null, null, 'Rousseau oppose deux rapports à l''argent : celui qu''on détient élargit les possibles, celui qu''on poursuit impose des contraintes. La différence tient au manque, pas au montant.', 'Distingue ce que tu gagnes de ce que tu poursuis. Une course sans terme défini produit de la contrainte quel que soit le revenu atteint.'),
  ('q-0497', 'Quand j''étais jeune, je croyais que, dans la vie, l''argent était le plus important. Maintenant que je suis vieux, je le sais !', 'Oscar Wilde', 'finance', null, null, null, 'Wilde retourne la formule attendue : au lieu de dire qu''il s''est trompé en jeunesse, il confirme son intuition. L''ironie sert à dire une vérité inconfortable sur le rôle réel de l''argent.', 'Sois lucide sur ce que l''argent permet dans ta situation, sans le surestimer ni le nier. Les deux erreurs conduisent à de mauvaises décisions.'),
  ('q-0498', 'Il y a tellement de choses plus importantes dans la vie que l''argent, mais il faut tellement d''argent pour les acquérir.', 'Groucho Marx', 'finance', null, null, null, 'Marx formule un paradoxe réel : les choses qui comptent le plus ne s''achètent pas, mais y accéder — du temps, de la santé, de la sécurité — suppose des moyens.', 'Vise le montant qui te donne accès à ce qui compte, pas le montant maximal. Les deux objectifs mènent à des vies très différentes.'),
  ('q-0499', 'Ce n''est pas parce que vous pouvez vous le permettre que vous devez l''acheter.', 'Suze Orman', 'finance', null, null, null, 'Orman sépare la capacité de payer de la pertinence d''acheter. Le fait de pouvoir se permettre une dépense ne dit rien sur son utilité ni sur son coût d''opportunité.', 'Avant un achat que tu peux te permettre, demande-toi ce que cet argent ferait ailleurs. La question change souvent la décision.'),
  ('q-0500', 'Ma philosophie d''investissement, généralement, avec des exceptions, est d''acheter quelque chose quand personne n''en veut.', 'Carl Icahn', 'finance', null, null, null, 'Icahn décrit une approche à contre-courant : acheter ce que personne ne veut, donc à prix bas. Il précise « avec des exceptions », ce qui rappelle que le désintérêt général est parfois justifié.', 'Quand une opportunité est délaissée, cherche pourquoi avant de conclure à une bonne affaire. Le désintérêt cache soit une occasion, soit un vrai problème.'),
  ('q-0503', 'Privilégiez le client, non la vente.', 'Katherine Barchetti', 'sales', null, null, null, 'Barchetti fixe une priorité : préserver la relation plutôt que conclure une vente. Une transaction obtenue au détriment du client coûte plus qu''elle ne rapporte sur la durée.', 'Quand une vente n''est pas dans l''intérêt du client, dis-le. Ce refus est l''investissement commercial le plus rentable qui soit.'),
  ('q-0504', 'Ne célébrez pas la clôture d''une vente, célébrez l''ouverture d''une relation.', 'Patricia Fripp', 'sales', null, null, null, 'Fripp déplace le moment de la réussite : la signature n''est pas une fin mais un début. Célébrer la clôture oriente l''attention vers l''acquisition et néglige ce qui suit.', 'Prévois ton suivi client avant de signer. C''est ce qui se passe après qui déterminera le renouvellement et la recommandation.'),
  ('q-0507', 'Si vous ne prenez pas soin de votre client, votre concurrent le fera.', 'Bob Hooey', 'sales', null, null, null, 'Hooey rappelle qu''un client négligé n''est pas perdu par hasard : quelqu''un d''autre s''occupe de lui. L''inattention n''est pas neutre, elle transfère.', 'Identifie tes clients avec lesquels tu n''as pas eu de contact depuis six mois. Chacun est une opportunité pour un concurrent.'),
  ('q-0508', 'Intéressez-vous à créer de la valeur pour vos clients. Si vous comprenez bien cette partie, la vente est facile.', 'Anthony Iannarino', 'sales', null, null, null, 'Iannarino conditionne la facilité de la vente à la valeur créée en amont. Si le client perçoit un bénéfice net, la conclusion devient une formalité ; sinon aucune technique ne compense.', 'Avant ton prochain rendez-vous, prépare une chose utile que tu apporteras quel que soit le résultat. Cela change complètement la conversation.'),
  ('q-0509', 'Les grands vendeurs sont des créateurs de relations qui apportent de la valeur et aident leurs clients à gagner.', 'Jeffrey Gitomer', 'sales', null, null, null, 'Gitomer redéfinit le métier commercial : la valeur créée pour le client précède la transaction, et la relation en découle. Vendre devient une conséquence, pas l''objectif direct.', 'Avant ta prochaine relance, demande-toi ce que tu peux apporter d''utile sans rien vendre. C''est ce qui te distinguera de tous ceux qui relancent.'),
  ('q-0510', 'L''éthique et les valeurs d''un vendeur contribuent davantage au succès des ventes que les techniques ou les stratégies.', 'Ron Willingham', 'sales', null, null, null, 'Willingham place l''éthique au-dessus de la technique en matière commerciale. Les méthodes s''apprennent et se copient, la réputation d''honnêteté ne se fabrique pas et décide des affaires longues.', 'Sur ton prochain dossier, dis explicitement une limite de ton offre. Ce que tu perds ponctuellement, tu le regagnes en crédibilité durable.'),
  ('q-0511', 'Les meilleures questions de vente témoignent de votre expertise.', 'Jill Konrath', 'sales', null, null, null, 'Konrath relie la qualité des questions à la démonstration de compétence : une question précise prouve qu''on comprend le métier du client mieux qu''un argumentaire.', 'Prépare trois questions qu''un non-spécialiste ne saurait pas poser. Elles établiront ta crédibilité plus vite que ta présentation.'),
  ('q-0512', 'Ne vous plaignez jamais d''un client difficile, car il est la cause de vos progrès.', 'Auguste Detoeuf', 'sales', null, null, null, 'Detoeuf traite le client difficile comme une ressource : ses exigences révèlent des défauts que les clients satisfaits ne signalent pas. Il coûte cher et fait progresser.', 'Analyse la réclamation la plus pénible que tu as reçue. Elle contient souvent une amélioration que personne d''autre n''aurait formulée.'),
  ('q-0513', 'Parler est un besoin, écouter est un art.', 'Goethe', 'sales', null, null, null, 'Goethe oppose un réflexe à une compétence : parler vient naturellement, écouter demande un travail. C''est ce déséquilibre qui rend l''écoute rare et précieuse.', 'Dans ton prochain échange important, mesure ton temps de parole. Au-delà de la moitié, tu n''as probablement pas appris grand-chose.'),
  ('q-0514', 'Les clients ne se soucient pas du tout de savoir si vous concluez la transaction ou non. Ils se soucient d''améliorer leur entreprise.', 'Aaron Ross', 'sales', null, null, null, 'Ross recentre la vente sur l''intérêt du client : il ne se préoccupe pas de tes objectifs commerciaux, seulement de ce que ta solution change pour lui.', 'Reformule ton argumentaire en supprimant toute mention de tes objectifs. Ce qui reste est ce qui intéresse réellement l''acheteur.'),
  ('q-0516', 'Être premier sur un marché n''est pas tout. La fidélité des clients est tout.', 'Stefan Persson', 'sales', null, null, null, 'Persson relativise l''avantage du premier entrant : arriver en tête donne une avance temporaire, la fidélité produit un revenu durable. La seconde se construit après, pas avant.', 'Mesure ton taux de réachat autant que ton acquisition. Le premier chiffre indique si ta croissance repose sur du solide.'),
  ('q-0518', 'Dire la vérité est la meilleure campagne marketing.', 'Richie Norton', 'sales', null, null, null, 'Norton défend la franchise comme stratégie commerciale : elle se vérifie, se transmet et ne demande aucun budget. Le mensonge, lui, coûte à chaque fois qu''il est découvert.', 'Remplace une formulation avantageuse mais discutable par la version exacte. Tu perdras quelques prospects et gagneras des clients qui restent.'),
  ('q-0519', 'Le bon entrepreneur, c''est vous : il n''y a pas de profil type pour réussir.', 'Xavier Niel', 'mindset', null, null, null, 'Niel refuse le profil type de l''entrepreneur — diplôme, parcours, réseau. Cette croyance élimine par avance des gens capables, sur des critères sans rapport avec ce qui fait réussir.', 'Cesse de comparer ton parcours à celui des fondateurs médiatisés. La seule question utile est de savoir si tu résous un problème réel pour quelqu''un.'),
  ('q-0520', 'On peut casser les codes d''un secteur et oser ce que personne n''a osé faire.', 'Xavier Niel', 'leadership', null, null, null, 'Niel décrit une stratégie de rupture : dans un secteur où tous appliquent les mêmes règles, les enfreindre crée un avantage que la taille ne procure pas.', 'Liste les règles que ton secteur suit sans les questionner — tarification, contrat, distribution. Une seule remise en cause suffit à te rendre différent.'),
  ('q-0522', 'L''échec n''est pas le contraire du succès, c''est une étape nécessaire pour y parvenir.', 'Marc Simoncini', 'mindset', null, null, null, 'Simoncini place l''échec dans la séquence qui mène au succès plutôt qu''en opposition. Cette lecture transforme un revers en information sur la suite du chemin.', 'Après un échec, cherche ce qu''il t''apprend sur l''étape suivante plutôt que sur tes capacités. La première question produit une action.'),
  ('q-0524', 'Le cœur a ses raisons que la raison ne connaît point.', 'Blaise Pascal', 'mindset', null, 'Pensées', 1670, 'Pascal distingue deux ordres de raisons : celles de la logique et celles du sentiment, qui obéissent à leur propre cohérence. Ignorer les secondes conduit à mal comprendre les décisions humaines.', 'Quand une décision t''échappe malgré une analyse impeccable, cherche ce qui se joue affectivement. C''est souvent là que se trouve la vraie raison.'),
  ('q-0525', 'L''essentiel est invisible pour les yeux.', 'Antoine de Saint-Exupéry', 'mindset', 'Ce que le renard confie au Petit Prince avant de le laisser repartir, après lui avoir appris ce qu''apprivoiser veut dire.', 'Le Petit Prince', 1943, 'Le renard désigne ce qui compte et qui échappe au regard : la confiance, l''attachement, le temps investi. Ces éléments décident de tout mais n''apparaissent sur aucun tableau de bord.', 'Quand tu évalues une relation professionnelle, ne t''arrête pas aux chiffres. Ce qui la rend solide — ou fragile — ne s''y trouve pas.'),
  ('q-0526', 'Fais de ta vie un rêve, et d''un rêve, une réalité.', 'Antoine de Saint-Exupéry', 'mindset', null, null, null, 'Saint-Exupéry décrit un enchaînement en deux temps : concevoir ce qu''on veut, puis le construire. La formule ne dispense pas du travail, elle rappelle que sans le rêve initial il n''y a rien à réaliser.', 'Écris ce que tu voudrais avoir construit dans dix ans, sans filtrer par le réalisme. Le tri viendra ensuite ; le faire trop tôt supprime tout ce qui vaut la peine.'),
  ('q-0527', 'L''ambition s''accorde mal avec la paresse.', 'La Rochefoucauld', 'mindset', null, null, null, 'La Rochefoucauld pointe une incompatibilité pratique : vouloir beaucoup et fournir peu ne se combine pas. L''ambition non suivie d''effort produit surtout de la frustration.', 'Compare l''ambition que tu affiches au temps que tu y consacres réellement. L''écart entre les deux explique la plupart des projets qui n''avancent pas.'),
  ('q-0529', 'Ne pas avoir peur d''échouer compte plus que ce qu''on apprend à l''école.', 'Sara Blakely', 'mindset', null, null, null, 'Blakely oppose deux formations : celle qui transmet des connaissances et celle qui apprend à encaisser l''échec. La seconde ne s''enseigne pas en classe et détermine pourtant davantage ce qu''on osera entreprendre.', 'Expose-toi volontairement à de petits refus — une demande, une proposition, une candidature. La tolérance à l''échec se construit par la pratique, pas par la réflexion.'),
  ('q-0531', 'Terminé vaut mieux que parfait : mieux vaut avancer qu''attendre la perfection.', 'Sheryl Sandberg', 'mindset', null, null, null, 'Sandberg arbitre entre deux coûts : celui d''un travail imparfait livré, et celui d''un travail parfait jamais terminé. Le second est plus élevé parce qu''il ne produit rien du tout.', 'Fixe une date de livraison avant de commencer, et livre à cette date l''état atteint. L''amélioration continue après la mise en service, pas avant.'),
  ('q-0532', 'Demandez-vous : que ferais-je si je n''avais pas peur ? Puis faites-le.', 'Sheryl Sandberg', 'mindset', null, null, null, 'Sandberg utilise la peur comme révélateur de préférence : ce qu''on ferait sans elle indique ce qu''on veut vraiment. La question sépare le désir réel des renoncements déguisés en choix raisonnables.', 'Pose-toi la question par écrit et note la première réponse qui vient. C''est généralement celle qui compte, avant que les justifications arrivent.'),
  ('q-0534', 'Si vous n''avez pas honte de la première version de votre produit, vous avez lancé trop tard.', 'Reid Hoffman', 'leadership', null, null, null, 'Hoffman propose la gêne comme indicateur de calendrier : si la première version te paraît présentable, tu as attendu trop longtemps et perdu du temps d''apprentissage.', 'Livre ta prochaine version quand elle résout le problème principal, même mal. Les retours réels valent mieux que les améliorations imaginées.'),
  ('q-0535', 'L''échec n''est pas l''opposé de la réussite, il en fait partie.', 'Arianna Huffington', 'mindset', null, null, null, 'Huffington place l''échec à l''intérieur du parcours plutôt qu''en face. Cette lecture change ce qu''on en fait : une étape se traverse, un contraire se combat.', 'Quand un échec survient, demande-toi de quelle étape il s''agit plutôt que s''il fallait l''éviter. La première question fait avancer, la seconde paralyse.'),
  ('q-0536', 'Le succès peut pousser à désapprendre les habitudes qui nous ont fait réussir.', 'Satya Nadella', 'mindset', null, null, null, 'Nadella pointe un piège : les habitudes qui ont produit le succès deviennent des réflexes qu''on n''interroge plus, alors même que le contexte a changé. Le succès rend donc l''adaptation plus difficile, pas plus facile.', 'Repère une pratique que tu maintiens parce qu''elle a marché autrefois. Vérifie qu''elle fonctionne encore dans les conditions actuelles, pas dans celles d''il y a cinq ans.'),
  ('q-0537', 'Il faut passer d''une culture du tout savoir à une culture du tout apprendre.', 'Satya Nadella', 'leadership', null, null, null, 'Nadella oppose deux postures : celle où l''on est valorisé pour savoir, qui pousse à cacher son ignorance, et celle où l''on est valorisé pour apprendre, qui autorise à poser des questions. La seconde va beaucoup plus vite.', 'En réunion, dis « je ne sais pas » au moins une fois quand c''est vrai. Ce que tu perds en assurance apparente, ton équipe le gagne en liberté de faire pareil.'),
  ('q-0539', 'On peut se focaliser sur les obstacles, ou se concentrer pour franchir le mur.', 'Tim Cook', 'mindset', null, null, null, 'Cook oppose deux emplois de l''attention : détailler l''obstacle, ou chercher le passage. Les deux consomment le même temps, un seul produit un mouvement.', 'Quand une réunion s''enlise sur les difficultés, redemande explicitement des propositions de franchissement. Le changement de question suffit souvent.'),
  ('q-0540', 'Le poison le plus dangereux, c''est le sentiment d''avoir réussi.', 'Ingvar Kamprad', 'mindset', null, null, null, 'Kamprad désigne le sentiment d''avoir réussi comme le vrai danger : il installe la satisfaction là où il faudrait de la vigilance, et transforme une avance en retard sans qu''on le remarque.', 'Après un bon trimestre, consacre une réunion à ce qui ne va pas. Le moment où personne n''en voit l''utilité est précisément celui où c''est utile.'),
  ('q-0541', 'Le temps est votre ressource la plus précieuse : une fois perdu, il est perdu pour de bon.', 'Ingvar Kamprad', 'mindset', null, null, null, 'Kamprad range le temps parmi les ressources non renouvelables. Contrairement à l''argent, il ne se récupère pas — ce qui devrait en faire l''objet du calcul le plus rigoureux.', 'Traite ton agenda comme un budget : chaque acceptation retire du temps à autre chose. La question n''est pas « est-ce utile » mais « est-ce plus utile que ce que ça remplace ».'),
  ('q-0544', 'Personne ne voit l''entrepreneuriat comme une survie, pourtant c''est exactement ça.', 'Anita Roddick', 'leadership', null, null, null, 'Roddick décrit une réalité peu racontée : l''entrepreneuriat est d''abord une affaire de survie, pas de vision. Le décalage avec l''image publique laisse beaucoup de fondateurs se croire seuls à galérer.', 'Si ton quotidien ressemble davantage à de la survie qu''à de la stratégie, sache que c''est la norme. Cela ne dit rien de la qualité de ton projet.'),
  ('q-0545', 'Il est impossible de vivre sans jamais échouer, à moins de vivre trop prudemment pour vivre vraiment.', 'J.K. Rowling', 'mindset', null, null, null, 'Rowling pose une alternative sans échappatoire : soit on échoue parfois, soit on a organisé sa vie pour ne rien risquer — et cette prudence est elle-même une forme de renoncement.', 'Vérifie que ta prudence protège quelque chose qui compte. Une vie sans échec signale souvent une ambition rabotée par précaution.'),
  ('q-0546', 'Notre seul vrai plan stratégique, c''est d''agir, tout simplement.', 'Herb Kelleher', 'leadership', null, null, null, 'Kelleher se moque des plans stratégiques élaborés au détriment de l''exécution. La formule ne rejette pas la réflexion mais son usage comme substitut à l''action.', 'Si ton plan est prêt depuis un mois sans première action, lance-la cette semaine. Le terrain corrigera le plan mieux qu''une révision supplémentaire.'),
  ('q-0547', 'Le succès est lié à l''action : ceux qui réussissent avancent sans cesse, malgré les erreurs.', 'Conrad Hilton', 'mindset', null, null, null, 'Hilton lie la réussite au mouvement continu, erreurs comprises. Ceux qui avancent commettent des fautes mais accumulent de l''expérience ; ceux qui attendent la certitude n''accumulent rien.', 'Autorise-toi à avancer avec une information incomplète, en gardant la possibilité de corriger. C''est le rythme, pas la perfection, qui produit le résultat.'),
  ('q-0548', 'Faites des erreurs, mais faites-les plus vite que les autres.', 'Andrew Grove', 'mindset', null, null, null, 'Grove ne valorise pas l''erreur mais la vitesse de détection. Se tromper vite et le savoir coûte peu ; se tromper lentement laisse le temps d''investir dans la mauvaise direction.', 'Raccourcis tes cycles de vérification : teste sur un échantillon avant de déployer. L''objectif n''est pas d''éviter l''erreur mais de la découvrir tôt.'),
  ('q-0549', 'Jouez des jeux à long terme, avec des gens qui jouent aussi le long terme.', 'Naval Ravikant', 'mindset', null, null, null, 'Naval relie la durée et la qualité des partenaires. Dans une relation qui se répète, la confiance devient rentable pour les deux parties ; dans une relation ponctuelle, l''intérêt de court terme prend le dessus.', 'Avant de t''engager avec quelqu''un, demande-toi si tu envisages de retravailler avec lui dans cinq ans. Cette question change la façon dont chacun se comporte.'),
  ('q-0550', 'Recherchez la richesse, pas l''argent ni le statut.', 'Naval Ravikant', 'finance', null, null, null, 'Naval sépare trois choses qu''on confond : l''argent est un moyen d''échange, le statut est un jeu à somme nulle où l''un monte quand l''autre descend, et la richesse est un ensemble d''actifs qui produisent pendant que tu dors.', 'Vérifie que tes efforts construisent quelque chose qui continue sans toi. Courir après la reconnaissance consomme la même énergie sans rien laisser derrière.'),
  ('q-0551', 'Le revenu est la meilleure forme de financement.', 'Naval Ravikant', 'finance', null, null, null, 'Naval rappelle que l''argent produit par l''activité elle-même ne se rembourse pas, ne dilue rien et n''impose aucune contrainte extérieure. C''est le financement le moins cher, même s''il est le plus lent.', 'Avant de chercher un financement externe, regarde ce que ton activité peut autofinancer. La contrainte oblige souvent à trouver un modèle plus solide.'),
  ('q-0552', 'Dans une startup, l''exécution est tout.', 'Paul Graham', 'leadership', null, null, null, 'Graham place l''exécution au-dessus de l''idée. Les idées circulent et se ressemblent ; ce qui distingue les projets, c''est la capacité à les mener, ce que personne ne peut copier.', 'Cesse de protéger ton idée et commence à la construire. Ceux qui l''auraient volée n''auraient de toute façon pas fait le travail.'),
  ('q-0553', 'N''embauchez pas de génies toxiques : le coût pour l''esprit d''équipe est trop élevé.', 'Reed Hastings', 'leadership', null, null, null, 'Hastings arbitre entre talent individuel et coût collectif : une personne brillante mais destructrice fait perdre plus qu''elle n''apporte, parce qu''elle dégrade le travail de tous les autres.', 'Quand quelqu''un de performant abîme l''équipe, chiffre l''effet sur les autres avant de trancher. Le calcul individuel est presque toujours trompeur.'),
  ('q-0555', 'Mon but n''est pas d''échouer vite, mais de réussir sur la durée : ce n''est pas la même chose.', 'Marc Andreessen', 'leadership', null, null, null, 'Andreessen corrige un slogan devenu paresseux : échouer vite n''a d''intérêt que si l''on apprend et qu''on finit par réussir. Faire de l''échec rapide un objectif revient à confondre le moyen et la fin.', 'Quand tu abandonnes vite, vérifie que tu as appris quelque chose de réutilisable. Sinon tu n''as pas itéré, tu as juste renoncé rapidement.'),
  ('q-0556', 'Les mauvais managers embauchent de très mauvais employés car ils se sentent menacés par les meilleurs.', 'Marc Andreessen', 'leadership', null, null, null, 'Andreessen décrit une spirale : un manager peu sûr recrute moins fort que lui pour ne pas être menacé, et ces recrues font pareil. La qualité d''une organisation se dégrade par niveaux successifs.', 'À chaque recrutement, demande-toi si la personne pourrait te remplacer un jour. Répondre non par confort est le début de la spirale.'),
  ('q-0557', 'Chaque décision difficile mais juste vous rend un peu plus courageux.', 'Ben Horowitz', 'mindset', null, null, null, 'Horowitz décrit le courage comme un muscle : chaque décision difficile prise correctement rend la suivante moins coûteuse. À l''inverse, chaque évitement rend l''évitement plus probable.', 'Traite la décision désagréable que tu repousses. Au-delà du sujet lui-même, c''est ta capacité à trancher la prochaine qui se joue.'),
  ('q-0558', 'Un fondateur doit croire qu''une solution existe et la chercher, sans se soucier des probabilités.', 'Ben Horowitz', 'leadership', null, null, null, 'Horowitz décrit la position particulière du fondateur : raisonner en probabilités conduit à abandonner, puisque les statistiques sont défavorables. Son travail est de chercher la solution en supposant qu''elle existe.', 'Face à un problème qualifié d''insoluble, impose-toi de produire trois pistes avant de conclure. La conviction qu''une solution existe change ce que tu cherches.'),
  ('q-0559', 'Toute grande entreprise repose sur un secret caché du reste du monde.', 'Peter Thiel', 'mindset', null, null, null, 'Thiel appelle « secret » une vérité importante que peu de gens partagent. Une entreprise qui repose sur un consensus n''a aucun avantage : si tout le monde le sait, tout le monde peut le faire.', 'Formule ce que tu crois et que la plupart des gens de ton secteur contestent. Si tu ne trouves rien, ton positionnement est probablement interchangeable.'),
  ('q-0560', 'La concurrence tue les profits ; visez plutôt un monopole créatif qui profite à tous.', 'Peter Thiel', 'finance', null, null, null, 'Thiel distingue le monopole obtenu par la barrière du monopole obtenu par la création : être seul parce qu''on a inventé quelque chose de neuf profite aussi au client, contrairement à la rente protégée.', 'Cherche à être seul sur un segment étroit plutôt que dixième sur un marché large. Le premier laisse des marges qui financent la suite, le second les élimine.'),
  ('q-0561', 'On voulait des voitures volantes, on a eu 140 caractères.', 'Peter Thiel', 'mindset', 'Formule d''ouverture du manifeste de son fonds d''investissement, pour dénoncer une innovation qui se serait repliée sur le numérique en délaissant le monde physique.', 'Manifeste de Founders Fund', 2011, 'Thiel formule une critique de l''orientation de l''innovation : les progrès des dernières décennies se sont concentrés sur l''information plutôt que sur le monde physique. La phrase est un reproche, pas un constat neutre.', 'Demande-toi si ce que tu construis résout un problème réel ou optimise un détail. La seconde catégorie est plus facile à financer et beaucoup moins utile.'),
  ('q-0562', 'Si ça ne vend pas, ce n''est pas créatif.', 'David Ogilvy', 'sales', null, null, null, 'Ogilvy, publicitaire, soumet la créativité à un critère unique : l''effet commercial. Une campagne remarquée mais sans vente n''a pas rempli sa fonction, quel que soit son mérite artistique.', 'Avant de valider une communication, définis le résultat attendu et comment tu le mesureras. Sans ce critère, seul le goût tranchera.'),
  ('q-0563', 'Dites la vérité, mais rendez-la fascinante : on n''achète pas ce qui nous ennuie.', 'David Ogilvy', 'sales', null, null, null, 'Ogilvy pose deux exigences conjointes : dire vrai, et le dire de façon intéressante. La première sans la seconde est ignorée, la seconde sans la première ne survit pas au premier achat.', 'Reprends ton argumentaire et supprime ce qui est exact mais ennuyeux. Garde ce qui est à la fois vrai et digne d''être écouté.'),
  ('q-0564', 'Si chacun de nous embauche des gens plus petits que lui, nous deviendrons une entreprise de nains.', 'David Ogilvy', 'leadership', null, null, null, 'Ogilvy décrit l''effet cumulatif du recrutement défensif : si chacun recrute moins bon que lui, l''organisation rétrécit à chaque génération. L''image des nains rend le mécanisme visible.', 'Fixe comme règle de recruter quelqu''un de meilleur que toi sur au moins une dimension. C''est vérifiable, et ça inverse la spirale.'),
  ('q-0565', 'Les grands battants sont portés non par la quête du succès, mais par la peur de l''échec.', 'Larry Ellison', 'mindset', null, null, null, 'Ellison propose une lecture inhabituelle de la motivation : la crainte de l''échec pousse plus fort et plus longtemps que l''attrait du succès. C''est un constat sur les moteurs réels, pas une recommandation.', 'Identifie ce qui te motive réellement — obtenir, ou éviter. Connaître son propre moteur permet de l''utiliser plutôt que de le subir.'),
  ('q-0566', 'Quand on innove, il faut être prêt à ce que tout le monde vous dise que vous êtes fou.', 'Larry Ellison', 'mindset', null, null, null, 'Ellison décrit une conséquence mécanique de l''innovation : ce qui est nouveau ne peut pas être évalué avec les critères existants, donc il est jugé absurde. Le rejet est un effet, pas un verdict.', 'Quand une idée provoque un rejet unanime, distingue les objections argumentées des réactions d''incompréhension. Seules les premières doivent te faire réviser.'),
  ('q-0567', 'Pas besoin d''être un génie ou un visionnaire pour réussir : il faut un cadre et un rêve.', 'Michael Dell', 'mindset', null, null, null, 'Dell dédramatise l''entrepreneuriat : il ne faut ni génie ni vision prophétique, mais une structure de travail et une direction. Deux choses accessibles à qui décide de s''organiser.', 'Si tu attends d''avoir une idée géniale, remplace cette attente par un cadre de travail régulier. Les idées viennent en travaillant, pas en attendant.'),
  ('q-0568', 'Les entreprises réussissent ou échouent selon leur capacité à transformer la donnée en décisions.', 'Michael Dell', 'leadership', null, null, null, 'Dell relie la donnée à la décision. Accumuler des chiffres sans les convertir en choix ne produit rien : la valeur est dans la conversion, pas dans la collecte.', 'Pour chaque indicateur que tu suis, écris la décision qu''il déclenchera. Ceux qui n''en déclenchent aucune peuvent être supprimés.'),
  ('q-0569', 'Le but du marketing est de rendre la vente superflue.', 'Peter Drucker', 'sales', null, 'Les Fondements du marketing', null, 'Drucker définit la réussite du marketing par sa propre disparition : si l''offre correspond exactement au besoin, il n''y a plus rien à convaincre. La vente devient l''aveu que le travail en amont est incomplet.', 'Quand une vente demande beaucoup d''efforts, remonte d''un cran : le message, la cible ou le produit sont mal ajustés. C''est là que se trouve le gain, pas dans un argumentaire supplémentaire.'),
  ('q-0570', 'Les gens détestent qu''on leur vende, mais ils adorent acheter.', 'Jeffrey Gitomer', 'sales', null, null, null, 'Gitomer distingue deux expériences opposées : subir une pression, ou décider par soi-même. Le produit peut être identique, c''est le sentiment de contrôle qui change tout.', 'Remplace tes affirmations par des questions qui aident le client à évaluer. Il conclura lui-même, et il défendra sa décision au lieu de la regretter.'),
  ('q-0571', 'Le marketing ne consiste plus à parler des produits que vous fabriquez, mais à raconter des histoires.', 'Seth Godin', 'sales', null, null, null, 'Godin décrit un déplacement du marketing : les caractéristiques se comparent et se copient, un récit crée un lien et une mémoire. Ce qu''on retient d''une marque est une histoire, pas une fiche technique.', 'Raconte comment ton produit est né et quel problème t''a poussé à le créer. C''est ce que les gens répéteront, pas tes spécifications.'),
  ('q-0572', 'Approchez chaque client avec l''idée de l''aider à résoudre un problème, pas de lui vendre un produit.', 'Brian Tracy', 'sales', null, null, null, 'Tracy réoriente l''intention commerciale : arriver avec l''idée d''aider change les questions posées, donc l''information obtenue, donc la pertinence de la proposition. La vente devient une conséquence.', 'Ouvre ton prochain rendez-vous par une question sur le problème du client, pas par ta présentation. Tu sauras vite si tu peux réellement l''aider.'),
  ('q-0573', 'Faites de votre client le héros de votre histoire.', 'Ann Handley', 'sales', null, null, null, 'Handley inverse les rôles du récit commercial : le client est le personnage principal, l''entreprise est l''outil qui l''aide. La plupart des communications font l''inverse et n''intéressent personne.', 'Réécris ta présentation en mettant le client au centre et ton produit en soutien. Le changement de perspective transforme la réception.'),
  ('q-0574', 'La meilleure publicité est celle que font les clients satisfaits.', 'Philip Kotler', 'sales', null, null, null, 'Kotler désigne le seul message parfaitement crédible : celui d''un client qui n''a rien à gagner à le dire. Aucune campagne ne reproduit cette crédibilité, parce que l''émetteur y est toujours intéressé.', 'Facilite le témoignage : demande-le au bon moment, juste après un résultat obtenu. C''est un levier moins coûteux que la publicité et plus efficace.'),
  ('q-0575', 'Si vous essayez de plaire à tout le monde, vous n''intéresserez personne.', 'Seth Godin', 'sales', null, null, null, 'Godin explique pourquoi le consensus est commercialement stérile : pour plaire à tous, il faut retirer tout ce qui pourrait déplaire — c''est-à-dire tout ce qui distingue. Le résultat n''intéresse personne.', 'Assume ce qui, dans ton offre, ne conviendra pas à tout le monde. C''est exactement ce qui la rendra indispensable à certains.'),
  ('q-0576', 'Vendre, ce n''est pas convaincre quelqu''un d''acheter, c''est l''aider à décider.', 'Zig Ziglar', 'sales', null, null, null, 'Ziglar déplace le rôle du vendeur : il ne s''agit pas de vaincre une résistance mais de lever ce qui empêche la décision. Le client veut souvent avancer et bute sur une incertitude que personne ne l''aide à résoudre.', 'Demande à ton prospect ce qu''il lui manque pour décider. La réponse est presque toujours plus simple à traiter que l''argumentaire que tu avais prévu.'),
  ('q-0577', 'La qualité d''un service se mesure à la façon dont on répare ses erreurs.', 'Donald Porter', 'sales', null, null, null, 'Porter place la qualité de service au moment de l''erreur : tout le monde est bon quand rien ne va mal. C''est la réparation qui révèle le niveau réel et fidélise ou non.', 'Définis à l''avance ce que tu fais quand tu te trompes — geste commercial, délai, interlocuteur. Improviser dans l''urgence produit toujours une réponse médiocre.'),
  ('q-0578', 'Rapprochez-vous plus que jamais de vos clients. Si près que vous leur direz ce dont ils ont besoin avant qu''ils s''en rendent compte.', 'Steve Jobs', 'sales', null, null, null, 'Jobs vise un niveau de connaissance client supérieur à la demande exprimée : les gens décrivent leurs irritants, rarement la solution. Le rôle de l''entreprise est de faire cette traduction avant qu''on la lui demande.', 'Écoute tes clients parler de leur problème, pas de ton produit. Les mots qu''ils emploient pour décrire leur galère valent plus que toutes leurs suggestions d''améliorations.'),
  ('q-0579', 'Le prix est ce que vous payez, la valeur est ce que vous obtenez.', 'Warren Buffett', 'finance', 'Buffett y attribue explicitement la leçon à son mentor Benjamin Graham, plutôt que de se l''approprier.', 'Lettre aux actionnaires de Berkshire Hathaway', 2008, 'Buffett sépare deux choses que le quotidien confond : le prix est ce qu''on affiche, la valeur est ce qu''on reçoit. Un prix bas ne rend rien bon marché si la valeur est moindre encore, et l''inverse est vrai aussi.', 'Devant une dépense, chiffre séparément ce qu''elle coûte et ce qu''elle t''apporte réellement. Le réflexe de comparer deux prix entre eux, sans passer par la valeur, est ce qui fait acheter le moins cher plutôt que le plus utile.'),
  ('q-0580', 'À court terme le marché est une machine à voter ; à long terme, c''est une balance.', 'Benjamin Graham', 'finance', null, 'L''Investisseur intelligent', 1949, 'Graham distingue deux mécanismes : à court terme, le prix reflète l''opinion, changeante et grégaire ; à long terme, il finit par refléter la substance réelle. L''écart entre les deux est temporaire mais peut durer longtemps.', 'Quand tu juges un projet ou une entreprise, sépare ce qu''en pensent les gens aujourd''hui de ce qu''elle produit réellement. La première donnée est bruyante, la seconde décide à la fin.'),
  ('q-0581', 'Montrez-moi les incitations et je vous montrerai le résultat.', 'Charlie Munger', 'finance', null, null, null, 'Munger énonce un outil de diagnostic redoutable : quand un comportement paraît absurde, c''est presque toujours qu''il est récompensé quelque part. Chercher la faute morale fait perdre du temps ; chercher l''incitation explique tout.', 'Devant un comportement récurrent qui te dépasse, demande-toi ce qu''il rapporte à celui qui l''adopte. Change l''incitation, et le comportement suit sans qu''il y ait besoin de convaincre.'),
  ('q-0582', 'Devenir riche et le rester sont deux compétences complètement différentes.', 'Morgan Housel', 'finance', null, 'La Psychologie de l''argent', 2020, 'Housel sépare deux compétences opposées : s''enrichir demande de la prise de risque et de l''optimisme, le rester demande de la prudence et de la paranoïa. Beaucoup échouent en appliquant la première logique trop longtemps.', 'Quand une situation s''améliore, change de mode : passe de l''expansion à la consolidation. Continuer sur la même intensité est la cause la plus fréquente des retours en arrière.'),
  ('q-0583', 'Ce n''est pas votre salaire qui vous enrichit, c''est vos habitudes de dépense.', 'Charles A. Jaffe', 'finance', null, null, null, 'Jaffe déplace la cause de l''enrichissement du revenu vers le comportement de dépense. Un revenu élevé intégralement consommé ne construit rien, contrairement à un revenu modeste bien géré.', 'Suis ton taux d''épargne plutôt que ton revenu. C''est le seul des deux chiffres que tu contrôles directement.'),
  ('q-0585', 'Un budget, c''est dire à son argent où aller au lieu de se demander où il est passé.', 'Dave Ramsey', 'finance', null, null, null, 'Ramsey définit le budget comme un acte de décision préalable plutôt qu''un exercice de constat. Décider avant supprime la surprise de fin de mois.', 'Affecte tes dépenses en début de mois, avant qu''elles arrivent. Le budget est un outil de décision, pas de comptabilité.'),
  ('q-0586', 'Le management c''est bien faire les choses ; le leadership c''est faire les bonnes choses.', 'Peter Drucker', 'leadership', null, null, null, 'Drucker sépare deux compétences que les organisations confondent : l''efficacité d''exécution et la justesse de direction. Être excellent sur la mauvaise chose reste un échec, simplement mieux organisé.', 'Avant d''optimiser un processus, vérifie qu''il devrait exister. La question « faisons-nous bien » vient après « faisons-nous ce qu''il faut », jamais l''inverse.'),
  ('q-0587', 'Le leadership, ce n''est pas être aux commandes. C''est prendre soin de ceux dont on a la charge.', 'Simon Sinek', 'leadership', null, null, null, 'Sinek redéfinit la fonction : diriger n''est pas un privilège de décision mais une responsabilité envers des personnes. Le pouvoir est le moyen, la protection de l''équipe est la finalité.', 'Avant une décision difficile, demande-toi qui en portera les conséquences. Si ce n''est pas toi, ton rôle est d''amortir, pas seulement de transmettre.'),
  ('q-0589', 'Le leadership est l''art d''obtenir plus que ce que la science du management juge possible.', 'Colin Powell', 'leadership', null, null, null, 'Powell distingue le management, qui optimise dans un cadre donné, du leadership, qui obtient ce que le cadre déclarait impossible. La différence tient à l''engagement des personnes.', 'Quand une analyse conclut à l''impossibilité, demande ce qu''il faudrait pour que ça devienne possible. La réponse dépasse souvent les paramètres examinés.'),
  ('q-0590', 'Prenez soin des gens, du produit et des profits — dans cet ordre.', 'Ben Horowitz', 'leadership', null, null, null, 'Horowitz fixe un ordre de priorité, et c''est l''ordre qui porte le message : les gens d''abord, parce qu''ils font le produit, qui génère les profits. Inverser la séquence casse la chaîne à la source.', 'Quand tu arbitres sous pression, vérifie que tu ne sacrifies pas le premier terme pour sauver le troisième. C''est le raccourci le plus courant et le plus coûteux.'),
  ('q-0591', 'Seuls les paranoïaques survivent.', 'Andrew Grove', 'leadership', 'Titre du livre où Grove, alors patron d''Intel, raconte les « points d''inflexion stratégiques » qui peuvent emporter une entreprise dominante.', 'Livre « Only the Paranoid Survive »', 1996, 'Grove, dirigeant d''un secteur à cycles courts, décrit la vigilance permanente comme condition de survie. Ce n''est pas de l''anxiété mais un refus de considérer une position comme acquise.', 'Programme un point trimestriel sur ce qui pourrait te déplacer — nouvel entrant, changement d''usage, évolution réglementaire. La menace vient rarement de là où on regarde.'),
  ('q-0592', 'Embauchez des gens plus intelligents que vous, puis laissez-les faire leur travail.', 'Steve Jobs', 'leadership', null, null, null, 'Jobs pointe une incohérence fréquente : on recrute des gens compétents, puis on leur retire toute latitude. Le coût du contrôle excessif n''est pas le confort perdu, c''est la compétence achetée puis inutilisée.', 'Sur ta prochaine délégation, transmets l''objectif et la contrainte, pas la méthode. Et fixe le point de contrôle à l''avance, pour ne pas être tenté de repasser derrière entre-temps.'),
  ('q-0593', 'Un dirigeant doit dire la vérité, surtout quand elle est mauvaise.', 'Ben Horowitz', 'leadership', null, null, null, 'Horowitz place la franchise au moment où elle coûte le plus. Une mauvaise nouvelle annoncée tôt permet de réagir ; dissimulée, elle détruit la confiance quand elle finit par sortir — et elle finit toujours par sortir.', 'Quand une mauvaise nouvelle tombe, communique-la avant qu''on te la demande. Le coût de l''annonce est toujours inférieur à celui de la découverte.'),
  ('q-0595', 'Un bon dirigeant assume plus que sa part de responsabilité et prend moins que sa part de mérite.', 'Arnold H. Glasow', 'leadership', null, null, null, 'Glasow décrit une asymétrie volontaire : prendre plus que sa part de responsabilité et moins que sa part de crédit. C''est ce déséquilibre assumé qui crée la confiance.', 'Lors du prochain succès, attribue-le publiquement à l''équipe. Lors du prochain échec, assume-le publiquement. L''ordre inverse détruit l''autorité.'),
  ('q-0596', 'Le meilleur chef est celui dont on remarque à peine l''existence.', 'Lao Tseu', 'leadership', null, 'Tao Tö King, chapitre 17', null, 'Lao Tseu décrit un leadership qui s''efface : quand l''organisation fonctionne, l''intervention du chef devient invisible. La visibilité permanente d''un dirigeant signale souvent que rien ne tourne sans lui.', 'Mesure ce qui continue de fonctionner quand tu t''absentes une semaine. C''est le meilleur indicateur de la qualité de ce que tu as construit.'),
  ('q-0597', 'L''obstacle à l''action fait avancer l''action. Ce qui se met en travers du chemin devient le chemin.', 'Marc Aurèle', 'mindset', 'Écrit pour lui-même pendant ses campagnes militaires, dans un carnet jamais destiné à la publication.', 'Pensées pour moi-même, livre V', null, 'Marc Aurèle renverse le rapport à l''obstacle : ce qui bloque une voie oblige à en trouver une autre, et cette contrainte devient le chemin réel. L''empêchement se transforme en direction.', 'Quand une porte se ferme, demande-toi ce que cette fermeture t''oblige à explorer. Les meilleures bifurcations viennent rarement d''un choix confortable.'),
  ('q-0598', 'Ce ne sont pas les choses qui troublent les hommes, mais l''opinion qu''ils en ont.', 'Épictète', 'mindset', null, 'Manuel d''Épictète, V', null, 'Épictète situe la perturbation dans le jugement, pas dans l''événement. Deux personnes vivant la même chose ne réagissent pas pareil — la différence n''est donc pas dans le fait mais dans sa lecture.', 'Face à une contrariété, sépare ce qui s''est réellement passé de ce que tu en conclus. La plupart du temps, c''est la conclusion qui blesse, pas le fait.'),
  ('q-0599', 'Vous ne vous élevez pas au niveau de vos objectifs, vous retombez au niveau de vos systèmes.', 'James Clear', 'mindset', null, 'Un rien peut tout changer', 2018, 'Clear déplace la cause du résultat : un objectif indique une direction mais ne produit rien, c''est le système d''habitudes quotidiennes qui détermine où l''on arrive réellement.', 'Plutôt que de fixer un objectif plus ambitieux, améliore le processus qui te fait avancer chaque jour. C''est lui qui fixe ton niveau réel.'),
  ('q-0601', 'La douleur plus la réflexion égale le progrès.', 'Ray Dalio', 'mindset', null, null, null, 'Dalio pose une équation à trois termes où le terme du milieu est décisif : la douleur seule n''apprend rien, c''est la réflexion qui la convertit. Sans elle, on répète les mêmes erreurs avec la même intensité.', 'Après un épisode difficile, bloque une heure pour écrire ce qui s''est passé et pourquoi. C''est cette heure, pas l''épreuve, qui produit le progrès.'),
  ('q-0602', 'La concurrence est pour les perdants.', 'Peter Thiel', 'sales', 'Thiel y soutient que la concurrence pure détruit les marges et que les entreprises durables sont celles qui échappent à la concurrence, pas celles qui la gagnent.', 'Essai « Competition Is for Losers », Wall Street Journal', 2014, 'Thiel prend le contre-pied de l''éloge habituel de la concurrence : sur un marché concurrentiel, les marges tendent vers zéro et personne ne gagne durablement. La concurrence est bonne pour le consommateur, pas pour celui qui l''affronte.', 'Si tu te compares en permanence à des concurrents proches, cherche ce qui te rendrait incomparable. La différenciation vaut mieux que la surenchère.'),
  ('q-0603', 'Il vaut mieux avoir cent personnes qui vous adorent que cent mille qui vous trouvent sympathique.', 'Peter Thiel', 'sales', null, null, null, 'Thiel préfère l''intensité à la portée. Cent personnes qui tiennent réellement à ton produit en parlent, reviennent et pardonnent les défauts ; cent mille indifférents ne font rien de tout cela.', 'Plutôt que d''élargir ton audience, cherche à savoir qui serait vraiment déçu si tu disparaissais. C''est ce noyau qu''il faut servir en priorité.'),
  ('q-0604', 'Faites des choses qui ne passent pas à l''échelle.', 'Paul Graham', 'sales', 'Conseil à contre-courant adressé aux fondateurs : au début, il faut recruter ses premiers utilisateurs un par un, à la main, précisément parce que ça ne tient pas à grande échelle.', 'Essai « Do Things That Don''t Scale »', 2013, 'Graham conseille aux débutants ce qui semble inefficace : recruter ses premiers clients un par un, à la main. Ces méthodes ne tiennent pas à grande échelle, mais c''est là qu''on apprend ce que veulent les gens.', 'Contacte personnellement tes dix prochains clients plutôt que d''automatiser. Ce que tu apprendras vaut plus que le temps économisé.'),
  ('q-0605', 'Le logiciel est en train de dévorer le monde.', 'Marc Andreessen', 'sales', 'Essai écrit alors que les logiciels commençaient à remplacer des industries entières ; le titre est devenu la formule de référence pour décrire cette bascule.', 'Essai « Why Software Is Eating the World », Wall Street Journal', 2011, 'Andreessen constate que les logiciels absorbent des activités qui n''avaient rien d''informatique — distribution, transport, finance. Le secteur n''est plus une industrie parmi d''autres, il en redéfinit d''autres.', 'Demande-toi quelle partie de ton métier pourrait être automatisée par quelqu''un d''extérieur. Mieux vaut le découvrir avant qu''il le fasse.'),
  ('q-0606', 'Le seul moyen de gagner est d''apprendre plus vite que tout le monde.', 'Eric Ries', 'sales', null, null, null, 'Ries fait de la vitesse d''apprentissage le facteur concurrentiel décisif : dans un environnement incertain, celui qui teste et corrige le plus vite finit par trouver avant les autres.', 'Raccourcis le délai entre une hypothèse et sa vérification. Ce cycle, plus que la qualité des idées, détermine la vitesse de progression.'),
  ('q-0608', 'Il faut commencer par l''expérience client et remonter vers la technologie, jamais l''inverse.', 'Steve Jobs', 'sales', null, 'Conférence des développeurs Apple (WWDC), session de questions', 1997, 'Ordre de raisonnement, pas slogan. Partir de la technologie conduit à chercher un usage à ce qu''on sait faire ; partir de l''expérience oblige à ne retenir que la technologie qui sert réellement à quelque chose.', 'Avant d''ajouter une fonctionnalité, écris la phrase que le client dira une fois qu''elle existera. Si tu n''arrives pas à l''écrire de son point de vue, tu pars encore de l''outil.'),
  ('q-0609', 'Il faut accepter d''être incompris pendant longtemps.', 'Jeff Bezos', 'sales', null, null, null, 'Bezos décrit le coût réel du long terme : entre le moment où l''on prend une décision et celui où elle donne raison, il y a une période où l''on paraît avoir tort. Céder pendant cet intervalle revient à ne jamais jouer le long terme.', 'Quand tu t''engages sur une décision longue, note d''avance à quelle échéance tu accepteras de la juger. C''est cette date écrite qui te protégera des remises en cause à chaque commentaire négatif.'),
  ('q-0610', 'Ce qui compte, ce n''est pas ce que vous vendez, c''est le problème que vous résolvez.', 'Clayton Christensen', 'sales', null, null, null, 'Christensen recentre l''offre sur le problème résolu plutôt que sur le produit vendu. Les clients changent de solution, mais le problème reste — c''est lui qui définit le marché.', 'Décris ton activité par le problème que tu résous, pas par ce que tu vends. Cette formulation résiste aux évolutions technologiques.'),
  ('q-0611', 'Les gens n''achètent pas une perceuse, ils achètent un trou dans leur mur.', 'Theodore Levitt', 'sales', 'Formulation devenue le résumé de tout le marketing moderne : le client n''achète pas un produit, il achète le résultat qu''il en attend.', '« Marketing Myopia », Harvard Business Review', 1960, 'Levitt formule le principe fondateur du marketing moderne : le client n''achète pas un objet mais le résultat qu''il en attend. Décrire l''objet plutôt que le résultat manque la raison de l''achat.', 'Réécris ta présentation en partant du résultat obtenu par le client. Les caractéristiques viennent après, pour prouver que le résultat est atteignable.'),
  ('q-0614', 'Faites ce que vous faites si bien que les gens auront envie de revenir et d''amener leurs amis.', 'Walt Disney', 'sales', null, null, null, 'Disney décrit un modèle de croissance par la qualité : un client satisfait revient et amène d''autres personnes. C''est le seul canal d''acquisition qui se renforce au lieu de coûter plus cher.', 'Mesure combien de tes clients reviennent et combien en amènent d''autres. Améliorer ce chiffre coûte moins cher que d''acheter de nouveaux prospects.'),
  ('q-0615', 'On ne construit pas une réputation sur ce qu''on a l''intention de faire.', 'Henry Ford', 'sales', null, null, null, 'Ford oppose l''annonce à l''acte. Les intentions ne produisent aucune preuve, et personne ne peut évaluer ce que tu comptes faire — seulement ce que tu as fait. Communiquer avant d''avoir livré consomme du crédit sans en créer.', 'Avant d''annoncer un projet, demande-toi ce que tu peux déjà montrer. S''il n''y a rien, l''annonce ne fera qu''avancer la date à laquelle on te demandera des comptes.'),
  ('q-0616', 'Si vous avez le temps de flâner, vous avez le temps de nettoyer.', 'Ray Kroc', 'sales', 'Règle de terrain d''un homme qui inspectait lui-même les restaurants et jugeait la propreté aussi importante que la cuisine.', null, null, 'Kroc traite l''exigence comme une affaire d''occupation du temps disponible. Le temps mort n''existe pas : il est soit utilisé à améliorer, soit perdu — et cette règle s''applique d''abord au dirigeant.', 'Repère les creux dans ta semaine et affecte-leur d''avance une tâche de fond. Sans affectation préalable, ils se remplissent tout seuls de choses sans valeur.'),
  ('q-0617', 'Le doute tue plus de rêves que l''échec ne le fera jamais.', 'Suzy Kassem', 'sales', null, null, null, 'Kassem compare deux causes d''abandon : l''échec, qui laisse une information et une possibilité de recommencer, et le doute, qui empêche de commencer. Le second détruit plus de projets.', 'Quand tu hésites depuis longtemps, lance un test à petite échelle. L''information obtenue vaut mieux que des mois de délibération.'),
  ('q-0618', 'Créez quelque chose que les gens veulent vraiment. C''est tout.', 'Paul Graham', 'sales', null, null, null, 'Graham réduit la condition de réussite à une seule : produire quelque chose que des gens veulent réellement. Tout le reste — financement, croissance, organisation — découle ou ne sert à rien sans cela.', 'Vérifie que des gens seraient déçus si ton produit disparaissait. Si personne ne l''est, aucune optimisation ne compensera.'),
  ('q-0620', 'Quelqu''un est assis à l''ombre aujourd''hui parce qu''un autre a planté un arbre il y a longtemps.', 'Warren Buffett', 'finance', null, null, null, 'Image du décalage entre l''effort et son fruit : les bénéfices que tu récoltes aujourd''hui viennent de décisions prises par d''autres, longtemps avant. C''est un argument pour agir au profit d''un terme qu''on ne verra pas soi-même.', 'Identifie une chose que tu peux lancer maintenant et dont le bénéfice n''arrivera pas avant plusieurs années — une formation, une documentation, une relation. Le bon moment pour la commencer est celui où elle ne rapporte encore rien.'),
  ('q-0621', 'Les chaînes de l''habitude sont trop légères pour être senties, jusqu''à ce qu''elles deviennent trop lourdes pour être brisées.', 'Warren Buffett', 'finance', 'Une formule qui remonte en réalité à l''écrivain anglais Samuel Johnson au XVIIIe siècle ; Buffett la reprend sans se l''attribuer pour parler du poids des habitudes de gestion.', null, null, 'L''habitude s''installe sans résistance perceptible, ce qui la rend indétectable au début et impossible à défaire à la fin. La formule décrit un piège de temporalité : le moment où c''est facile est celui où ça paraît sans importance.', 'Repère un automatisme récent que tu juges anodin — une dépense, un raccourci, une tolérance. C''est maintenant qu''il se corrige sans effort, pas dans deux ans.'),
  ('q-0623', 'Il faut beaucoup de temps pour devenir riche lentement, et c''est précisément pour cela que peu de gens le font.', 'Charlie Munger', 'finance', null, null, null, 'Munger pointe une contradiction humaine : la méthode lente fonctionne, et c''est précisément pour cela qu''elle est délaissée. Peu de gens acceptent un procédé fiable dont le résultat n''arrive pas avant longtemps.', 'Vérifie que ton plan est compatible avec ta patience réelle. Un bon plan qu''on abandonne au bout de six mois vaut moins qu''un plan moyen tenu dix ans.'),
  ('q-0624', 'Tout ce que je veux savoir, c''est où je vais mourir, comme ça je n''irai jamais.', 'Charlie Munger', 'finance', null, null, null, 'Munger décrit l''inversion : plutôt que de chercher comment réussir, il liste ce qui fait échouer et l''évite. C''est souvent plus simple, parce que les causes d''échec sont moins nombreuses et mieux connues que les recettes de succès.', 'Sur ton projet en cours, écris les cinq façons les plus probables de le faire échouer. Traiter cette liste te fera avancer davantage que chercher un levier de croissance supplémentaire.'),
  ('q-0625', 'L''investisseur avisé est un réaliste qui vend aux optimistes et achète aux pessimistes.', 'Benjamin Graham', 'finance', null, null, null, 'Graham décrit une position à contre-courant fondée sur le réalisme et non sur l''audace : l''optimisme collectif fait monter les prix au-dessus de la valeur, le pessimisme les fait descendre en dessous. Le réaliste se contente d''en tenir compte.', 'Face à un engagement, demande-toi si tu paies pour ce que la chose vaut ou pour ce qu''on en dit actuellement. La différence entre les deux est ta marge d''erreur.'),
  ('q-0626', 'L''ennemi principal de l''investisseur, c''est probablement lui-même.', 'Benjamin Graham', 'finance', null, null, null, 'Graham identifie la source principale des pertes : les décisions prises sous émotion. L''analyse peut être juste et le résultat mauvais simplement parce qu''on n''a pas tenu sa propre stratégie.', 'Tiens un journal de tes décisions importantes avec leur motif. Le relire est le seul moyen de repérer tes schémas de réaction — personne ne les voit sur le moment.'),
  ('q-0627', 'Le temps est l''ami des belles entreprises et l''ennemi des médiocres.', 'Warren Buffett', 'finance', null, 'Lettre aux actionnaires de Berkshire Hathaway', 1989, 'Le temps agit comme un révélateur, pas comme un remède. Une entreprise solide accumule pendant qu''on attend ; une entreprise fragile consomme sa trésorerie et sa réputation dans le même intervalle. Patienter n''améliore que ce qui était déjà bon.', 'Face à une situation qui stagne, demande-toi si attendre travaille pour toi ou contre toi. Si le temps aggrave le problème, la patience n''est pas de la sagesse, c''est du report.'),
  ('q-0628', 'Ne me dites pas ce que vous pensez, montrez-moi votre portefeuille.', 'Nassim Nicholas Taleb', 'finance', null, null, null, 'Taleb exige une preuve d''engagement : les opinions ne coûtent rien, la position prise en coûte. La question révèle qui assume réellement ce qu''il affirme.', 'Quand quelqu''un te donne un conseil engageant, demande-lui ce qu''il a fait lui-même dans cette situation. La réponse est plus instructive que le conseil.'),
  ('q-0629', 'La richesse, c''est ce que vous ne voyez pas : les voitures non achetées, les sacs non achetés.', 'Morgan Housel', 'finance', null, 'La Psychologie de l''argent', 2020, 'Housel définit la richesse par ce qui n''a pas été dépensé — donc par ce qui reste invisible. Ce qu''on voit chez les autres, ce sont leurs dépenses, pas leur patrimoine : la comparaison est structurellement faussée.', 'Cesse de te comparer aux signes extérieurs. Un train de vie visible indique une dépense, jamais une richesse.'),
  ('q-0630', 'Le plus grand dividende que l''argent puisse verser, c''est la maîtrise de votre temps.', 'Morgan Housel', 'finance', null, 'La Psychologie de l''argent', 2020, 'Housel désigne l''usage le plus rentable de l''argent : la maîtrise de son temps. Pouvoir choisir ce qu''on fait de ses journées est un rendement que la consommation ne procure pas.', 'Avant un achat important, demande-toi s''il augmente ou réduit ta liberté d''emploi du temps. Beaucoup de dépenses imposent ensuite de travailler pour les financer.'),
  ('q-0631', 'Ce ne sont pas les revenus qui font la richesse, c''est l''écart entre ce que vous gagnez et ce que vous dépensez.', 'Thomas J. Stanley', 'finance', null, null, null, 'Stanley identifie l''écart entre revenus et dépenses comme seule source de patrimoine. Le revenu élevé ne garantit rien s''il est absorbé par un train de vie proportionnel.', 'Calcule ton écart mensuel réel entre entrées et sorties. C''est ce nombre, et lui seul, qui construit ou non quelque chose.'),
  ('q-0632', 'Payez-vous en premier.', 'George S. Clason', 'finance', null, null, null, 'Clason énonce une règle d''ordre : prélever son épargne avant toute dépense, plutôt qu''espérer un solde. Ce qui vient en dernier ne vient jamais.', 'Programme un virement automatique le jour de ta paie. L''automatisme retire la décision mensuelle, qui est le vrai point de fuite.'),
  ('q-0633', 'Une partie de tout ce que vous gagnez vous appartient, à vous et à personne d''autre.', 'George S. Clason', 'finance', null, null, null, 'Clason affirme un droit sur une part de ses propres revenus, avant les créanciers et les besoins courants. La formule transforme l''épargne en dû plutôt qu''en effort de volonté.', 'Fixe un pourcentage — même faible — que tu ne dépenses jamais, quelles que soient les circonstances. C''est le principe qui compte, pas le montant de départ.'),
  ('q-0635', 'Le temps passé sur le marché bat le fait de vouloir choisir le bon moment.', 'Peter Lynch', 'finance', null, null, null, 'Lynch oppose la durée à la synchronisation. Rester présent longtemps produit un résultat régulier ; chercher le bon moment suppose de réussir deux paris successifs, sortir puis revenir.', 'Si tu envisages de sortir puis de revenir, écris à l''avance à quel signal tu reviendras. Sans ce critère, la sortie devient définitive par indécision.'),
  ('q-0636', 'Bien plus d''argent a été perdu par des investisseurs à essayer d''anticiper les corrections qu''à en subir.', 'Peter Lynch', 'finance', null, null, null, 'Lynch chiffre un coût invisible : l''argent perdu à éviter les baisses dépasse celui perdu en les traversant. Se protéger a un prix, souvent supérieur au risque évité.', 'Avant une mesure de protection, compare son coût permanent au risque qu''elle couvre. Beaucoup de précautions coûtent chaque mois pour un danger rare.'),
  ('q-0637', 'Il vaut mieux acheter une entreprise formidable à un prix correct qu''une entreprise correcte à un prix formidable.', 'Warren Buffett', 'finance', 'Tirée du bilan que Buffett dresse de ses vingt-cinq premières années à la tête de Berkshire, où il reconnaît avoir trop longtemps cherché la bonne affaire plutôt que la bonne entreprise.', 'Lettre aux actionnaires de Berkshire Hathaway, section « Mistakes of the First Twenty-Five Years »', 1989, 'Buffett résume ici sa propre correction de trajectoire : il a longtemps cherché des affaires bradées, avant d''admettre qu''une entreprise médiocre le reste, quel que soit le prix d''entrée. La qualité produit dans la durée ; la décote ne produit qu''une fois.', 'Quand tu arbitres entre le moins cher et le meilleur, regarde ce que tu vas devoir vivre avec pendant des années. Une remise se consomme au premier jour, un défaut t''accompagne à chaque utilisation.'),
  ('q-0638', 'Ce n''est pas le critique qui compte, ni celui qui montre comment l''homme fort a trébuché. Le mérite revient à celui qui est dans l''arène.', 'Theodore Roosevelt', 'leadership', 'Extrait du passage dit « L''homme dans l''arène », prononcé à la Sorbonne un an après avoir quitté la Maison-Blanche. Roosevelt y défend ceux qui agissent contre ceux qui commentent.', 'Discours « Citizenship in a Republic », Sorbonne, Paris', 1910, 'Roosevelt oppose celui qui commente à celui qui agit. La critique est confortable et sans risque ; l''action expose à l''échec public, ce qui lui donne sa valeur.', 'Avant de critiquer une décision, demande-toi si tu aurais accepté de la prendre. Cette question ne fait pas taire, elle rend la critique utile.'),
  ('q-0639', 'Faites ce que vous pouvez, avec ce que vous avez, là où vous êtes.', 'Theodore Roosevelt', 'leadership', null, null, null, 'Roosevelt supprime l''excuse des conditions. La formule ne nie pas les contraintes, elle refuse qu''elles servent d''autorisation à ne rien entreprendre : il reste toujours un premier pas possible avec les moyens du moment.', 'Prends le projet que tu remets à plus tard faute de moyens et identifie la version la plus modeste que tu peux lancer cette semaine. Elle t''apprendra plus que six mois d''attente.'),
  ('q-0640', 'Le meilleur dirigeant est celui qui a assez de bon sens pour choisir des gens capables, et assez de retenue pour ne pas se mêler de leur travail.', 'Theodore Roosevelt', 'leadership', null, null, null, 'Roosevelt définit le dirigeant par deux qualités opposées : le discernement pour choisir, et la retenue pour ne pas défaire ensuite ce choix en s''immisçant. La seconde est la plus rare, parce qu''elle demande de renoncer au contrôle.', 'Après avoir confié une mission, fixe un point d''étape et tiens-toi à cette échéance. Chaque intervention non prévue entre-temps signale que tu ne fais pas confiance à ta propre décision de recrutement.'),
  ('q-0641', 'La difficulté attire l''homme de caractère, car c''est en l''étreignant qu''il se réalise lui-même.', 'Charles de Gaulle', 'leadership', null, null, null, 'De Gaulle voit dans la difficulté un révélateur et un moyen : c''est en l''affrontant qu''on développe ce qu''on ne savait pas avoir. L''obstacle n''est pas un empêchement, c''est l''occasion de se constituer.', 'Quand tu as le choix entre deux missions, prends celle qui t''oblige à progresser. Le confort ne construit rien qui te serve ensuite.'),
  ('q-0642', 'On ne fait rien de grand sans de grands hommes, et ceux-ci le sont pour l''avoir voulu.', 'Charles de Gaulle', 'leadership', null, null, null, 'De Gaulle lie les réalisations aux personnes, et les personnes à leur volonté. Il écarte le déterminisme : ce n''est pas la naissance ou le talent qui font les grands hommes, c''est le fait de l''avoir voulu.', 'Cesse d''attendre de te sentir légitime. Ceux que tu admires ont commencé sans l''être davantage — la légitimité vient après l''engagement, jamais avant.'),
  ('q-0643', 'Le prix de la grandeur, c''est la responsabilité.', 'Winston Churchill', 'leadership', null, null, null, 'Churchill lie le rang à la charge : plus la position est élevée, plus les conséquences des décisions pèsent sur d''autres. La grandeur n''est pas un privilège, c''est ce qu''on accepte de porter.', 'Avant de rechercher plus de responsabilités, demande-toi si tu es prêt à assumer les erreurs de ceux que tu dirigeras. C''est la partie du poste qu''on voit le moins et qui coûte le plus.'),
  ('q-0644', 'Un chef est un marchand d''espérance.', 'Napoléon Bonaparte', 'leadership', null, null, null, 'Napoléon définit le chef par ce qu''il fournit : une raison de croire que l''effort mènera quelque part. Sans cette perspective, l''autorité ne produit que de l''obéissance passive.', 'Quand ton équipe traverse une passe difficile, décris précisément ce à quoi ressemble la sortie. L''espérance sans contenu ne tient pas plus de quelques semaines.'),
  ('q-0645', 'Ne demandez pas ce que votre pays peut faire pour vous, demandez ce que vous pouvez faire pour votre pays.', 'John F. Kennedy', 'leadership', 'Prononcé par un président de 43 ans, le plus jeune jamais élu, en pleine guerre froide et deux mois avant la création des Peace Corps qu''annonce cet appel.', 'Discours d''investiture, Washington', 1961, 'Kennedy inverse le rapport habituel entre l''individu et la collectivité : au lieu de demander ce qu''on peut recevoir, il propose de considérer ce qu''on peut apporter. C''est un renversement de posture, applicable bien au-delà de la politique.', 'Dans une organisation où tu attends quelque chose, commence par identifier ce que tu peux y apporter sans contrepartie. C''est presque toujours ce qui débloque le reste.'),
  ('q-0646', 'Le changement est la loi de la vie. Ceux qui ne regardent que le passé ou le présent manqueront à coup sûr l''avenir.', 'John F. Kennedy', 'leadership', null, null, null, 'Kennedy présente le changement comme une donnée, pas comme un choix. Ceux qui raisonnent uniquement sur ce qui existe ou a existé bâtissent des décisions sur un état qui aura disparu au moment de récolter.', 'Sur ta prochaine décision structurante, projette la situation à cinq ans plutôt qu''à aujourd''hui. Beaucoup de choix évidents dans le présent deviennent absurdes à cet horizon.'),
  ('q-0647', 'Les problèmes du monde ne peuvent être résolus par les sceptiques dont l''horizon se limite aux réalités visibles.', 'John F. Kennedy', 'leadership', null, null, null, 'Kennedy vise un scepticisme qui se limite au constat : refuser d''envisager ce qui n''existe pas encore garantit de ne rien créer. La lucidité est utile, l''incapacité à imaginer ne l''est pas.', 'Face à une idée nouvelle, oblige-toi à formuler ce qu''il faudrait pour qu''elle fonctionne avant de lister pourquoi elle échouera. L''ordre change complètement la conclusion.'),
  ('q-0648', 'L''effort et le courage ne suffisent pas sans but ni direction.', 'John F. Kennedy', 'leadership', null, null, null, 'Kennedy pose l''orientation comme condition d''efficacité de l''effort. Travailler dur sans direction produit de la fatigue et non des résultats : l''énergie ne compense jamais l''absence de cap.', 'Si tu te sens débordé sans avancer, le problème est probablement la direction, pas le rythme. Arrête-toi une heure pour reformuler l''objectif plutôt que d''accélérer.'),
  ('q-0649', 'Un dirigeant est un homme qui a besoin des autres.', 'Paul Valéry', 'leadership', null, null, null, 'Valéry définit le dirigeant par sa dépendance : il ne peut rien seul, ce qui fait de sa capacité à s''entourer et à faire travailler ensemble sa compétence principale.', 'Évalue-toi sur ta capacité à obtenir des résultats par d''autres, pas sur ta production personnelle. C''est le changement de métier que suppose la direction.'),
  ('q-0650', 'La qualité d''un dirigeant se mesure aux normes qu''il se fixe à lui-même.', 'Ray Kroc', 'leadership', null, null, null, 'Kroc situe l''exigence envers soi comme la source de l''exigence collective. Un dirigeant ne peut pas demander un niveau qu''il ne tient pas lui-même sans que l''écart soit remarqué.', 'Écris les trois standards que tu exiges de ton équipe et vérifie que tu les respectes. Chaque écart annule silencieusement la règle correspondante.'),
  ('q-0651', 'Les gens ne quittent pas des entreprises, ils quittent des managers.', 'Marcus Buckingham', 'leadership', null, null, null, 'Buckingham identifie la cause réelle des départs : la relation directe avec le responsable, plus que la marque, le salaire ou les locaux. C''est un facteur local, donc corrigeable.', 'Quand quelqu''un démissionne, cherche ce qui s''est passé dans sa relation managériale. La réponse officielle porte rarement sur ce point.'),
  ('q-0652', 'Mettez d''abord les bonnes personnes dans le bus, ensuite décidez où aller.', 'Jim Collins', 'leadership', null, 'De la performance à l''excellence', 2001, 'Collins inverse l''ordre habituel : constituer la bonne équipe avant de fixer la direction. Une équipe solide s''adapte à un changement de cap, une direction parfaite ne compense pas une mauvaise équipe.', 'Avant de lancer un projet, assure-toi d''avoir les bonnes personnes. Le temps passé à recruter est presque toujours rentabilisé par la suite.'),
  ('q-0653', 'Commencez avec la fin en tête.', 'Stephen R. Covey', 'leadership', null, 'Les 7 habitudes de ceux qui réalisent tout ce qu''ils entreprennent', 1989, 'Covey propose de raisonner à rebours : définir l''aboutissement avant de choisir les moyens. Sans cette clarté, chaque décision intermédiaire se prend au hasard des circonstances.', 'Avant un projet, écris à quoi ressemble le résultat le jour où il est terminé. Ce texte devient le critère qui tranche toutes les questions suivantes.'),
  ('q-0654', 'Cherchez d''abord à comprendre, ensuite à être compris.', 'Stephen R. Covey', 'leadership', null, 'Les 7 habitudes de ceux qui réalisent tout ce qu''ils entreprennent', 1989, 'Covey inverse l''ordre habituel d''une conversation : on cherche d''ordinaire à se faire comprendre avant d''écouter, ce qui produit deux monologues. Comprendre d''abord change ce qu''on aura à dire.', 'Dans ton prochain désaccord, reformule la position de l''autre jusqu''à ce qu''il la valide avant d''exposer la tienne. La suite de l''échange en est transformée.'),
  ('q-0656', 'Recrutez lentement, licenciez vite.', 'Ray Dalio', 'leadership', null, null, null, 'Dalio inverse les rythmes habituels. Un recrutement raté coûte des mois et se propage à l''équipe, donc il mérite du temps ; une fois l''erreur constatée, chaque semaine de délai aggrave le coût pour tout le monde, y compris pour la personne concernée.', 'Si tu doutes depuis plus de trois mois sur quelqu''un, le sujet n''est plus le doute mais ta décision. Traite-le avec égards, mais traite-le.'),
  ('q-0657', 'Une organisation excellente n''est pas celle où il n''y a pas de problèmes, c''est celle où les problèmes remontent vite.', 'Ray Dalio', 'leadership', null, null, null, 'Dalio définit la qualité d''une organisation par sa vitesse de remontée d''information, pas par l''absence de problèmes. Une organisation sans problème visible est généralement une organisation où l''on n''ose pas les signaler.', 'Mesure le temps entre l''apparition d''un problème et le moment où tu l''apprends. Le raccourcir vaut mieux que d''essayer d''avoir moins de problèmes.'),
  ('q-0658', 'La transparence radicale n''est pas confortable, mais elle est efficace.', 'Ray Dalio', 'leadership', null, null, null, 'Dalio assume un arbitrage : la transparence crée de l''inconfort à court terme, mais elle évite les non-dits qui coûtent bien plus cher ensuite. Le confort du silence est payé plus tard, avec intérêts.', 'Sur un sujet que tout le monde évite, dis-le explicitement en réunion. L''inconfort de cinq minutes remplace souvent des mois de contournement.'),
  ('q-0659', 'Notre culture, c''est la liberté et la responsabilité.', 'Reed Hastings', 'leadership', null, null, null, 'Hastings associe deux termes qui se conditionnent : la liberté n''est tenable que si chacun assume les conséquences de ses choix. Sans responsabilité, elle devient du laisser-faire.', 'Avant d''accorder plus d''autonomie, précise ce dont la personne devra rendre compte. C''est cette clarté qui rend la liberté possible.'),
  ('q-0660', 'Le talent dense attire le talent dense.', 'Reed Hastings', 'leadership', null, null, null, 'Hastings décrit un effet d''attraction : les gens compétents veulent travailler avec des gens compétents. La qualité de l''équipe devient donc son propre argument de recrutement.', 'Traite chaque recrutement comme un signal envoyé aux suivants. Une exception à la baisse rend les recrutements ultérieurs plus difficiles.'),
  ('q-0661', 'L''empathie n''est pas un luxe pour un dirigeant, c''est un outil de travail.', 'Satya Nadella', 'leadership', null, null, null, 'Nadella traite l''empathie comme une compétence opérationnelle : comprendre ce que vit l''autre est ce qui permet de concevoir un produit utile et de diriger une équipe réelle. Ce n''est pas une qualité morale ajoutée.', 'Avant une décision qui affecte d''autres personnes, formule leur point de vue à voix haute. Si tu n''y arrives pas, tu n''as pas assez d''informations pour décider.'),
  ('q-0662', 'Notre secteur ne respecte pas la tradition, il ne respecte que l''innovation.', 'Satya Nadella', 'leadership', null, null, null, 'Nadella décrit un secteur où l''ancienneté ne protège de rien : une position acquise ne vaut que tant qu''elle reste la meilleure réponse. L''histoire d''une entreprise n''est pas un actif défendable.', 'Ne t''appuie pas sur ton antériorité comme argument. Demande-toi ce que tu apportes aujourd''hui à quelqu''un qui découvrirait ton marché sans te connaître.'),
  ('q-0663', 'Le leadership, c''est aussi savoir quand se taire.', 'Indra Nooyi', 'leadership', null, null, null, 'Nooyi inclut le silence dans les compétences de direction. Parler en premier ferme le débat, occuper l''espace prive l''équipe de la sienne — se taire est parfois l''acte de leadership le plus utile.', 'En réunion, parle en dernier sur les sujets où tu as un avis fort. Tu obtiendras des positions qui n''auraient jamais été exprimées autrement.'),
  ('q-0664', 'Supposez toujours la bonne intention chez votre interlocuteur.', 'Indra Nooyi', 'leadership', null, null, null, 'Nooyi propose un principe de lecture : partir du postulat que l''autre agit de bonne foi. Cela évite les conflits fondés sur des malentendus et change la qualité des échanges.', 'Face à un comportement qui t''agace, formule d''abord une explication bienveillante plausible. Si elle tient, la conversation qui suit sera très différente.'),
  ('q-0665', 'Si vous voulez aller vite, allez seul. Si vous voulez aller loin, allez ensemble.', 'Proverbe africain', 'leadership', null, null, null, 'Le proverbe oppose deux objectifs : la vitesse, qu''on obtient seul en évitant la coordination, et la distance, qui suppose un collectif capable de se relayer. Il faut choisir selon le trajet.', 'Avant de lancer un projet, décide s''il s''agit d''un sprint ou d''un marathon. Le mode d''organisation qui convient à l''un handicape l''autre.'),
  ('q-0667', 'La seule chose que nous devons craindre, c''est la crainte elle-même.', 'Franklin D. Roosevelt', 'leadership', 'Premier discours d''investiture, au creux de la Grande Dépression : un adulte américain sur quatre est sans emploi et les banques ferment les unes après les autres.', 'Premier discours d''investiture', 1933, 'Roosevelt décrit un mécanisme d''auto-aggravation : la peur pousse à des décisions défensives qui provoquent ce qu''on redoutait. Dans une panique bancaire, c''est la peur du retrait qui vide les banques.', 'Face à un risque, distingue la menace réelle des réactions qu''elle déclenche. Souvent, le coût vient de la panique en chaîne, pas de l''événement.'),
  ('q-0668', 'Un bon plan exécuté aujourd''hui vaut mieux qu''un plan parfait exécuté la semaine prochaine.', 'George S. Patton', 'leadership', null, null, null, 'Patton arbitre entre qualité et délai : dans une situation qui évolue, un plan appliqué maintenant s''adapte, tandis qu''un plan parfait arrive après que la situation a changé.', 'Quand tu peaufines un plan depuis plus d''une semaine, lance-le en l''état. Les ajustements se feront au contact, avec de meilleures informations.'),
  ('q-0669', 'Ne dites pas aux gens comment faire les choses. Dites-leur quoi faire et laissez-les vous surprendre par leur ingéniosité.', 'George S. Patton', 'leadership', 'Principe de commandement d''un général réputé pour son exigence, qui tenait pourtant à laisser l''initiative à ses subordonnés.', null, null, 'Patton, réputé exigeant, sépare l''objectif de la méthode : imposer le comment supprime l''ingéniosité de ceux qui exécutent, alors que c''est précisément ce qu''on attend d''eux.', 'Formule tes demandes en résultat attendu plutôt qu''en marche à suivre. Tu recevras parfois mieux que ce que tu avais imaginé.'),
  ('q-0670', 'Restez affamés, restez fous.', 'Steve Jobs', 'mindset', 'Jobs conclut son discours en citant la formule d''adieu du dernier numéro du Whole Earth Catalog, publication qui l''a marqué dans sa jeunesse — la phrase n''est donc pas de lui à l''origine.', 'Discours de remise des diplômes, Université Stanford (citant le Whole Earth Catalog, 1974)', 2005, 'Jobs oppose deux appétits qu''on perd habituellement avec le succès : la faim, qui empêche de se croire arrivé, et la folie, qui autorise à tenter ce que les gens raisonnables écartent d''emblée.', 'Repère la décision que tu n''as pas prise parce qu''elle paraissait déraisonnable. Demande-toi si elle l''est vraiment, ou si elle est seulement inhabituelle dans ton entourage.'),
  ('q-0671', 'On ne peut pas relier les points en regardant devant soi, seulement en regardant en arrière.', 'Steve Jobs', 'mindset', 'Jobs y raconte avoir suivi, sans but apparent, un cours de calligraphie après avoir quitté l''université — devenu dix ans plus tard la typographie soignée du Macintosh.', 'Discours de remise des diplômes, Université Stanford', 2005, 'Jobs décrit une cohérence qui n''apparaît qu''après coup : les expériences apparemment inutiles finissent par se relier, mais seulement rétrospectivement. Cela justifie de suivre sa curiosité sans plan d''usage.', 'Ne renonce pas à un apprentissage parce que tu n''en vois pas l''usage immédiat. Les compétences les plus différenciantes viennent souvent de ces détours.'),
  ('q-0672', 'Je n''ai pas échoué. J''ai simplement trouvé dix mille façons qui ne fonctionnent pas.', 'Thomas Edison', 'mindset', 'Réponse d''Edison à un journaliste qui lui demandait ce que ça faisait d''avoir échoué des milliers de fois avant de mettre au point la lampe à incandescence.', null, null, 'Edison reformule l''échec en résultat : chaque tentative infructueuse élimine une possibilité, ce qui constitue une information et non une perte.', 'Tiens la liste de ce que tu as éliminé sur un problème difficile. Elle transforme une série d''échecs en progression mesurable.'),
  ('q-0673', 'La vie se rétrécit ou s''élargit à proportion de notre courage.', 'Anaïs Nin', 'mindset', null, null, null, 'Nin établit une proportion directe entre courage et étendue de la vie. Chaque renoncement rétrécit le champ des possibles, chaque audace l''élargit — le processus est continu.', 'Repère une chose que tu as cessé de faire par appréhension. Sa reprise, même partielle, élargit immédiatement ton périmètre.'),
  ('q-0674', 'Vous êtes la moyenne des cinq personnes que vous fréquentez le plus.', 'Jim Rohn', 'mindset', null, null, null, 'Rohn décrit un effet d''environnement : les habitudes, le niveau d''exigence et les ambitions de l''entourage deviennent notre référence de normalité, sans qu''on l''ait décidé.', 'Ajoute à ton entourage une personne dont le niveau te met légèrement mal à l''aise. C''est le moyen le plus rapide de déplacer ta propre norme.'),
  ('q-0675', 'Ne souhaitez pas que ce soit plus facile, souhaitez d''être meilleur.', 'Jim Rohn', 'mindset', null, null, null, 'Rohn déplace la demande : espérer des conditions plus faciles rend dépendant des circonstances, chercher à devenir meilleur rend capable de les affronter. Seul le second est sous contrôle.', 'Face à une difficulté récurrente, demande-toi quelle compétence te la rendrait gérable. Travaille celle-là plutôt que d''attendre que la difficulté disparaisse.'),
  ('q-0676', 'Ce que l''esprit peut concevoir et croire, il peut le réaliser.', 'Napoleon Hill', 'mindset', null, null, null, 'Hill pose la conception et la conviction comme conditions préalables à la réalisation. Ce n''est pas une promesse de résultat automatique : ce sont les deux premières étapes, sans lesquelles rien ne commence.', 'Écris précisément ce que tu veux obtenir — pas l''intention, le résultat. L''imprécision à cette étape se paie ensuite à chaque décision qui suit.'),
  ('q-0677', 'Devenir vaut mieux qu''être.', 'Carol Dweck', 'mindset', null, null, null, 'Dweck oppose l''état à la trajectoire : se définir par ce qu''on est fige, se définir par ce qu''on devient autorise l''erreur et l''apprentissage. C''est le fondement de l''état d''esprit de développement.', 'Remplace « je ne suis pas bon à ça » par « je ne suis pas encore bon à ça ». La formulation change ce que tu t''autorises à tenter.'),
  ('q-0678', 'Rien dans la vie n''a autant d''importance que vous ne le pensez pendant que vous y pensez.', 'Daniel Kahneman', 'mindset', null, null, null, 'Kahneman décrit un biais d''attention : ce sur quoi on se concentre paraît démesurément important pendant qu''on y pense. L''effet explique bien des décisions disproportionnées.', 'Avant de trancher sous le coup d''une préoccupation, attends un jour. L''importance apparente du sujet diminue presque toujours.'),
  ('q-0679', 'J''ai raté plus de neuf mille tirs dans ma carrière. C''est pour cela que je réussis.', 'Michael Jordan', 'mindset', 'Texte d''une publicité Nike entièrement consacrée à ses échecs, diffusée alors qu''il était déjà considéré comme le meilleur joueur de l''histoire.', 'Publicité Nike « Failure »', 1997, 'Jordan pose une causalité, pas une consolation : la répétition des tentatives ratées est ce qui a construit sa réussite. Le nombre d''échecs mesure le volume d''essais, donc l''exposition aux occasions de réussir.', 'Compte le nombre de tentatives que tu fais réellement sur un objectif — appels, candidatures, propositions. Si le chiffre est bas, ton problème est le volume, pas la qualité.'),
  ('q-0680', 'On rate cent pour cent des tirs qu''on ne tente pas.', 'Wayne Gretzky', 'mindset', null, null, null, 'Gretzky énonce une certitude arithmétique : une tentative non faite a zéro chance d''aboutir. Toutes les autres, même improbables, ont une probabilité supérieure.', 'Compte les demandes que tu n''as pas formulées ce mois-ci par crainte du refus. Chacune était une occasion à probabilité nulle.'),
  ('q-0681', 'Je détestais chaque minute d''entraînement, mais je me disais : souffre maintenant et vis le reste de ta vie en champion.', 'Muhammad Ali', 'mindset', null, null, null, 'Ali décrit un arbitrage entre deux souffrances : celle de l''entraînement, courte et choisie, et celle du regret, longue et subie. Il ne prétend pas aimer l''effort, il en accepte le prix.', 'Quand une discipline te coûte, compare-la à ce que coûterait de ne pas la tenir sur dix ans. La comparaison rend l''effort du jour plus supportable.'),
  ('q-0682', 'L''homme qui n''a pas d''imagination n''a pas d''ailes.', 'Muhammad Ali', 'mindset', null, null, null, 'Ali relie l''imagination à la capacité de dépasser sa condition : sans représentation de ce qui pourrait être, on reste borné à ce qui est. L''image des ailes désigne cette capacité de projection.', 'Avant de fixer un objectif réaliste, autorise-toi à décrire la version idéale. Tu pourras réduire ensuite, mais tu ne pourras pas viser plus haut que ce que tu as su imaginer.'),
  ('q-0683', 'Le job n''est pas fini.', 'Kobe Bryant', 'mindset', null, null, null, 'Bryant refuse de célébrer avant la fin. Se satisfaire d''une étape intermédiaire relâche l''effort exactement au moment où il faudrait le maintenir — la victoire partielle est le piège.', 'Après une réussite intermédiaire, redéfinis immédiatement l''étape suivante. Le relâchement d''après-succès coûte plus cher que la difficulté elle-même.'),
  ('q-0684', 'Les gens oublieront ce que vous avez dit et ce que vous avez fait, mais jamais ce que vous leur avez fait ressentir.', 'Maya Angelou', 'mindset', null, null, null, 'Angelou hiérarchise ce qui reste : les arguments s''oublient, les actes se brouillent, l''émotion associée persiste. Cela explique pourquoi une relation professionnelle se juge sur le ressenti bien plus que sur les faits.', 'Après un échange difficile, demande-toi dans quel état tu as laissé l''autre. C''est cette trace, et non ton argumentaire, qui déterminera sa réaction la prochaine fois.'),
  ('q-0685', 'Rien ne fonctionnera si vous ne le faites pas.', 'Maya Angelou', 'mindset', null, null, null, 'Formule minimale sur l''exécution : aucune méthode, aucun outil, aucun plan ne produit de résultat sans quelqu''un qui s''y met. Angelou coupe court à la recherche de la solution parfaite comme substitut à l''action.', 'Si tu compares des méthodes depuis plus d''une semaine, choisis la moins mauvaise et commence. Le temps d''exécution t''apprendra plus que la comparaison.'),
  ('q-0686', 'Aujourd''hui est dur, demain sera pire, mais après-demain sera magnifique. La plupart abandonnent le soir du deuxième jour.', 'Jack Ma', 'mindset', null, null, null, 'Jack Ma décrit la courbe réelle d''un projet difficile : ça empire avant de s''améliorer, et l''abandon se produit systématiquement au creux. Connaître la forme de la courbe permet de ne pas confondre le creux avec la fin.', 'Quand tout se dégrade, vérifie si c''est une trajectoire ou un accident. Si les fondamentaux tiennent, le creux fait partie du chemin — c''est là que la majorité s''arrête.'),
  ('q-0687', 'Chaque action que vous entreprenez est un vote pour la personne que vous voulez devenir.', 'James Clear', 'mindset', null, 'Un rien peut tout changer', 2018, 'Clear décrit l''identité comme un cumul d''actes : chaque action confirme ou infirme l''idée qu''on se fait de soi. Le changement durable passe par cette accumulation, pas par la motivation.', 'Choisis l''identité que tu veux renforcer, puis identifie l''action minimale qui la prouve chaque jour. La régularité compte plus que l''intensité.'),
  ('q-0688', 'La passion est courante, la persévérance est rare.', 'Angela Duckworth', 'mindset', null, null, null, 'Duckworth distingue une ressource abondante d''une ressource rare. Beaucoup de gens sont passionnés par quelque chose ; très peu maintiennent cet engagement quand l''enthousiasme retombe. C''est la seconde qualité qui discrimine.', 'Ne choisis pas ta voie sur l''intensité de ton envie initiale, mais sur ce que tu es prêt à faire quand elle sera retombée.'),
  ('q-0689', 'Le talent, c''est le potentiel. L''effort, c''est ce qui le transforme en résultat.', 'Angela Duckworth', 'mindset', null, null, null, 'Duckworth pose une équation en deux temps : le talent définit un plafond potentiel, l''effort détermine quelle fraction en est atteinte. Deux personnes de talent inégal peuvent donc obtenir l''inverse de ce qu''on attend.', 'Cesse d''évaluer les gens sur leur potentiel apparent. Regarde ce qu''ils produisent réellement sur six mois — c''est la seule mesure qui intègre l''effort.'),
  ('q-0691', 'Tu as pouvoir sur ton esprit, pas sur les évènements extérieurs. Comprends cela et tu trouveras la force.', 'Marc Aurèle', 'mindset', null, null, null, 'Marc Aurèle délimite le périmètre de contrôle : les événements extérieurs échappent, le jugement qu''on porte reste accessible. La force vient de concentrer l''effort là où il produit quelque chose.', 'Quand une situation t''échappe, écris ce qui dépend encore de toi — même minime. Cette liste est ton vrai terrain d''action.'),
  ('q-0692', 'Nous souffrons plus souvent en imagination qu''en réalité.', 'Sénèque', 'mindset', null, 'Lettres à Lucilius, lettre 13', null, 'Sénèque observe que l''anticipation anxieuse coûte plus cher que l''événement lui-même, parce qu''elle se répète indéfiniment alors que le fait, lui, n''arrive qu''une fois — et souvent pas du tout.', 'Face à une inquiétude tenace, écris le pire scénario réaliste et ce que tu ferais s''il survenait. Avoir le plan écrit fait presque toujours retomber la charge mentale.'),
  ('q-0693', 'Ce n''est pas ce qui t''arrive qui compte, mais la façon dont tu y réagis.', 'Épictète', 'mindset', null, null, null, 'Formulation stoïcienne du contrôle : les événements sont extérieurs, la réponse est intérieure. C''est la seule part sur laquelle on peut travailler, et elle suffit à changer l''issue.', 'Après une mauvaise nouvelle, accorde-toi un délai avant de répondre. C''est dans ce délai que la réaction se transforme en décision.'),
  ('q-0694', 'Ne cherche pas que les évènements arrivent comme tu veux, mais veuille les évènements comme ils arrivent.', 'Épictète', 'mindset', null, 'Manuel d''Épictète, VIII', null, 'Épictète propose un renversement radical : plutôt que d''épuiser son énergie à vouloir plier le réel, accorder sa volonté à ce qui advient. Ce n''est pas de la résignation mais une économie d''effort.', 'Sur une situation que tu ne peux pas changer, cesse de la contester et demande-toi ce qu''elle rend possible. Tu récupères l''énergie que la lutte consommait.'),
  ('q-0695', 'Le premier pas n''emmène pas là où vous voulez aller, mais il vous sort de là où vous êtes.', 'James Clear', 'mindset', null, null, null, 'Clear décrit la fonction réelle du premier pas : il ne rapproche pas beaucoup du but, mais il fait sortir de l''immobilité. C''est ce déblocage qui compte, pas la distance parcourue.', 'Quand tu es bloqué, fais l''action la plus petite possible sans te soucier de son utilité. Sortir de l''arrêt est le seul objectif de ce premier geste.'),
  ('q-0696', 'Connaître les autres, c''est sagesse. Se connaître soi-même, c''est sagesse supérieure.', 'Lao Tseu', 'mindset', null, 'Tao Tö King, chapitre 33', null, 'Lao Tseu hiérarchise deux savoirs. Comprendre les autres permet d''agir efficacement avec eux ; se comprendre soi-même conditionne tout le reste, car nos angles morts faussent aussi la lecture d''autrui.', 'Demande à deux personnes de confiance ce qu''elles voient chez toi et que tu ne vois pas. C''est le seul moyen d''accéder à ce qui, par définition, t''échappe.'),
  ('q-0697', 'Le succès, c''est de tomber sept fois et de se relever huit.', 'Proverbe japonais', 'mindset', null, null, null, 'Le proverbe compte un relèvement de plus que de chutes : ce qui compte n''est pas d''éviter de tomber, mais de finir debout. La persistance prime sur la performance.', 'Ne mesure pas ta constance à l''absence d''interruption mais à ta rapidité de reprise. C''est ce délai qui fait la différence sur un an.'),
  ('q-0699', 'Ce qui ne nous tue pas nous rend plus forts.', 'Friedrich Nietzsche', 'mindset', null, 'Le Crépuscule des idoles', 1888, 'Nietzsche décrit un renforcement par l''épreuve, à condition d''y survivre — la formule contient sa propre limite. Ce n''est pas un éloge de la souffrance mais un constat sur ce qui reste après.', 'Après une période difficile, note ce que tu sais désormais gérer et qui t''aurait effrayé avant. C''est le gain concret, à distinguer du coût.'),
  ('q-0700', 'Celui qui a un pourquoi qui lui tient lieu de but peut supporter presque n''importe quel comment.', 'Friedrich Nietzsche', 'mindset', null, 'Le Crépuscule des idoles', 1888, 'Nietzsche relie l''endurance au sens : disposer d''une raison suffisante rend supportable presque n''importe quelle modalité. La difficulté n''est pas absolue, elle dépend de ce à quoi elle sert.', 'Quand une tâche te pèse, reformule à quoi elle sert précisément. Si tu n''y arrives pas, le problème n''est pas la charge mais l''absence de finalité.'),
  ('q-0701', 'La plus grande aventure, c''est de vivre la vie de ses rêves.', 'Oprah Winfrey', 'mindset', null, null, null, 'Winfrey qualifie d''aventure ce qu''on présente souvent comme un confort. Vivre selon ses propres choix suppose de renoncer à des sécurités, ce qui en fait un risque assumé plutôt qu''une facilité.', 'Identifie une chose que tu fais uniquement parce qu''elle est sûre. Demande-toi ce qu''elle te coûte réellement, au-delà de ce qu''elle te garantit.'),
  ('q-0702', 'Transformez vos blessures en sagesse.', 'Oprah Winfrey', 'mindset', null, null, null, 'Winfrey décrit une transformation qui n''est pas automatique : une blessure ne devient sagesse que par le travail d''en tirer quelque chose. Sans ce travail, elle reste une blessure.', 'Prends une difficulté passée et formule ce qu''elle t''a appris sous forme de règle. Tant que tu ne peux pas l''écrire, l''expérience n''est pas encore convertie.'),
  ('q-0703', 'Échouer, ce n''est pas ne pas réussir, c''est ne pas essayer.', 'Sara Blakely', 'mindset', null, null, null, 'Blakely redéfinit l''échec : ce n''est pas de ne pas atteindre son but, c''est de ne pas avoir tenté. Cette définition déplace le critère de jugement du résultat vers l''engagement, seul élément réellement sous contrôle.', 'Juge tes semaines au nombre de tentatives réelles, pas au nombre de réussites. C''est la seule métrique qui ne dépende pas des autres.'),
  ('q-0705', 'La perfection est atteinte non pas lorsqu''il n''y a plus rien à ajouter, mais lorsqu''il n''y a plus rien à retirer.', 'Antoine de Saint-Exupéry', 'mindset', 'Saint-Exupéry y parle de la conception des avions : la beauté d''une machine vient de tout ce qu''on a fini par lui retirer.', 'Terre des hommes', 1939, 'Saint-Exupéry, qui parle de conception d''avions, définit la perfection par soustraction et non par accumulation. Ajouter est facile et rassurant ; retirer demande de savoir ce qui est essentiel.', 'Sur ton produit ou ton offre, cherche ce que tu peux supprimer sans rien perdre. C''est plus difficile et plus rentable que d''ajouter une fonctionnalité.'),
  ('q-0707', 'On ne subit pas l''avenir, on le fait.', 'Georges Bernanos', 'mindset', null, null, null, 'Bernanos oppose deux rapports au futur : le subir comme une donnée, ou le construire comme un résultat. Le choix entre les deux est lui-même une décision quotidienne.', 'Repère un aspect de ta situation que tu décris comme inévitable. Vérifie s''il l''est réellement ou si tu as simplement cessé d''agir dessus.'),
  ('q-0709', 'Le pessimiste se plaint du vent, l''optimiste espère qu''il va changer, le réaliste ajuste ses voiles.', 'William Arthur Ward', 'mindset', null, null, null, 'Ward décrit trois attitudes face à la même contrainte : se plaindre, espérer, s''adapter. Seule la troisième produit un mouvement, les deux autres attendent que la situation change.', 'Face à une contrainte durable, cesse d''attendre qu''elle disparaisse et adapte ton dispositif. C''est la seule des trois options qui te fasse avancer.'),
  ('q-0710', 'Le doute est le commencement de la sagesse.', 'Aristote', 'mindset', null, null, null, 'Le doute est présenté comme point de départ, non comme faiblesse : c''est en cessant de tenir une chose pour acquise qu''on commence à l''examiner. La certitude, elle, arrête l''enquête avant qu''elle commence.', 'Prends une conviction que tu n''as jamais remise en question dans ton activité. Cherche activement ce qui la contredirait — c''est là que se trouvent les angles morts.'),
  ('q-0711', 'Nous sommes ce que nous faisons de manière répétée. L''excellence n''est donc pas un acte mais une habitude.', 'Will Durant', 'mindset', 'Souvent attribuée à Aristote : c''est en réalité le résumé qu''en fait Will Durant dans son ouvrage de vulgarisation. L''attribution ici est la bonne.', 'Histoire de la philosophie', 1926, 'Durant, résumant Aristote, situe l''excellence dans la répétition plutôt que dans la performance ponctuelle. Ce qu''on fait habituellement définit ce qu''on est, pas ce qu''on réussit exceptionnellement.', 'Choisis une pratique quotidienne cohérente avec ce que tu veux devenir. C''est l''accumulation qui construit, pas l''exploit isolé.'),
  ('q-0712', 'Tout le monde savait que c''était impossible. Il est venu un imbécile qui ne le savait pas et qui l''a fait.', 'Marcel Pagnol', 'mindset', null, null, null, 'Pagnol décrit un mécanisme réel : le consensus sur l''impossibilité empêche d''essayer, donc empêche de découvrir que c''était possible. L''ignorance de l''obstacle peut être un avantage.', 'Face à un « tout le monde sait que ça ne marche pas », demande sur quoi repose cette certitude. Souvent, personne n''a réellement testé depuis longtemps.')
